with v(numero,viejo,nuevo,sec) as (values
(154,'d1180af4546070be59b30a299b206abd','18be509051e0af5aa53b38172c17d08a',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Ìwòrì habla de una buena fortuna excepcional que llega a la persona, y explica cómo el buitre alcanzó su lugar sagrado en Ifá. El éxito material llegará por la acción espiritual. Pide ofrendar para vencer a los enemigos y preguntar qué acepta su Orí."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera los frutos de un esfuerzo largo (relato de Ajétunmobi).", "Teme que otros quieran quitarle un puesto o un beneficio.", "Necesita protección frente a quien se le opone (relato del buitre Igún)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Dinero que llega del mar y de la laguna.", "Ser intocable para los enemigos, como el buitre.", "Victoria sobre muchos detractores.", "Que la ofrenda sea aceptada."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El cambio repentino lleva a la transformación. (Este odu habla de la riqueza inesperada, especialmente abundancia que viene como resultado de alguna forma de trabajar con uno mismo o creatividad).", "origen_id": "08cfb0668914f15a6c1b2e3d"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Muchos detractores que lo atacan.", "Que lo traten como a cualquiera y quieran 'comérselo'."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino repentino lleva al conflicto (Este odu habla de las consecuencias negativas del fracaso de seguir tabú).", "origen_id": "270d32725add81da3aff3327"}]}, {"titulo": "Enseñanza principal", "texto": "Mientras no vean a Olúmọ, nadie podrá comerse al buitre: su ofrenda de kola llegó hasta Olódùmarè, y Èṣù lo protege porque ofrendó."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀sá'wòri habla de la excepcional buena fortuna que viene al cliente. También explica cómo el buitre alcanzó su sagrada posición en Ifá.", "origen_id": "4eed9981edf8da0f1c7f0867"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ajétunmobi y la fortuna del mar. Temigbusi le dijo a Ajétunmobi que su fortuna venía del mar y de la laguna y que el dinero llegaba a su casa. Él sonrió: '¿No sabes por lo que me he estado esforzando?'. Ofreció una carnera, palomas, plátanos maduros pequeños y 44,000 cauríes, y le dieron una parte de los plátanos para que se los comiera; puede comerlos a menudo.", "El buitre y Olúmọ. La gente se reunió porque quería comerse al buitre como a los demás pájaros, y mandaron a Ọmọ, un emisario sabio, al cielo a preguntar si se podía. Al buitre le pidieron un paquete grande de kola, una carnera y 8,600 cauríes. Ofreció. Ọmọ entregó el mensaje a Olódùmarè, que estaba ocupado y le pidió que le trajera kola. Ọmọ bajó, y en el cruce entre la tierra y el cielo encontró, a los pies de Èṣù, la kola que había ofrecido el buitre, y se la llevó a Olódùmarè. Tiempo después el buitre fue al cielo de visita, Olódùmarè le convidó de esa kola, y el buitre reconoció la suya y contó su historia. Olódùmarè dijo: 'Tu ofrenda fue aceptada. Ọmọ se quedará en el cielo y tú volverás a la tierra; mientras no vean a Ọmọ, no podrán matarte'. Desde entonces se dice: 'Si no vemos a Olúmọ, no podemos comernos al buitre'.", "Ṣàngó grita Ọ̀sá pàá. Ṣàngó, Olúkòso Làlú, estaba rodeado de detractores y preguntó si los vencería a todos. Ofreció con valor y bastante dinero. Cuando lo atacaron, gritó con un trueno: '¡Ọ̀sá pàá!', y todos temblaron; volvió a gritar: '¡Ìwòrì wàràràrà!'. Así saluda desde el cielo a los dos sacerdotes que le marcaron la ofrenda. Venció.", "Sóowò y la rata gigante. Las cosas de Sóowò no prosperaban. Le dijeron que comprara una rata gigante en el mercado y la sostuviera en las manos durante la ofrenda: la rata en su mano haría aceptable la ofrenda. Lo hizo y la vida le fue grata."], "pasajes": [{"titulo": "Verso 154.1", "texto": "Temigbusi: adivinó Ifá para Ajétunmobi.\nEl predijo: \"para Ajetunmobi\nla buena fortuna proviene del mar,\nla buena fortuna proviene de la laguna\"\n\"El dinero está viniendo para su casa\".\nSonriendo él miró al Babaláwo y dijo:\n¿Acaso no sabes por lo que me he estado esforzando?\nLe fue aconsejado hacer sacrificio\npara obtener la felicidad completa y el bienestar.\nSacrificio: carnera, palomas,\nplátanos\nmaduros pequeños y 44.000 cowries.\nÉl escuchó y ejecutó el sacrificio.\nA él le dieron una parte de los plátanos que ofreció\ny fue instruido para que se los comiera.\nLe fue dicho que podía comer\nplátanos pequeños maduros frecuentemente.", "comentario": "plátano: MUSA SAPIENTUM var. paradisiaca, Musaceae.", "origen_id": "21dd0a415f46594a7d0e6c2b"}, {"titulo": "Verso 154.2", "texto": "Ọ̀sá woo,\nÌwòrì woo,\nadivinó Ifá para el buitre (lgún),\ncuando todo el mundo se reunió porque querian comerse a lgún.\nEllos enviaron a Ọmo (un emisario sabio) al cielo para averiguar.\nPor otro lado, los adivinos aconsejaron a lgún sacrificar:\nun paquete de nuez de kola (gran cantidad),\nuna carnera y 8.600 cowries,\npara prevenir de que sus enemigos se lo comieran,\ncomo a los otros pájaros.\nEl escuchó el aviso e hizo el sacrificio.\nCuando Ọmo arribó al cielo,\nél entregó el mensaje del pueblo a Olódùmarè.\nOlódùmarè dijo que él no era capaz de responder\nen ese momento porque estaba muy ocupado\ny que necesitaba algún obi para completar su empeño.\nÉl por lo tanto ordenó a Ọmp ir y buscar obi\nỌmo rápidamente fue de vuelta a la tierra a buscar obi.\nCuando él estuvo en el cruce entre la tierra y el cielo,\nencontró al pie de Eṣú los obi\nque lgún había ofrecido como sacrificio.\nEl tomó el obi para Olódùmarè.\nDespués de un tiempo,\nel Igún fue al cielo a visitar a Olódùmarè,\nquien lo entretuvo con algunos de los obi\nque Ọmo le había traído.\nIgún examinó el obi y dijo que esos obi se parecian\na los que él había sacrificado el otro día.\nEntonces narró su historia a Olódùmarè,\nque él había ido a un Babaláwo a consultarse,\ncuando oyó que las personas\nestaban considerando que él debia ser matado\ny comido como los otros pájaros.\nÉl dijo: \"por la controversia que se dio,\nlas personas se vieron forzadas\na enviar a Ọmo al cielo para preguntarle,\nsi lgun debía ser comido o ser intocable\"\nDespués del sacrificio,\nEṣú me instruyó ir al cielo para visitarlo, Olódùmarè.\nOlódùmarè le preguntó a lgún si regresaría al mundo.\nEl dijo: \"si la gente deja de ver a Ọmo,\nellos no serán capaces de matarte\".\n\"Tu sacrificio ha sido aceptado\"\n\"Omo entregó su mensaje pero no será respondido\"\n\"Omo permanecerá en el cielo y tú, Igún, podrás volver a la tierra\".\nMientras la gente estaba esperando en vano por Ọmo,\nEṣú orgulloso fue anunciando\nque nadie podría comerse a lgún en la tierra,\nÈṣú ayuda a los que hacen sacrificio,\npor eso Eṣú estaba protegiendo a lgün.\nDesde entonces siguieron el proverbio:\n\"si no vemos a Olumo (espiritu sabio de Olódùmarè)\nno podremos comernos a lgún\"\nIgún está en la tierra.\nOlumo está en el cielo.", "origen_id": "f735d55b2b723612a730ebe2"}, {"titulo": "Versos complementarios 1 · A", "texto": "Ifá pé kí eléyìun ó rúbo.                 ``\n                           ' Ayé ó ye' é,\n                                       ' nnkan è' ò níí bàjé.\n                                                           ' Ìségun\n                                                              ''    ni kí eléyìun ó rúbo' sí,\nyóó ségun,\n     ''      ire è' ó sì pò.\n                          '\nÒsá\n ' pàá pàá\nÌwòrì wààràwà\nA díá fún Olókòso Làlú\nBámbí omo    ' ' arígba ota         ' ségun\n                                         ''\nÀwon   '    Elénìní         tó  pò'  yìí\nÒun le ségun ''           gbogbo won      ' báyìí?\nWón ' ní kí Sàngó ó rúbo'\nWón ' ní láko' láko' ní ó rúbo'\nSàngó bá rú òpòlopò      ' ' ' ' owó\nÓ rúbo' tán\nNí ón' bá gbógun ti Sàngó\nNi Sàngó bá ké\nÓ ni ‘Òsá  ' pàáááá’\nGbogbo wón                    ´´\n                   ' bá n gbòn        '\nYóó bàá tún wí ‘Ìwòrì wàràràràrà’\nÀwon                                      ´´\n       ' Awo è' méjèèjì ni n kí ní òfurufú\nPé ebo' ' tí ón  ' rú fún òun\nLòún fi ´´n dá bírà báyìí\nIfá pé kí eléyìun ó rúbo' è' kó pé\nPé òún ó ba ségun         '\nSàngó bá ségun      '         tan\nNí wá ´´    n jó ní ´´n yò'\nNí ´´n yin àwon Babaláwo è'\nÀwon                           ´´\n       ' Babaláwo n yin Ifá\nÓ ní béè   ' ' làwon    ' Babaláwo tòún wí\nÒsá\n '       pàá   pàá\nÌwòrì wààràwà\nA díá fún Olúkòso Làlú\nBámbí omo    ' ' arígba ota         ' ségun\n                                         ''\n              ´´\nNígbà tí n be' láàrin òsììrì\nTí ´´n be' láàrin Òtá sángílítí\nEbo     ´´\n ' ' n wón     '´´ ní ó rú\nÓ gbébo  ' ' nbè'\nÓ´rúbo'\nMo mòmò    ' ' sebo   ' ' Òsá  ' pàá o\nMo sì sebo ' ' Ìwòrì wààràwà\nMo mòmò    ' ' ségun  '\nBéè''    mo   ségun.\n                 '\nÒsá\n ' Ìwòrì A\nIfá le pide a esta persona que realice sacrificio. Su vida sería buena y sus cosas no se\npondrían estropear (echar a perder). Ifá le pide que ofrezca el sacrificio para el\npredominio en sus enemigos.\n\nÒsá pàá pàá\nÌwòrì wààràwà\n\nAdivinación lanzada para Olúkòso Làlú\nBámbí omo arígba ota ségun\n'¿Estos muchos detractores?\n'Yo podría ganarles a todos'? Él preguntó\nOfrezca sacrificio' ellos le dijeron a Sàngó\nEllos le dijeron que ofreciera sus sacrificios con la temeridad\nSàngó también ofreció el dinero suficiente\nPoco después de ofrecido el sacrificio\nLos detractores empezaron a guerrear contra él\nY con un crujido estruendoso\nÉl lloró 'Òsá pàáááá'\nTodos ellos empezaron a estremecerse\nContinuando, él lloraría de nuevo, 'Ìwòrì wàràràràrà'\nEstan sus dos sacerdotes que Sàngó está saludando del cielo\nPara decirles que es el sacrificio que ellos prescribieron para él\nEso le ha hecho realizar estas maravillas.\nIfá exhorta a esta persona para observar sus sacrificios totalmente\nQue él le ayudaría a ganar\nSàngó se puso victorioso\nY empezó a bailar y regocijar\nÉl estaba alabando su Babaláwos\nSus Babaláwos estaban alabando Ifá\nÉl dijo era exactamente como sus Babaláwos había dicho\nÒsá pàá pàá\nÌwòrì wààràwà\nAdivinación lanzada para Olúkòso Làlú\nBámbí ommo arígba ota ségun\nEn el día que él estaba en medio de sus enemigos\nÉl estaba en medio de sus enemigos\nLe pidieron que realizara sacrificio\nÉl oyó hablar del sacrificio\nY lo ofreció\nYo he ofrecido el sacrificio de Òsá pàá\nY también realizó el sacrificio de Ìwòrì wààràwà\nYo soy victorioso\nDe hecho, yo soy triunfante.", "origen_id": "f7a0ba9e25cb50b7c434bcd2"}, {"titulo": "Versos complementarios 2 · B", "texto": "Ifá pé kí eléyìun ó rúbo' kó sì bèèrè nnkan tóríi rè ó gbà. Elédàá rè' ò níí jé' ó rí aburú. Ifá\n                                                            ' '\npé kí eléyìun ó lòó\n                 ' ' ra òkété kan lójà\n                                   ' kó fi rúbo;\n                                               ' yóó mùú òkété náà lówó  ' ' ni bí ón bá n\nrúbo' è.", "origen_id": "b345a63df75dc08e649e7aea"}, {"titulo": "Versos complementarios 3", "texto": "N táa bá dìjo' wò\nGégé\n  ' ' níí gún bí ojúu Gúnnugún\nA díá fún Sóowò     omo\n                    '     Agéegún\n         `` ' ' è ò dáa' tó ' '\nÒun ni nnkan\n ``             '\nNnkan  òún wáá le dáa báyìí?\nWón' ní kó rúbo'\n\nWón ' ní kó lòó   ' ' ra òkété kan lójà\n                                      '\nKée rúbo'\nWón ' ní òkété owó    ' ' è' ní ó ba fínbo'\nWón '    bá  se\n              ' Ifá   fún Sóowò\n                             ' ' ' omo\n                                   ' ' Agéegún\n                                            ''\nAyé ye' é'\nNí wá ´´   n jó ní ´´n yò'\nNí ´´n yin àwon   ' Babaláwo\nÀwon       babalwo     ´´n yin Ifá\n      '\nÓ ní béè  ' ' láwon' Babaláwo tòún wí\nÒsá\n '      wò   ó\nÌwòrì wò ó\nN táa bá dìjo' wò\nGégé\n   ' ' níí gún bí ojúu Gúnnugún\n Adíá fún Sóowò  ' ' ' omo ' ' Agéegún\n                                   ''\nN náà ló fínbo'\nEboo\n ' ' ' wá dà\nÒkété owóo ' ' ' Sóowò''      o\nN náà ló fínbo.     '", "origen_id": "e8539d6f71b99374475747d8"}, {"titulo": "Versos complementarios 4 · B", "texto": "Ifá le pide a esta persona que realice el sacrificio y debe preguntar de lo que sus Orí\ncoleccionaría (recoger, juntar) de él. Su creador no le permitiría ver el mal. Él debe ir al\nmercado para comprar una rata gigante para el sacrificio. Él sostendría la rata durante el\ntiempo de realizar el sacrificio.\n\nÒsá, look at it\nÌwòrì, look at it\nCualquier cosa que nosotros examinamos juntos\nTendría el éxito como los ojos de Gunnugún\nAdivinación lanzada para Sóowò el niño de Agéegún\nÉl es unol cuyas cosas no tuvieron el éxito\n'Mis cosas serían en absoluto buenas'? Él preguntó\nLe aconsejaron que realizara el sacrificio\nLe dijeron que comprara una rata gigante del mercado\nÉl debe usarlo entonces como sacrificio\nEs la rata gigante en sus manos que harían sus sacrificios aceptable\nEllos realizaron una porción de Ifá para Sóowò el niño de Agéegún\nLa vida lo agradó (gustar, contento) así\nÉl empezó a bailar y regocijar entonces\nÉl estaba alabando su Babaláwos\nSus Babaláwos estaban alabando Ifá\nÉl dijo que era exactamente como sus Babaláwos había dicho\nÒsá, mírelo, Ìwòrì, mírelo\nCualquier cosa que nosotros examinamos juntos\nSería tan exitoso como hace los ojos de Gúnnugún\nAdivinación lanzada para Sóowò el niño de Agéegún\nEs uno que hace el sacrificio aceptable\nNuestro sacrificio ha demostrado eficacia\nLa rata gigante en la mano de Sóowò\nEs el que ha hecho el sacrificio aceptable", "origen_id": "723838db51cf9b5f3c038ff0"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Osa´Wori habla de la excepcional buena fortura. También\n                                 explica la sagrada posición del buitre en Ifá.\n            WO - El cliente encontrará el éxito material a través de la acción\n                                                                     espiritual.\n\n\n154.1 · Temigbusi adivinó Ifá para Ajetunmobi, predijo buena fortuna\n         proveniente del mar y de la laguna para Ajetunmobi. El dinero (aje)\n         podría ir a casa de él. Sonriendo él miró al babalawo y dijo: ¿Acaso\n           no sabes por lo que me he estado esforzando?, él fue avisado para\n     hacer sacrificio en función de obtener completa felicidad y bienestar.\n             Ebo: 1 carnero, palomas, plátanos maduros y 44.000 cowries. Él\n         escuchó el aviso y ejecutó el sacrificio. A él le dieron algunos de los\n         plátanos que ofreció y fue instruido para que se las comiera. Le fue\n                                    dicho que podía comerlas frecuentemente.\n\n\n154.2 · Osa woo, Iwori woo, profetizó Ifá para el buitre (igun). Todo el\n\n             mundo vino juntos, queriendo comer a igun. El sabio (omo), fue\n     enviado al cielo para averiguar, Igun, fue avisado a sacrificar: 1 bulto\n     de nueces de kola, 1 carnera, 8.600 cowries. Para prevenir de que sus\n            enemigos se lo comieran, como a los otros pájaros. Él escuchó el\n          aviso e hizo el sacrificio. Cuando Omo arribó al cielo, él entregó el\n     mensaje del pueblo a Olodumare. Olodumare dijo que él no era capaz\n\nde responder porque él estaba muy ocupado y que él necesitaba algún\n   obi para completar su empeño. Él por lo tanto ordenó a Omo a ir y\n    buscar por obi. Omo rápidamente fue de vuelta a la tierra a buscar\n  obi. Cuando él estuvo en el cruce entre la tierra y el cielo, al lado de\n Eşu encontró algún obi que Igun ofreció como sacrificio. Él tomó el\n    obi para Olodumare. Después de un tiempo, el mismo Igun fue al\n  cielo a visitarlo, quien lo entretuvo con algunos de los obi que Omo\n le había traído. Igun examinó el obi y dijo que el obi se parecía a los\n    que él había sacrificado el otro día. Entonces él narró su historia a\n  Olodumare, de que él había ido a ver un babalawo para consultarse,\n     cuando oyó que las personas estaban considerando si él debía ser\nmatado y comido como los otros pájaros. Él dijo “por la controversia\n   que se dio, las personas se vieron forzadas a enviar a Omo al cielo\n        para preguntarle, si Igun debía ser comido o quedar intocable.\n Después del sacrificio, Eşu me instruyó para ir al cielo para visitarlo,\nOlodumare.” Olodumare le preguntó a Igun si regresaría al mundo. Él\n        dijo: “si la gente deja de ver a Omo, ellos no serán capaces de\nmatarte. Tu sacrificio ha sido aceptado. Omo entregó su mensaje pero\n no sería respondido. Omo permanecerá en el cielo y tú, Igun, podrás\n   volver a la tierra.” Mientras la gente estaba esperando en vano por\n Omo, Eşu orgulloso fue anunciando que nadie podrá comerse a Igun\nen la tierra, Eşu ayudó a cada uno a hacer el sacrificio, esto es porque\n     Eşu estaba detrás de Igun protegiéndolo. Desde entonces ese día\n siguieron el proverbio: si no vemos a Olumo no podremos comernos\n\na Igun. Igun está en la tierra. Olumo está en el cielo", "origen_id": "3714ae573dd28600e97e211d"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ajétunmobi: una carnera, palomas, plátanos maduros pequeños y 44,000 cauríes; comer parte de los plátanos.", "El buitre: un paquete grande de kola, una carnera y 8,600 cauríes.", "Ṣàngó: dinero suficiente y la ofrenda completa.", "Sóowò: una rata gigante sostenida en las manos durante la ofrenda; preguntar qué acepta su Orí."], "pasajes": [{"titulo": "Ofrenda en el verso 154.1", "texto": "Temigbusi: adivinó Ifá para Ajétunmobi.\nEl predijo: \"para Ajetunmobi\nla buena fortuna proviene del mar,\nla buena fortuna proviene de la laguna\"\n\"El dinero está viniendo para su casa\".\nSonriendo él miró al Babaláwo y dijo:\n¿Acaso no sabes por lo que me he estado esforzando?\nLe fue aconsejado hacer sacrificio\npara obtener la felicidad completa y el bienestar.\nSacrificio: carnera, palomas,\nplátanos\nmaduros pequeños y 44.000 cowries.\nÉl escuchó y ejecutó el sacrificio.\nA él le dieron una parte de los plátanos que ofreció\ny fue instruido para que se los comiera.\nLe fue dicho que podía comer\nplátanos pequeños maduros frecuentemente.", "origen_id": "6289bb3c93511ffe55315fd4"}, {"titulo": "Ofrenda en el verso 154.2", "texto": "Ọ̀sá woo,\nÌwòrì woo,\nadivinó Ifá para el buitre (lgún),\ncuando todo el mundo se reunió porque querian comerse a lgún.\nEllos enviaron a Ọmo (un emisario sabio) al cielo para averiguar.\nPor otro lado, los adivinos aconsejaron a lgún sacrificar:\nun paquete de nuez de kola (gran cantidad),\nuna carnera y 8.600 cowries,\npara prevenir de que sus enemigos se lo comieran,\ncomo a los otros pájaros.\nEl escuchó el aviso e hizo el sacrificio.\nCuando Ọmo arribó al cielo,\nél entregó el mensaje del pueblo a Olódùmarè.\nOlódùmarè dijo que él no era capaz de responder\nen ese momento porque estaba muy ocupado\ny que necesitaba algún obi para completar su empeño.\nÉl por lo tanto ordenó a Ọmp ir y buscar obi\nỌmo rápidamente fue de vuelta a la tierra a buscar obi.\nCuando él estuvo en el cruce entre la tierra y el cielo,\nencontró al pie de Eṣú los obi\nque lgún había ofrecido como sacrificio.\nEl tomó el obi para Olódùmarè.\nDespués de un tiempo,\nel Igún fue al cielo a visitar a Olódùmarè,\nquien lo entretuvo con algunos de los obi\nque Ọmo le había traído.\nIgún examinó el obi y dijo que esos obi se parecian\na los que él había sacrificado el otro día.\nEntonces narró su historia a Olódùmarè,\nque él había ido a un Babaláwo a consultarse,\ncuando oyó que las personas\nestaban considerando que él debia ser matado\ny comido como los otros pájaros.\nÉl dijo: \"por la controversia que se dio,\nlas personas se vieron forzadas\na enviar a Ọmo al cielo para preguntarle,\nsi lgun debía ser comido o ser intocable\"\nDespués del sacrificio,\nEṣú me instruyó ir al cielo para visitarlo, Olódùmarè.\nOlódùmarè le preguntó a lgún si regresaría al mundo.\nEl dijo: \"si la gente deja de ver a Ọmo,\nellos no serán capaces de matarte\".\n\"Tu sacrificio ha sido aceptado\"\n\"Omo entregó su mensaje pero no será respondido\"\n\"Omo permanecerá en el cielo y tú, Igún, podrás volver a la tierra\".\nMientras la gente estaba esperando en vano por Ọmo,\nEṣú orgulloso fue anunciando\nque nadie podría comerse a lgún en la tierra,\nÈṣú ayuda a los que hacen sacrificio,\npor eso Eṣú estaba protegiendo a lgün.\nDesde entonces siguieron el proverbio:\n\"si no vemos a Olumo (espiritu sabio de Olódùmarè)\nno podremos comernos a lgún\"\nIgún está en la tierra.\nOlumo está en el cielo.", "origen_id": "9328056730b1ab1de21cfe63"}]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè acepta la kola del buitre. Èṣù protege al buitre. Ṣàngó vence con el trueno."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Plátanos maduros pequeños (Musa paradisiaca), kola, rata gigante, carnera."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 154.1 (yorùbá): Temigbusi: a dífá f'Ajétunmobi. / Wọ̀n ni: \"Ajetunmobi Ire-Ökun, / Ire-Ọ̀sá ma de. / Ajé nwọle wa\" / O wo oju Babalawo tẹrintẹrin. / O ni: \"Ẹyin komope ohun ti mo ti ntorirẹ sare / kiri niyẹn ti mo nwo'hin-w'ohun?\". / Wọ̀n niki ó wa rúbọ / ki ara le rọo pẹsẹ. / Àgùtàn, eyẹlé, / ogèdẹ̀ wẹerẹ tio pọ̀n ati egbàá méjilélógún owó. / Ó gbọ̀ ó rú. / Wọ̀n ko apakan Ogèdè tiofi rúbọ / fún un pe kiojẹẹ / ati pe bẹẹ niki ó ma jẹ gèdẹ̀ weerẹ.", "Verso 154.2 (yorùbá): Ọ̀sá woo, / Ìwòrì woo, / a daa fún lgún, / gbogbo ayé pejẹ, / wọn nfẹe jee. / Wọ̀n ran Ọmo / losi Isalu orun / kiolo bere wa. / Wọ̀n niki lgún rúbọ: / Egbirin Obi kan, àgutàn / ati egbetalelẹ-gbàrin owó, / ki àwọn ọ̀tá rẹ̀ ma le paa je / bi àwọn eyẹ miran. / Ó gbọ̀ ó rú. / Nigbati Ọmo de Isalu orun, / o jiṣẹ ti àwọn qmo aráyé / ran fún Olódùmare. / Olódùmarè l'òun Koitiiri aye / dahun ibere rẹ / nitoripe òun ṣe kini kan lowọ. / Oun tilẹ nwa obi lati tubo / fiṣe ohun naa yanju. / Nitorinaa ki Ọmọ wa obi / lọ fún oun wa na. / Ọmọ nyarabowa òde-ayé / lati mu obi lọ fún Olódümare. / Biotide ikorita örun ati ayé nidi Eṣú, / O ba obi ti lgún fi rúbọ nidi Eṣú. / Ó gbee lọ fún Olódümare. / O pẹ diẹ lẹhin eyi, / Igún tikalararẹ wasi isalu orun / wa ki Olódùmare. / Ó mu ninu obi ti Ọmọ gbe wa fún un, / O fiṣe İgún l'álejò. / Igún yẹ obi naa wo. / Ó ni obi yi ma ferẹẹ jo / Obi ti òun fi ṣẹbọ la'na. / Ó ko o ro fún Olódùmarè. / Ìdí rẹ ti òun fi losodọ Babaláwo / ti òun ko aarunitẹ'ni ati eeji adibo. / Nigba ti oun gbọ pe / àwọn omọ aráyé pejọ / ngbimo pe wọn iba ma pa lgún je / bi i àwon eyẹ miran, / ti ariyanjiyan kojẹ toobẹẹ ti wọ̀n firan / Ọmo wasi isalu Orun lodọ rẹ / kiolo bere wa. / Ki wọ̀n toole maa pa lgún jẹ / tabi ki wọ̀n jọwọ rẹ. / Bi oun ti rúbọ tan, / ni Eṣú niki oun lọ / ki Olódùmarè ni Isalu-Orun wayi o, / li òun fi nbọwa ki ọ. / Olódùmarè niki Igún maa losinu ayé. / Nigbati wọ̀n ko ba ri Ọmg, / wọ̀n koniile pa q jẹ. / Mo ti gba ebọ rẹ, o da. / Ọmọ jiṣe orọ rè fún mi sùgbọ̀n / koi tiigba esi ṣa ni. / Ọmp wa nibi na. / Iwọ maa lọ sinu ayé biwọn / kô ba ri Ọmo / wọ̀n koniile pa q jẹ. / Nigbati àwọn omọ aráyé / reti fún igbapipẹ / to ti wọn kori Ọmọ wa jiṣẹ fún wọn. / Ti Elégbárá gb'ode ayé kan / ti o nleri kiri pe: / \"Kosi eniti o gbodo pa lgún jẹ li ayé\". / \"Eniti o rúbọ ni Eṣú ngbe\". / Nitorinaa ni Eṣú ṣe wa lẹhin lgún pe / wọn koniile pa jẹ. / Lati ojọ naa li a ti npa Owe yi pe: / \"A ko ri Olumo ba jẹ lgún, / Igún wa li ayé, / Olumo wa li orun.\"", "REZO: OSA WO ABATI ELEYELA NINIMU ADIFAFUN ETU TINSHOMA OLU BEBE AKUKO, ABO LEBO.", "REZO: OSA WO IWOURI WO ALO ADIFAFUN ETU BAITA LEYO ALABOMU. OSA WO IWORI WO AWO ALEYO ATENA SOKU.", "REZO: ABATO EIELLELA NINIMU ITU TINCHOMA OLUBELE KUKO AKUKO ABO LEBO.", "REZO: OSAIGUO IGUO IGUIRI GUE ALO ADIFAFUN ITU LELLO ALOBUMU.", "REZO: BABA OSA WORIWO AWO ORUN AWO AYE ORUNMILA LODEFA OLOFIN ODE KIODE KORUBO AIKORDIE, AKOFA AKO MANU ORISHAOKO KUBIA ODE INSHE EBOAKO AKOFA LODO LOKUMI ORISHAOKO LODAFUN ORISHAOKO AWA AYE OMO OGODO GAI OLOTIGBARO.", "REZO: ODE OMOYADI OMO EYE EKUN ONI CAINI INU INA OBE LOGUEDE OWA IRENISHE LAYERE ETAN AWO IBA YOKU ORUN LAYE ENIFA.", "REZO: OSAWO WORI IWO OTORIKU IWANI AWOLODO, OSAWO IWANI AWO APONUKU AWO OSA INLE ABITI OYEYA ALOBI OMA OTURON BIOSHE INLE EGGUN OMASHALE OSAWORIWO AWO LODONIFA ENI OMO EFAN, OBARADA UN ADE AWO AMORO ATEFA MADA MI ODA YEKA OMABODUN IYALE KOFUN FITIBO ENI LOWIFA ADIFAFUN ORUNMILA.", "REZO: OSA WORIWO WO UMBATI ALEYO ATINI ADIFAFUN ABATE OLAYA AWO NINIYU OGGUN ARATAKO INLE ORISHAOKO ADAFUN ITU INSHOMA ELUBERERE INLE OSA WORIWO OGGUN ATALA MOBANLA LA ADIFAFUN UMBATI ALEYO IKOKO ALABA NU LODAFUN ORUNMILA KAFEREFUN ORISHAOKO."]}]$q$::jsonb),
(155,'a64e83e874a7cf2079728112ce10d620','8f2ebf360f78d248c2bd6418eb99afcb',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Ìdí habla de quitar los obstáculos con la ofrenda y de lograr una buena relación de pareja o familiar. Los miedos de la persona a no tener pareja terminarán cuando aparezca alguien nuevo. Hay un egúngún de los ancestros guardado que hay que dejar salir. Libra de problemas mentales."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que sus esfuerzos no avanzan y el camino se le cierra.", "Llega alguien nuevo y no sabe cómo saldrá esa relación.", "Espera una visita o una noticia que puede cambiar sus planes."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que se abra el camino y aparezca la conducta correcta.", "Una persona nueva en su vida.", "Buenas noticias: llegó a quien esperábamos.", "Riqueza, pareja, hijos y casa para toda la familia.", "Que la enfermedad mental se vaya."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El cambio repentino lleva al renacimiento. (Este odu habla de la necesidad de escuchar la guianza de un extraño).", "origen_id": "ade733458c38812efb211cf6"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Un camino torcido o bloqueado.", "Dejar guardado el egúngún de la familia.", "Males de la mente."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El cambio repentino lleva a las decisiones arbitrarias. (Este odu habla de la posibilidad de vargas de un cambio espiritual).", "origen_id": "fb74c391409ae96fae204403"}]}, {"titulo": "Enseñanza principal", "texto": "Cuando el camino está torcido, se enciende una lámpara para encontrar el recto. Y la riqueza de la familia vuelve cuando se deja salir a su egúngún."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀sá'Dí habla de remover los obstáculos y las dificultades a través del sacrificio y para obtener una relación de pareja o familiar exitosa.", "origen_id": "7abbe732b8f14e17e1e1a728"}]}, {"titulo": "Relatos reunidos", "puntos": ["El camino de Ọ̀sá. El camino de Ọ̀sá no estaba abierto; estaba torcido. Ọ̀rúnmìlà le dijo que ofreciera una lámpara de barro, aceite de palma, 8,000 cauríes y medicina de Ifá, y que encendiera la lámpara al hacer la ofrenda, para que apareciera un buen camino.", "Las buenas noticias. 'Las buenas noticias son motivo de alegría; ve y diles a todos que llegó a quien esperábamos.' Se ofrecen kola, kola amarga, pimienta de guinea, ginebra, vino de palma y 3,200 cauríes, y todo se usa para que la gente disfrute.", "El egúngún de Lánlègè. Lánlègè lloraba por todas las cosas buenas. Le dijeron que todos en su casa, jóvenes y viejos, con hijos y sin ellos, debían ofrendar, y que dejaran salir al egúngún de la familia que estaba guardado. Al terminar su recorrido, antes de entrar a casa, todos debían tocar con las manos su vestido. Lo hicieron, compraron un chivo entre todos para el egúngún, y llegaron la riqueza, las esposas, los hijos y las casas; Lánlègè llegó a viejo y nada malo le pasó a nadie de su casa.", "Ìyèrú y la mente. Ifá consultó para Ìyèrú, que cargaba con una enfermedad de la mente. Le pidieron un chivo grande para su Orí. Ofreció y la vida le fue grata. 'Se fueron todos los ajogun; la enfermedad de la mente se fue y no puede volver.'"], "pasajes": [{"titulo": "Verso 155.1", "texto": "El camino de Ọ̀sá no está abierto\nEl camino de Ọ̀sá está bloqueado.\nỌ̀rúnmìlà aconsejó:\n\"un sacrificio se debe realizar\npara que aparezca un camino para Ọ̀sá\":\nlámpara de arcilla,\naceite de palma (epo),\n8.000 cowries\ny medicina de Ifá.\nNota: La lámpara debe ser encendida cuando se haga el sacrificio.", "origen_id": "2c9d8041344fbc6d85abb4db"}, {"titulo": "Verso 155.2", "texto": "Ọ̀rúnmìlà dice:\n\"las buenas noticias son motivos de alegría\".\nYo digo: \"las buenas noticias\",\nPor favor, ve y dile a cada uno,\nque a quien nosotros esperamos a llegado.\nNueces de kola,\nnueces de kola amarga,\npimienta guinea,\nginebra, vino de palma\ny 3.200 cowries deben ser sacrificados.\nNota: Los materiales del sacrificio deben ser usados para el disfrute y\nentretenimiento de la gente.", "origen_id": "ce23c2b80c727aa10d76d6f3"}, {"titulo": "Versos complementarios 1 · A", "texto": "Ifá pé ire fún eléyìun. Eni                 ´´\n              ´´            ' ´´ojú omo\n                                      ' ' n pon, ' eni\n                                                     ' ti ò lájé, gbogboo won   ' ò níí ráburu. Ifá pé\neègún baba nláa won   ' kán n be       láíláí ti wón dì mó ibi kan. Ifá pé kí wón   ' o jé' eégún náà ó\njáde. Gbogbo àwon      ti   ojú    ``´ ´´n pon ni' wón ó 'dáwó jo kí wón ó sì ra\n                                nnkan                                                 òrúko' kan fi bo'\n                    '                        '         '           '       '\neégún òhún.\n        ' ``´ Gbogbo ire won     ' ò níí jùnù. Bí eégún òhún '      bá fé' wo' ilé padà, gbogbo àwon\nti ´´\n   n wá nnkan    ni kí wón    ó fi owó    gbé   asoo  rè. Gbogbo  won             ``´          ´´ '\n                          '         ' '          ''' '               ' ní ó rìí nnkan ti wón ' n wá.\nÒsá\n ' bíìrìn bíntin\nA díá fún Lánlègè             ' '\nOmo\n ' ' Akànrunkande'\nOmo\n ' ' Akànlèkè          ' ' sunwòn          ' sunwòn   '\nNíjó' ti n fomi ojú sògbérè ire gbogbo\nWón' ní kó' rúbo'\nWón                                          ´´\n   ' ní gbogboo won                    ' nnú ilé òhún  '\nWón           ``´\n   ' ní nnkan won                  ' ò níí bàjé'\nWón' ní tomodé  ' ' tàgbà ni wón                   ' ó jo' rúbo'\nEni   ojú   omo          ´´n pón, kó rú\n '           ' '                 '\nEni\n '    ó  ti bímo       '    kóun       náà ó rú\nSùgbón\n'            kí     wón  '      ó   jÉégún       babaa wón ' ó jáde\nBéégún òhún   '             bá jáde\nBí bá ´´ n woléé '           lo'\nKí wón '     ó   fowó' ' kó aso          ' ' è' wolé\n                                                  ' '\nGbogbo ihun tíí jájogun ò tún bá won                        ' gbé mó'\nIre ló kù ti ó móo             ''    bá    won'   gbé\nWón'    bá    se\n              ' ''    béè\nGbogbo ará ilée Lànlègè               ``\n                                            ' ' omo\n                                                 ' ' Akànrunkande'\nWón' bá bo' Eégún\nWón' bá bèrè     ' ' síí lájé\nWón' láya\nWón' bímo'\nWón' kó' ilé\nWón' gbó\nWón' tó'\nAburú ò selè     ' ' sénìkan '\nKò kan àwon        '´´ omo  ' ' è' ´´\nNi wón ' bá n jó ni wón                  ' n yò'\nWón    ´´\n        n   yin       àwon          Babaláwo\n   '                         ' ´´\nÀwon '    Babaláwo                  n yin Ifá\nÓ ní béè  ''    láwon    '      Babaláwo          tòún wí\nOsa\n ' bíìrìn bíntin\nA díá fún Lánlègè       ``\n                              ' '\nOmo\n '   '   Akànrunkande                  '\nOmo\n ' ' Akànlèkè          ' ``' sunwòn        ' sunwòn   '\nKín ní ò jé Lánlègè             ' ' foso?ó    ' '\nÒpò\n ' ' òjò ``\nNi ò jé' Lánlègè        ' ' ó foso    ' '\nÒpò\n ' '   Òjò.\nÒsá\n ' Òdí A\nIfá desea bien a esta persona. Todos aquéllos en la necesidad de riqueza, niños, y todas\nlas cosas buenas de vida no se defraudarían. Ifá dice hay una mascarada que pertenece a\n\nsus antepasados que había sido condensado (empacado). Ifá dice que ellos deben\npermitirle exhibirse (ostentar). Todos ellos en la necesidad deben contribuir el dinero\nentonces para comprar una cabra como sacrificio a la mascarada. Cuando la mascarada\nestá viniendo de regreso a casa después de la excursión, todos ellos deben usar sus\nmanos para empacar el vestido (traje, disfraz) de la mascarada. Ellos habrían conseguir\nel deseo de su corazón.\n\nÒsá bíìrìn bíntin\nAdivinación lanzada para Lánlègè\nEl niño de Akànrunkande\nEl niño de Akànlèkè sunwón sunwón\nEn el día que él estaba llorando debido a todas las fortunas buenas\nLe pidieron que realizara sacrificio\nTodos ellos en la casa\nEllos fue dicho que todas sus cosas no se pondrían consentidas\nTodos ellos, joven y viejo debe realizar el sacrificio\nÉl que esta sin hijos debe ofrecer el sacrificio\nÉl eso tiene los niños debe realizarlo\nPero ellos deben permitir la mascarada para venir fuera para visualizar (exhibir,\nexponer)\nDespués de la excursión de la mascarada\nY está a punto de entrar en la casa\nEllos deben usar sus manos para empacar en sus trajes\nTodas las cosas conocidas como Ajogun nunca vivirían de nuevo con ellos\nEs sólo fortunas buenas que estarían con ellos\nEllos hicieron como los instruiyeron\nTodos los miembros de la casa de Lánlègè\nOfreciendo el sacrificio a Egúngún\nTodos ellos empezaron a tener la riqueza\nEllos se casaron a las Esposas\nEllos tenían los niños\nY construyeron casas\nLánlègè también envejeció\nY se pone firme en la vejez\nNinguna cosa mala ocurrió a cualquiera de la casa\nNi nada hizo", "origen_id": "7b33ac15f8d11ec8a41978db"}, {"titulo": "Versos complementarios 2 · B", "texto": "Ifá pé ki eléyìun ó rúbo.\n                       ' Ifá pé kò níí rárùn Orí. Ìgìrìpá òrúko' lebo\n                                                                  ' ' è.\n                                                                      ' Ifá pé kí wón\n                                                                                   ' ó sì\nmóo\n  ' ' bo' Orí.\nÓ sá mó' leè dí\nAwo ilé Alárá\n  ````\nKannkàn    womú\nAwo òkè Ìjerò\nAro' ni ò dàgbà\nKó gbégbá etí kan laja\nNíbi ti gbé ´´\n            n wo' tuurutu\n       ´´\nTi gbé n wó' gbajagbaja\nA díá fún Ìyèrú\n              ' kan gèjègèjè\n                       ' ' ' '\n\nÈyí ti ó móo ' ' rárùn ori\nWón'   ní  kó  rúbo'\nKó fi òrúko' rúbo' Orí è'\nÓ bá rúbo'\nAyé bá ye' é'\nÓ ní Ó sá mó' leè dí\nAwo ilé Alárá\n     ``\nKannkàn     womú\nAwo òkè Ìjerò\nAro' ni ò dàgbà\nKó gbégbá etí kan laja\nNíbi ti gbé´´n wo' tuurutu\nTi gbé ´´n wó' gbajagbaja\nA díá fún Ìyèrú ' kan gèjègèjè\n                          ' ' ' '\nÈyí ti ó móo ' ' rárùn Orí\nWón' ló ti lo' ò\nIbí ti lo'\nÀrùn Orí ti wón      ´´\n                  ' n rùn\nGbogbo ajogun ibí ti lo'\nAjogun ò leè wèyìn  '   wò\n\nÒsá\n ' Òdí B\nIfá le pide a esta persona que realice sacrificio. Él no experimentaría el problema\nmental. Él debe sacrificar un macho cabrío maduro y también ofrecer sacrificio a su Orí.\n\nÓ sá mó leè dí\nEl sacerdote de la casa de Alárá\nKannkàn womú\nEl sacerdote de las colinas de Ìjeròland\nUn cojo no crecería en la edad\nY puede poner una calabaza en el ático\nDonde él estaba arrastrándose\nY arrastrándose alrededor\nAdivinación lanzada para un cierto Ìyèrú-gèjègèjè\nEl que estaría alimentando una enfermedad mental\nLe pidieron que realizara sacrificio\nLe pidieron que usara un macho cabrío maduro como sacrificio a su Orí\nÉl realiza el sacrificio\nLa vida lo agradó después\nÉl cantó 'Ó sá mó leè dí'\nEl sacerdote de la casa de Elárá\nKannkàn womú\nEl sacerdote de las colinas de Ìjeròland\nUn cojo no crecería en la edad\nY puede poner una calabaza en el ático\nDonde él estaba arrastrándose\nY arrastrándose alrededor\nAdivinación lanzada con toda seguridad a Ìyèrú gèjègèjè\nEl que estaba alimentando una enfermedad mental\nEllos se han ido\n\nTodas las cosas malas se han ido\nLa enfermedad mental que ellos estaban alimentando\nTodos los Ajoguns se han ido\nLos Ajoguns nunca pueden recaer de nuevo.", "origen_id": "2e6ae0109a17c7412cc37dfc"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Osa´Di habla de remover obstáculos para obtener una relación\n                                                                      exitosa.\n            WO – Los miedos del cliente de carecer de relaciones terminarán\n                                            cuando una nueva persona aparezca.\n\n\n155.1 · El camino de Osa no está abierto. El camino de osa está\n      bloqueado. Orunmila le dijo que él tenía que hacer un sacrificio para\n          abrirle el camino. Ebo: 1 lámpara de arcilla, aceite de palma, 8.000\n             cowrie y medicina de Ifá (moler las hierbas okro con jabón para\n          baños). La lámpara debe ser encendida cuando se haga el sacrificio.\n\n\n155.2 · Orunmila dice que las buenas noticias son motivos de alegria.\n           Yo digo buenas noticias. Por favor, dile a cada uno, que la persona\n\nque nosotros esperamos a llegado. Ebo: nueces de kola, nueces de\n                  kola amarga, pimienta guinea, ginebra, vino de palma y 3.200\n             cowries deben ser sacrificados. Los materiales del sacrificio deben\n                                    ser usados en el entretenimiento de la gente.", "origen_id": "1368330c8bde368950cf1025"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Una lámpara de barro encendida, aceite de palma, 8,000 cauríes y medicina de Ifá.", "Kola, kola amarga, pimienta de guinea, ginebra, vino de palma y 3,200 cauríes, para que la gente disfrute.", "Un chivo para el egúngún de la familia, comprado entre todos.", "Un chivo grande para Orí."], "pasajes": [{"titulo": "Ofrenda en el verso 155.1", "texto": "El camino de Ọ̀sá no está abierto\nEl camino de Ọ̀sá está bloqueado.\nỌ̀rúnmìlà aconsejó:\n\"un sacrificio se debe realizar\npara que aparezca un camino para Ọ̀sá\":\nlámpara de arcilla,\naceite de palma (epo),\n8.000 cowries\ny medicina de Ifá.\nNota: La lámpara debe ser encendida cuando se haga el sacrificio.", "origen_id": "1d4ff1efce35a0e555a0ad46"}, {"titulo": "Ofrenda en el verso 155.2", "texto": "Ọ̀rúnmìlà dice:\n\"las buenas noticias son motivos de alegría\".\nYo digo: \"las buenas noticias\",\nPor favor, ve y dile a cada uno,\nque a quien nosotros esperamos a llegado.\nNueces de kola,\nnueces de kola amarga,\npimienta guinea,\nginebra, vino de palma\ny 3.200 cowries deben ser sacrificados.\nNota: Los materiales del sacrificio deben ser usados para el disfrute y\nentretenimiento de la gente.", "origen_id": "a9bf9d71a16bbf9edce3c874"}]}, {"titulo": "Relaciones espirituales", "texto": "Egúngún de los ancestros trae bendiciones a la casa. Orí sana la mente."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de quimbombó (ilá, Abelmoschus esculentus) machacadas con jabón para baño. Lámpara de barro, kola, pimienta de guinea. Ante males de la mente, se debe buscar también atención médica."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 155.1", "texto": "moler hojas de ilá con jabón para baños.\n\" Nota: En \"Ọ̀nà Ọ̀sá koila\", \"Ọ̀nà\" es camino y se puede entender también como conducta, \"koila\" significa \"que no es recto\", \"está torcido\" y por tanto \"no está abierto\". El sacrificio de una lámpara (luz) es para que aparezca un buen camino para \"Ọ̀sá\", no se trata tanto de eliminar obstáculos y dificultades en el camino, sino de encontrar el camino o conducta adecuada, que esté libre de obotáculos y dificultades, y por tanto desbloqueado.\nllá: ABELMOSCHUS ESCULENTUS (L.) Moench, Malvaceae. Nombre común en Cubiquimbombó", "origen_id": "60fecdf9e81238c534e1afaa"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 155.1 (yorùbá): Onà Ọ̀sá koila. / Qnà Ọ̀sá ma di o. / Ọ̀rúnmìlà I: / ẹbọ niki a ṣe / ki ònà le la fún Ọ̀sá. / Atupa-amo, epo, / egbàá mẹrin owó / ati ewé Ita / Akiyesi: Kia tan atupa naa biaba nṣ'ẹbọ l'ọwọ. / Ewé Ifá: Lo ewé ilá pomo Ọ̀ṣẹ́ kioma fi wẹ.", "Verso 155.2 (yorùbá): Ọ̀rúnmìlà I: \"agboka bràn ayo\", / Emi I: \"agboka\" / O niki ẹ wa bawa / wi fún gbogbo èniyàn, / eniti a nwa ma de o. / Obi, Orogbo, ataare, / pti-okà, emu / ati egberindílógún owó li ẹbọ. / Akiyesi: Ki a maa fi wọn tọrẹ fún gbogbo èniyàn.", "REZO: OSA DI ISHE ISHERI OSHE KOLOMA TABATI ISHE WELE IBA LAFI MUNU ADIFAFUN BABA BOKUN BANTI POROKI AKUKO EYELE LEBO.", "REZO: OSA DI IFA OSUN, YEMAYA ORUN GUN SAFUYE EYENSHE EFAN OSA FUYA AYOYARAN ABOSA AFUYA AYORI SAFUMI INSAFUO. MAFEREFUN ORUNMILA, OBATALA, SHANGO ATI ESHU.", "REZO: ADIFAFUN OBA AKUAKUOFUN AWO IÑA GBOGBO INKAN ARAYE GBOGBO OMO ODARA ASHE ONI GBOGBO ASHO LODAFUN OLOFIN KAFERFUN OLOFIN."], "pasajes": [{"titulo": "Osa Di — último rezo del ebo", "texto_ritual": "Adimula erin okun Adimula erin osa Erin dikinmu erin yaso Efon dimu efon yajana Agbamurere dimu ohu iwo kan soso lori girogiro Manjagbani Manjagbarare Adifa fun alaaka Ti odi opo opemunitori abiye omo Ope mudi omu kioma yinminu Iyere ara igi kiiwannu Iyo iku banbo koobo Ijo arun banbo koobo Ijo gbogbo ajogun banbo koobo Ijo aje banbo koosiisile Ijo ire gbogbo banbo koosiisile", "traduccion": "Adimula, el elefante del mar. Adimula, el elefante de la laguna. El elefante aguantó a Ifá y se engordó. El búfalo aguantó a Ifá y se engordó. Agbamurere aguantó a Ifá y le creció un cuerno en la cabeza. El que se salvó de la pelea, el que se salva a sí mismo de la pelea. Hicieron adivinación para Alaaka, que se aguantaba a Ifá para poder tener hijos vivos. Ifá, tú me aguantas, no me abandonas; las pimientas no abandonan la mata (árbol). Cuando viene la muerte, me protege. Cuando viene la enfermedad, me protege. Cuando vienen los espíritus malévolos, me protege. Cuando viene la suerte de dinero, me abre los caminos. Cuando viene toda la suerte, me abre el camino.", "origen_id": "8ef3d75064ce05985ae6a1d2"}]}]$q$::jsonb),
(156,'92201aa9f03feb346075ef42477cb837','955089204ab9f2616cecc0fd06aa6738',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Ìrosùn dice que la paz y el dinero son esenciales para el éxito. La persona enfrenta cambios repentinos en casa o en el trabajo. Saldrá ilesa de lo que emprenda. Debe escuchar los consejos que le dan."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay un cambio repentino en su casa o en su trabajo.", "Trabaja con terquedad y necesita descansar.", "Busca seguridad económica sin romper la paz en casa (relatos de Alágemo y de Eeka-Alajé)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una vida tranquila andando con cuidado.", "Prosperidad y poder comprar cosas buenas.", "Quedarse con lo que se disputa."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El cambio inesperado lleva a la satisfacción del destino. (Este odu habla de la necesidad de descansar y disfrutar la vida).", "origen_id": "37a3cd25bc43cf34786f00b4"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Cambios repentinos.", "Oír el consejo por un oído y sacarlo por el otro.", "Un accidente en casa por no ofrendar."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El cambio inesperado lleva a la resistencia del destino. (Este odu habla de las consecuencias negativas del trababo sin ceder).", "origen_id": "83facb766a49aa652e5847ec"}]}, {"titulo": "Enseñanza principal", "texto": "El caracol anda despacio y en paz. Si las predicciones de Ifá no se cumplieran, el principiante no las temería: Eléèdìmédìro oyó el consejo con una oreja y lo sacó por la otra."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀sá'Rosù dice que la paz y el dinero son los ingredientes esenciales para el éxito y la prosperidad.", "origen_id": "484ab191d6ba1597059e7a35"}]}, {"titulo": "Relatos reunidos", "puntos": ["El camaleón y la calma. Ifá le aconsejó a Alágẹmọ, el camaleón, andar por el mundo con cuidado para que su vida fuera tranquila, y ofrecer aceite de palma, manteca de cacao, un pescado ahumado grande y 18,000 cauríes. Ofreció.", "El que tiene dinero. 'El que tiene dinero puede comprar cosas buenas.' Le aseguraron a Ẹẹka-Alájé que sería muy próspero si ofrecía cuatro gallinas y 3,200 cauríes.", "La oreja y el mosquito. La oreja le quitó a Monífọnran, la esposa del mosquito. Los vecinos le advirtieron que el mosquito era muy atrevido y entraría a su casa. Ọ̀rúnmìlà le pidió dos manojos de escoba y un chivo grande. Ofreció, dio una escoba y el babaláwo se quedó con la otra. Cuando el mosquito llegó directo a agarrar a la oreja por la cabeza, Èṣù gritó: '¡Pégale con la escoba!'. Por eso hasta hoy a los mosquitos se les espanta con la escoba; zumban buscando a su esposa.", "Eléèdìmédìro y el colmillo. A Eléèdìmédìro le pidieron ofrendar porque en siete días le pasaría algo importante. Escuchó con la oreja derecha y lo sacó por la izquierda. Junto a su casa había un mercado, y guardaba en el ático un colmillo de elefante para venderlo el día de plaza. Al séptimo día vio un gato subiendo al ático; lo quiso espantar desde lejos, el gato chocó con el colmillo y el colmillo cayó del techo sobre Eléèdìmédìro y lo clavó al suelo. Ọ̀rúnmìlà dijo: '¿No se los dije?'."], "pasajes": [{"titulo": "Verso 156.1", "texto": "Tener paz y sosiego es bueno, Ọ̀sá'Rosù,\nPor el mundo va la babosa\nsuavemente (pacíficamente):\nỌ̀sá'Rosù adivinó Ifá para Alágemo.\nLe fue aconsejado a Alágemo\nir por el mundo con cautela (cuidadosamente)\ny la vida le sería fresca (pacífica).\nLe fue aconsejado hacer sacrificio:\nepo, manteca de cacao,\nun pez aro grande\ny 18.000 cowries.\nÉl realizó el sacrificio.", "comentario": "Alágemo: el camaleón, lagarto.", "origen_id": "5c9707b5d4642e8c11f39566"}, {"titulo": "Verso 156.2", "texto": "\"Cualquiera que tenga dinero\nserá capaz de comprar cosas buenas\":\nadivinó Ifá para Eeka-Alajé.\nEl adivino aseguró:\n\"Ekika será muy próspero\ny hará buenas cosas\".\nSacrificio: cuatro gallinas\ny 3.200 cowries.\nEl oyó y sacrificó.", "origen_id": "65f2d2ded1173455666339e9"}, {"titulo": "Versos complementarios 1 · A", "texto": "Ifá pé Àsegbé ni eléyìun ó se\n                           ' gobgbo ihun tí bá 'se. Ifá pé kó fi òsùsù\n                                                                  ' ' owò\n                                                                       ' ' méjì kún ebo\n                                                                                    ' '\nrú.\n\nÒsá\n ' ni ò le sùn\nOorun ni ò kojú\nA díá fún Etí\nÈyí tí ´n lo' rèé gba Monífonran        ' '      Obìnrin Èfon\n                                                         ' '\nObìnrin Èfon      ' '       ni  Monífonran\n                                    ' '\nEtí bá gbà á lówó         ' ' è\nÌwo' etí\n‘Eni\n   ' tóo gba obìin è' yìí láyàa’!\n‘Yóó móo       ' ' wo' ilé tòó      ' ' wá à’\n‘Gbogbo bóo ti lè 'se é’!\n‘Ó le púpò’        '\nEtí bá to' Òrúnmìlà '                lo\nÒrúnmìlà\n '                    ní ìwo  '  Etí\nSóó le rúbo?          '\nÓ lóun ó rùú!\nÓ ní rú òsùsù     ' ' owó    ' ' méjì\nKóo rú gìrìpá òrúko'\nEtí bá rú gbogbo è'\nWón  ' bá fún un ní òsùsù             ' ' owò\n                                           ' ' kan\nÀwon    '    Babaláwo             je\n                                   ' ' òkan lérù\n´Ngbà      ó yá\nÈfón\n ' '´      bá    dé\nNí n bò' gaanran\nKó mú Etí lórí\nÈsù ' ní o dáké' ni?\n‘Ó dé nùu’\n‘Kù ú lósusu     ' ' owò   ' ' ni ì’!\nNi ón       fí  ´n ju Èfon lálé tée dòní\n      '                  ' '            '\nObìnrin è' ní ´n wáá kiri\nWìì\nNí ón              ´\n      ' bá n ju Èfon        ' '\nÒsá\n ' ni ò le sùn\nOorun ni ò kojú\nA díá fún Etí\nÈyí tí ´n lo' rèé gba Monífonran                 Obìnrin Èfon\n´Ngbà tó le tí ò wò mó' o '                              ' '\n                                '\nEtí bowò  ' ' lówè    ' '\nEtí gba Monífonran   ' '               gbé pátápátá\n\nÒsá\n '   Ìrosùn A\nIfá dice que esta persona escaparía ilesa en cualquier función o actos realizaron por él.\nÉl debe sacrificar dos manojos de escoba.\n\nÒsá no podría dormir\nEs el sueño que no molesta los ojos\nAdivinación lanzada para la Oreja\n\nEl que iba a arrebatar (agarrar, quitar) a Monífonran, la esposa de Mosquito,\nMonífonran desde principio era la esposa de Mosquito\nLa oreja la arrebato entonces de él\n'Usted Oreja' los vecinos llamaron\n'¡La persona cuya esposa que usted agarro es muy valiente!'\n'Él entraría derecho en su casa'\n'Allí nada usted puede hacer'\n'Él es muy recalcitrante (obstinado, rebelde)'\nLa oreja fue entonces a Òrúnmìlà\nUsted Oreja' Òrúnmìlà dijo\n'¿Usted puede realizar el sacrificio?'\n'Yo quiero' La Oreja dijo\nUsted debe ofrecer dos escobas\nY también un macho cabrío maduro, Òrúnmìlà dijo\nLa Oreja oyó hablar del sacrificio y lo realizó\nLa Oreja dio una de las escobas entonces\nEl Babaláwo tomó uno para el como regalo libre\nDespués de algún período de tiempo\nEl Mosquito vino llamando\nÉl vino recto sin cualquier vacilación\nPara agarrar la Oreja en su cabeza\n'Por qué usted está callado'? Èsù lloró\n¡El tiempo ha venido!\n'¡Pegúelo con el manojo de escoba!'\nÉsa ha sido alguna vez la razón por pegar a los Mosquitos con las escobas hasta la fecha\nEs su esposa por que él está pareciendo\nWìì!,\nEllos lo pegarán de una y otra vez\nÒsá no podría dormir\nEs sueño que no molesta los ojos\nAdivinación lanzada para la Oreja\nEl que iba a tomar a Monífonran, la esposa del Mosquito,\nCuando se puso ciertamente intolerable\nLa Oreja contrató la Escoba\nY agarro a Monífonran completamente.", "origen_id": "b98fce30b6980a300764b16c"}, {"titulo": "Versos complementarios 2 · B", "texto": "Ifá pé kí eléyìun ó gbóràn            `\n                           o. Gbogbo nnkan tí ón\n                      '                       ' bá so' fún eléyìun ni kó móo\n                                                                          ' ' gbó.\n                                                                                '\nEléèdìmédìro\nAwo ilé Eléèdìmédìro Awo ilé Òrúnmìlà\n                                 '\nA díá fún Òrúnmìlà\n            '\nIfá ´n sawoó relé Eléèdìmédìro\nA díá fún Eléèdìmédìro\nWón ' ní ó rúbo'\nWón ' ní kí Eléèdìmédìro ó rúbo' ojó\n                                 ' ' méje òní\n  `              ´\nNnkan àmì kàn n bò wáá selè' '\nKó là á mì\nNi kó rúbo' sí\nEléèdìmédìro fi etí òtún\n                     '   gbébo\n                            ' '\n\nÓ fi tòsì dà á nù\nKò rúbo'\nOjà ´n be' létí abúlée won    '\nÓ sì gbé eyín erin tì lókè àjà\nYóó ta Eyín Erin ´njó' ojà\n´\nNgbà    tó di ojó\n                ' ' keje\nLó bá rí olóngìnní\nOlóngìnní ta mo' etí àjà\nKó sì mó' lòó                            ´\n              ' ' kán eyín erin tí n be' lókè\nÓ ní kóun ó lè ongìnní kúò\nBí Olóngìnní ti féé    ' ' sá kúò\nOngìnní bá ko' lu eyín Erin\nEyín Erin bá ré bóólè   '' '\nÀfi pììn\nLó bá sín Eléèdìmédìro mólè         ' '\nÓ yípo yípo\nÓ yípo tì\nÒrúnmìlà\n'             ní e bóun ti wí béè     ''\nWon'   ní  bífá   ò bá 'se' lójú Awo\nÈrù\n' ò níí bògbèrì' ' jèjè   ' '\nEléèdìmédìro Awo ilé Eléèdìmédìro\nA díá fún Òrúnmìlà\n              '\nIfá ´n sawoó relé Eléèdìmédìro\nBífá ò bá 'se' lójú Awo\nÈrù\n' ò níí bògbèrì\n              ' ' jèjèèjè ' '' '\nA díá fún Eléèdìmédìro tí ón         ' ní ó 'sebo\n                                              ' '\nBéè\n  ''  ni ò  sebo\n            '' '\nÌgbà àìsebo\n         '' '\nÈgbà\n'       àìtùèrù\nÈyin\n'      e\n       ' wo Ifá ojóhun\n                    ' '       bí tí ´n se'\nÌgbà tí ò 'sebo\n             ' '\nÌgbà tí ò tu èèrù\nEléèdìmédìro wáá lo!       '\nÒsá\n '    Ìrosùn B\nIfá le pide a esta persona que considere las instrucciones o consejos dados a él.\n\nEléèdìmédìro\nEl sacerdote de las casas de Eléèdìmédìro y Òrúnmìlà\nAdivinación lanzada para Òrúnmìlà\nIfá estaba aventurando el sacerdocio a la casa de Eléèdìmédìro\nAdivinación lanzada para Eléèdìmédìro\nLe pidieron que realizara sacrificio\nEllos le dijeron a Eléèdìmédìro que sacrificara en contra de los próximos siete días\nAlgo de importancia pasaría entonces antes\nPara que él navegara con éxito a través de ello\nÉsta es la razón por qué él debe sacrificar\nEléèdìmédìro oyó el sacrificio con su oreja derecha\nY usar la izquierda para cepillarlo fuera\nÉl no realizó el sacrificio\n\nHabía un mercado entretanto al lado de su casa\nY él guardó un colmillo del elefante dentro del ático\nÉl quiso vender el colmillo en el día del mercado\nPero en el séptimo día\nÉl vio un gato\nEl gato estaba subiendo el ático\nY para impedir al gato molestar la colocación del colmillo y rompiéndolo así\nÉl intentó cazarlo de lejos\nEl gato sin embargo en este anuncio para escapar\nFinalmente chocaba con el colmillo\nEl colmillo se cayó del techo\nEn una gota de alfiler pesada\nClavo Eléèdìmédìro a la tierra\nÉl intentó volverse\nÉl no podría volverse de nuevo\n'Yo no le dije'? Òrúnmìlà preguntó\nSi las predicciones de Ifá no demostraran verdad ante un Babaláwo\nNo se instilaría el miedo en un principiante\nEléèdìmédìro el sacerdote de la casa de Eléèdìmédìro\nAdivinación lanzada para Òrúnmìlà\nIfá estaba aventurando el sacerdocio en la casa de Eléèdìmédìro\nSi las predicciones de Ifá no demostraran verdad ante un Babaláwo\nNo se instilaría el miedo en un principiante\nAdivinación lanzada para Eléèdìmédìro que fue pedido realizar el sacrificio\nTodavía él no lo realizó\nEl mal de no realizar los sacrificios\nEl problema de no dar las ganancias (premio) a Èsù\nQué Ifá dijo que el otro día se había hecho realidad\nCuando él no ofreció el sacrificio\nY no dio los regalos libres\nEléèdìmédìro se murió entonces.", "origen_id": "f65aa2524c787aa330116d85"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Osa´Rosu habla de paz y dinero como ingredientes esencial para\n                                                      el éxito y la prosperidad.\n               WO – El cliente afronta cambios repentinos en el hogar o en el\n                                                                        trabajo.\n\n\n156.1 · Paz perfecta, Osa´Rosu. La babosa vives una vida pacífica. Osa\n     ´Rosu vaticinó Ifá para Alagemo. Alagemo fue avisado para vivir una\n            pacífica y calmada vida. La vida de Alagemo será pacífica. Él fue\n      avisado para sacrificar: manteca de corojo, manteca de cacao, un pez\n                          aro grande y 18.000 cowries. Él realizó el sacrificio.\n\n\n156.2 · Cualquiera quien tenga dinero será capaz de comprar cosas\n     buenas. La adivinación de Ifá fue interpretado para Eeka-Alaje. Ekika\n          fue asegurado que llegaría a ser próspero. Él tendría muchos hijos. 4\n                  gallinas, 3.200 cowries debía sacrificarse. Él oyó y sacrificó", "origen_id": "8529df6b92f59568881704e7"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El camaleón: aceite de palma, manteca de cacao, un pescado ahumado grande y 18,000 cauríes.", "Ẹẹka: cuatro gallinas y 3,200 cauríes.", "La oreja: dos manojos de escoba y un chivo grande."], "pasajes": [{"titulo": "Ofrenda en el verso 156.1", "texto": "Tener paz y sosiego es bueno, Ọ̀sá'Rosù,\nPor el mundo va la babosa\nsuavemente (pacíficamente):\nỌ̀sá'Rosù adivinó Ifá para Alágemo.\nLe fue aconsejado a Alágemo\nir por el mundo con cautela (cuidadosamente)\ny la vida le sería fresca (pacífica).\nLe fue aconsejado hacer sacrificio:\nepo, manteca de cacao,\nun pez aro grande\ny 18.000 cowries.\nÉl realizó el sacrificio.", "origen_id": "f7c5f4b61ca577677b0d4cfe"}, {"titulo": "Ofrenda en el verso 156.2", "texto": "\"Cualquiera que tenga dinero\nserá capaz de comprar cosas buenas\":\nadivinó Ifá para Eeka-Alajé.\nEl adivino aseguró:\n\"Ekika será muy próspero\ny hará buenas cosas\".\nSacrificio: cuatro gallinas\ny 3.200 cowries.\nEl oyó y sacrificó.", "origen_id": "827e63fe6cf1df01410a50db"}]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù defiende a la oreja. Ọ̀rúnmìlà advierte a Eléèdìmédìro."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Escobas, manteca de cacao, aceite de palma, pescado ahumado, gallinas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 156.1 (yorùbá): Kẹkẹpa rere, Ọ̀sá'Rosù, / Ayé-i-kẹlẹ ni igbin wa: / Ọ̀sá'Rosù a dífá fAlágemo, / Wọ̀n niki Alágemọ / maa fi eso-ẹso ṣe ayé. / Ayé Alágemo a tutu / Wọ̀n niki ó rú / Epo, orí, eja-aro nla / ati egbàásan owó. / O ru u.", "Verso 156.2 (yorùbá): Eniti-o-ban'owó lọwọ / a ri ohun rere ra. / a difá fún Eeka-Alajé / Wọ̀n ni: / Ekika a fi owó rè ṣe ohun rere. / A rẹ. / Ebo: Adiyẹ mẹrin / ati egberindilógún owó. / Ó gbọ̀ ó rú.", "REZO: OSA ROSO KUKUTE KUKU ADIFAFUN EÑI TINSHELA OSA ADERE ADIE LEBO OBOÑA IMBEMBE.", "REZO: ADIFAFUN OSA ROSO OSHUN IYA MI IKOBOSI IYA NIWASI IYA NI YALORDE OGUIODO ABALA ABE DEBA OMI MALE ADO EWE MI KIKIRISO KEDE TOSHE KUELE KUELE YEYE MORO.", "REZO: OSHUN IYALORDE ABEBEREYISU MORO APETEBI MOBA ILE EYIGBO MEKONILE AITA INA IFA ORUNMILA, OLOFIN. OSHUN OMODENIFA OWE IKOKO LODAFUN OSHUN MAFEREFUN ELEGBA ATI SHANGO, ADIFAFUN ORUNMILA.", "REZO: OBATALA ORI AYAKA LODE AWO LAMOREGUN BOGBO LEGODO BOKINI ORI OKE OBATALA NI YEMAYA ODO AFITI ABI OPON LENU ARA WOGBE WA LAYESI KOSI NILE ONIRI ELENU MADA, ENU EYO ODOO ENI IYA AREWO WOWO TOBOSHE KUN ONI EWA.", "REZO: BABA OBAROSUN KUKUTE KUKU ADIFAFUN TINSHELU OSA ADIRO ADIE LEBO ABONA IMBERES.", "REZO: ADIFAFUN AZOJUANO NILE ORUNMILA LARE NILE OLOKUN LARIN AWO KAFEREFUN ORUNMILA LODAFUN OLUO POPO."]}]$q$::jsonb),
(157,'871891d5cb7f652382d241b1552fd92b','3d23db48d6033048d54445f36be37cd9',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Ọ̀wọ́nrín dice que es inútil huir de los problemas o de lo que puede avergonzar a la persona; debe ofrendar y mantener buen carácter para no pasar bochornos. Puede haber cambios desagradables y repentinos en la pareja. Pide no guardar rencor; llega una pareja nueva que le dará un hijo que lo hará conocido."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente avergonzado o acusado y cree que huir lo resolverá.", "Necesita aclarar públicamente que no hizo lo que le achacan.", "Un cambio en una relación le está resultando incómodo.", "Tiene obligaciones de trabajo o de familia que no puede descuidar."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que sus asuntos se vuelvan honorables.", "Que la gente acepte su carácter.", "Un hijo que lo hará conocido.", "Que nada pueda detener a su hijo."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La abundancia lleva a la proteción en contra del cambio inesperado. (Este Odu habla de la necesidad de reirse de un problema).", "origen_id": "3756615790c6b75f49f0628b"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Huir y que el mundo se burle.", "Asuntos vergonzosos por mentir, robar, chismear o ser indiscreto.", "Cambios bruscos con la pareja."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La inestabilidad lleva al caos. (Este Odu habla de la necesidad de dejar ir al deseo de control).", "origen_id": "a51c425cc412d4961f984a41"}]}, {"titulo": "Enseñanza principal", "texto": "Ọ̀sá no roba, no usa hechicería mala, no divulga los secretos de sus amigos y no dice mentiras; así sus asuntos se vuelven honorables. El buen carácter es lo que hace aceptable a la persona."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀sá'Wónrin[247] habla de que es inútil huir de los problemas y de cualquier asunto que signifique una vergüenza potencial para el cliente. El o ella deben sacrificar y ajustarse a mantener un buen carácter para evitar situaciones bochornosas (deshonrosas)", "origen_id": "87e46380a8704d239883bdef"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀sá no huye de la vergüenza. Le advirtieron a Ọ̀sá que escapar era inútil, porque el mundo lo vería y se burlaría, y que ofrendara para que no le cayeran asuntos vergonzosos: un caracol, una paloma y 32,000 cauríes. Lo hizo, y el babaláwo cantó: 'Ọ̀sá no roba, no usa hechicerías, no divulga secretos, no miente; mis asuntos son honorables; ofrecí un pájaro'.", "El perro guardián. Al perro guardián le pidieron miel, una gallina y 2,000 cauríes para que la gente aceptara su carácter. Ofreció.", "Onílẹ̀fun y el río de la riqueza. Ifá consultó para Onílẹ̀fun Tẹ̀tẹ́, que ofrecía pescado seco por tener hijos, y le pidió ofrendar y cumplir sus responsabilidades. Cumplió y tuvo paz. 'Vamos al río de Ìlẹ̀fun: Ìlẹ̀fun es la casa del dinero.'", "El escarabajo y el patinador de agua. El escarabajo volador fue a bailar a la casa de Olókun Ṣẹ̀níadé, buscando hijos. Olókun ya estaba casado con el pez, con Ìkòrò y con el caracol de agua, y cada una tenía su lugar; para el escarabajo, que era muy hermosa, no había sitio, y los hijos de las otras la corrían de un lado a otro. Tuvo un hijo con Olókun, el patinador de agua, y ofrendó por él contra los enemigos de la tierra. Tiempo después, Èṣù le dijo al hombre que echara veneno en los arroyos; murieron todas las crías de los peces, pero el patinador seguía andando sobre el agua. Así heredó la casa de Olókun, y nada lo detiene."], "pasajes": [{"titulo": "Verso 157.1", "texto": "La hoja de Ọmo: adivinó Ifá para Ọ̀sá.\nEl adivino le advirtió: \"escaparse es inútil\nporque el mundo podría verlo y burlarse de él\".\nTambién le aconsejó: \"un sacrificio debe realizar\npara que asunto vergonzoso\nno vengan a el o no recaigan sobre él\"\nSacrificio: caracol de babosa, paloma y 32.000 cowries.\nÉl lo hizo como se le dijo.\nDespués del sacrificio,\nal Babaláwo se le escuchó cantar una canción de Ifá:\nỌ̀sá no roba,\n¡hẹn!\nỌ̀sá no usa hechicerias diabólicas,\nihẹn!\nỌ̀sá no divulga los secretos de sus amigos,\njhẹn!\nihẹn!\nỌ̀sá no dice mentiras,\nMis asuntos se vuelven honorables,\nYo ofrecí un pájaro como sacrificio (3 veces).\nYo ofrecí un pájaro como sacrificio\nYo ofrecí un pájaro como sacrificio\nMis asuntos son honorables,\ny así sucesivamente.\nTodo el que estaba allí se unió al coro.", "comentario": "247 Ọ̀sáwọ́nrín: Puede estar formado por las palabras Ösátawon+nrin, que gnificaria \"Ọ̀sá ellos se están riendo\" oran itiju: problema o asunto vergonzoso.", "origen_id": "6f28f8783bc95945cbad51bd"}, {"titulo": "Verso 157.2", "texto": "Atẹwogba (la aceptación):\nadivinó Ifá para Aṣolé (perro guardián).\nAṣolé fue advertido de hacer sacrificio,\npara que su carácter pudiera ser aceptado\npor la gente del mundo.\nSacrificio: miel, gallina, 2.000 cowries.\nÉl escuchó y realizó el sacrificio.", "comentario": "asunto vergonzoso: las actitudes que pueden llevar a este cliente a un asunto vergonzoso son: mentir, robar, chismear, la indiscreción, la delación, la imprudencia, la hechicería y cualquier manifestación de un mal carácter.", "origen_id": "f8c768e02b1f6db92109210a"}, {"titulo": "Versos complementarios 1", "texto": "' '        A\nIfá pé ayé ó ye' eléyìun; nnkan è' ò níí bàjé.\n                                            ' Ifá pé kó jókòó ti nnkan è.\n                                                                       ' Kó sì mójú tó.\nIsé' ' nìse' ìtójú'\nÒwò síse   ' ' nìbéèrè\nBí ón   ' bá n gbóndo  '         lójò\nOmi a móo        ' ' ta sí on' lójú\nOmi a móo        ''  ta  sí  on\n                             ' lénu'\nA díá fún Onílèfun Tèté\nOmo                                    ´´\n ' ' Akéja      ' wúrúkú borí        ' ntorí omo\n                                             ' '\nWon   '    ní  kí   Onílèfun      ó  rúbo\n                                        '\nÓ bá rúbo'\nAyé ye' é'\nOkàan\n '           è' balè'\nNí wá ´´     n jó n ní ´´n yò'\nNí ´´n yin àwon      ' Babaláwo\nÀwon         Babaláwo         ´´\n                              n yin Ifá\n         '\nÓ ní béè    ' ' làwon ' Babaláwo tòún wí\nIsé'' ' 'nìse  ìtójú\nÒwò síse   ' ' ´´nìbéèrè\nBí ón   ' bá n gbóndò  '         lójò\nOmi a móo        ''  ta  sí  on\n                             ' lójú\nOmi a móo        ' ' ta sí on' lénu'\nA díá fún Onílèfun Tèté\nOmo                                    ´´\n ' ' Akéja      ' wúrúkú borí        ' ntorí omo\n                                             ' '\nEbo\n ' ' n wón      ' ´´ní ó se'\nÓ sì gbébo    ' ' nbè'\nÓ rúbo'\nE' jé' á rodò ´´     nIlèfun\nÌlèfun mòmò nilé owó\nE' jé' á rodò ´´     nIlèfun\n\nÒsá\n ' Òwónrín\n      ' '       A\nIfá dice que la vida agradaría a esta persona y sus planes no se romperían. Ifá le pide ser\ncomprometido a sus responsabilidades y ser obediente a ellos.\n\nCuidar es una responsabilidad obediente\nComerciar es un acto de cuestionar\nCuando ellos agotan los ríos en la lluvia\nEl agua salpicaría hacia sus caras\nEl agua salpicaría en sus bocas\nAdivinación lanzada para Onílèfun Tèté\nEl niño de Akéja wúrúkú borí ntorí omo\nLe pidieron que realizara sacrificio\nÉl lo hizo\nY la vida lo agradó\nÉl tenía descanso de mente\nÉl empezó a bailar y regocijar entonces\nÉl estaba alabando sus Babaláwos\nSus Babaláwos estaban alabando Ifá\n\nÉl dijo que era exactamente como sus Babaláwos habían dicho\nCuidar es una responsabilidad obediente\nComerciar es un acto de cuestionar\nCuando ellos agotan los ríos en la lluvia\nEl agua salpicaría hacia sus caras\nEl agua salpicaría en sus bocas\nAdivinación lanzada para Onílèfun Tèté\nEl niño de Akéja wúrúkú borí ntorí omo\nLe pidieron cuidar de la tierra y realizar el sacrificio\nÉl oyó hablar del sacrificio\nY lo realizó\nPermítanos ir al río en Ìlèfun\nÌlèfun es la casa de dinero\nPermítanos ir al río en Ìlèfun..\n\nÒsá\n ' Òwónrín\n      ' '       B\nIfá pé kí eléyìun ó mó' jà o, Obìnrin kán ´´n bò' wáá fé' e.\n                                                          ' Àwon\n                                                                                    ´´\n                                                                ' Obìnrin tí ó bàá nlé ò níí\nféràn\n  '    ìyàwó tuntun. Ifá pé Obìnrin òhún\n                                     '      ní ó sì bí omo\n                                                       ' ' tí eléyìun ó fi lòóko' láyé.\n\n'Eye' wéréwéré\n         ' ' ' ' abìyé' wéréwéré     ' ' ' '\nEye\n ' ' ' ' ' ' abìyé' wéréwéré\n      wéréwéré                       ' ' ' '\nA día fún Olóbònhùnbohùn\n              '     '     '          '\nÈyí tí ´´n sòwò arrijo relé Olókun Sèníadé          '\nOlóbònhùnbohùn\n ' ' '              '        ní ´´n bèèrè\nIlé Olókun Sèníadé  '          tóun ´´   n lo' yìí dáa báyìí?\nWón'   ní   kó  rúbo    '\nÓ sì ti wá omo' ' wá omo      ' '\nKò rí\nEja,\n ' Obìnrin Olókun ni\nÌkòrò, Obìnrin Olókun níí se               '\nÌsin pàápàá, Obínrin Olókun lòun náà\nOlokún ti fé' gbogbo won             ' télè\nÓ sì fún gbogboo won           ' ní káà lo'\n´´\nNgbà tí Olóbònhùnbohùn\n            ' ' '                '         dé òhún\n                                               '\nKò rí ibi fi Olóbònhùnbohùn\n                 ' ' '                 '       wò' sí\nÓ sì dáa láwò'\nOlóbònhùnbohùn\n ' ' '              '        bá ´´n fòó ká gbogbo ilé\nBó bó' síhìín\nÀwon ' omo' ' Eja  ' a pé ilé ìyá àwon           '\nÓ bó' sóhùún\n          '\nÀwon                                         ´´\n     ' omo' ' Ìkòrò a lé e kúò nbè'\nÀwon ' a pé káà ìyá àwon            ' ni\nOlóbònhùnbohùn\n ' ' '              '        ò rí ibì kan dúó sí\n´´\nNgbà ó yá\nÓ bá bímo' fún Olókun\nÒun ló bí Ìròmi\nWón' ní ìwo Olóbònhùnbohùn\n                    ' ' '                '       rúbo' fún omoò\n                                                           ' ' ' re'\nWón'   ní   rúbo '    ayé   o\nÓbá pèsè fáwon         ' ayé\nOlóbònhùnbohùn\n ' ' '              '        rúbo'\n\nEbo     è pé\n´´' '\nNgbà ó dèèkan   ''\nÈsù'    bá   ní  kí wón   ' ó dòògùn sódò\nÒògún mú gbogbo omo                ' ' Eja\n                                         ' pátá\nÒògùn ò leè mú Ìròmi\nNí ´´n yan kiri lójú omi\nN ní wá ´´n jó ní wá ´´n yò'\nNí ´´n yin àwon Babaláwo\nÀwon                           ´´\n       ' Babaláwo n yin Ifá\nÓ ní béè   ' ' làwon  ' Babaláwo tòún wí\nEye\n ' ' ' 'wéréwéré    ' ' abìyé' ' '  wéréwéré ' '\nEye     wéréwéré\n ' ' ' ' ' '               abìyé    wéréwéré\n                                   ' ' ' ' '\nA díá fún Olóbònhùnbohùn\n                  '   '     '         '\nÈyí tí ´´n sòwò arrijo relé Olókun Sèníadé         '\nErebete\n ' ' ' ' sé'\nÈrèbètè\n ' ' ' ' sé'\nErebete\n ' ' ' ' sé' sèè     ' ' sé'\nIlé tí ón ' ní n gbodò      ' ' dé\nErí\n '     deri\n         '    Ìròmi\n'Erebete\n     '  '   ' sé'\nÈrèbètè\n ' ' ' ' sé'\nErebete\n ' ' ' ' sé' sèè     ' ' ``sé'\nÀkòdì tí ón    ' ní n gbodò       ' ' wò'\nÀkòdí ti di tÌròmi\nErebete\n ' ' ' ' sé'\nÈrèbètè\n ' ' ' ' sé'\nErebete\n ' '    ' ' sé' sèè  ' ' sé' ``\nGbogbo ibi tí ón         ' ní n gbodò   ' ' dé\nGbogbo è' ló wáá di tÌròmi\nErebete\n ' ' ' ' sé'\nÈrèbètè\n ' '     ' ' sé'\nErebete\n ' ' ' ' sé' sèè     ' ' sé'\nÌròmi bá ´´n sáré lójú omi\nGbogbo ibi àwon            ' omo ' ' Eja ní kò gbodò ' ' wò'\nÌròmi ló wáá padà nilé Olókun Sèníadé            '\nKinní kan ò le mú Ìròmi mó.                '\nÒsá\n ' Òwónrín\n       ' '       B\nIfá le pide a esta persona que no guarde la malicia con cualquiera. Una cierta mujer está\nviniendo a casarse a le o si él es un hombre. La esposa incumbida no le gustaría. Es la\nnueva mujer que le daría el niño que haría a esta persona popular en la vida.\n\nLos pájaros pequeños con las plumas pequeñas\nLos pájaros bonitos con las plumas llenas de colores\nAdivinación lanzada para el Escarabajo volante\nUn acto del baile aventurando en la casa de Olókun Sèníadé\nEs el Escarabajo que estaba preguntándole a Ifá\n'¿La casa de Olókun es que yo voy lleno de cosas buenas?\nEllos le dijeron que realizara el sacrificio\nPero ella había estado buscando mucho tiempo por niños\n\nElla no había tenido ninguno\nEl pez, era una esposa de Olókun\nÌkòrò, también era una esposa de Olókun\nEl caracol de agua también era una esposa de Olókun\nOlókun se había casado a todos ellos previamente\nÉl dio a cada uno, sus salones de descanso respectivos y salas\nPero cuando el Escarabajo llegó allí\nOlókun no podría encontrar un lugar para ella\nSin embargo, el Escarabajo era muy bonito\nElla empezó a volar alrededor de la casa entonces\nSi ella vuela aquí\nEl niño del Pez diría que el lugar perteneció a su madre\nSi ella descansara en el otro extremo\nLos niños de Ìkòrò la perseguirían lejos\nEllos dirían que era el salón de descanso de su madre\nEl Escarabajo no podría encontrar un lugar de descansando\nDespués de un período\nElla tenía un niño para Olókun\nEl niño es el patinador de Agua\n'Usted el Escarabajo, ofrezca sacrificio para su niño' ellos advirtieron\nEllos le pidieron que realizara el sacrificio contra los enemigos terrenales\nElla hizo la prevención para los enemigos\nEl Escarabajo realizó todos los sacrificios\nEstaba muy lleno\nDespués de un período prolongado de tiempo\nÈsù le pidió al hombre que vertiera el veneno en los arroyos\nEl veneno mató a todos los bebés del Pez completamente\nEl veneno no podría matar a patinador de Agua\nÉl estaba vagando sobre la superficie de agua\nÉl empezó a bailar y regocijar entonces\nÉl estaba alabando sus Babaláwos\nSus Babaláwos estaban alabando Ifá\nÉl dijo que era exactamente como su Babaláwos había dicho\nLos pájaros pequeños con las plumas pequeñas\nLos pájaros bonitos con las plumas vívidas\nAdivinación lanzada para el Escarabajo volador\nUno que aventura el acto del baile en la casa de Olókun Sèníadé\nErebete sé\nErèbètè sé\nErevete sé sèè sé\nLa casa que ellos me pidieron que no entrara\nTodo se ha vuelto una propiedad poseída por el patinador\nErebete sé\nErèbètè sé\nErevete sé sèè sé\nEl apartamento de Àkòdí ellos me prohibieron entrar\nTodo se ha vuelto una propiedad poseída por el patinador\nErebete sé\nErèbètè sé\nErevete sé sèè sé\n\nTodo el lugar que ellos dijeron que yo no debo ir cerca (próximo, casi, intimo)\nTodo se ha vuelto una propiedad poseída por el patinador\nErebete sé\nErèbètè sé\nErevete sé sèè sé\nEl patinador de Agua empezó el patinaje después en las superficies de agua\nTodos los lugares que le pidieron que no entrara\nEs el Patinador que heredó la casa de Olókun\nNada podría detenerlo de Nuevo.", "origen_id": "247ef9a8812e5871622793d2"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Osawonrin habla de la inutilidad de huir de los problemas y\n                                                 asuntos de posible vergüenza.\n      WO - El cliente puede encontrar rápidamente cambios desagradables\n                                                             en sus relaciones.\n\n\n157.1 · La hoja de Omo adivinó para Osa. Advirtiéndole de que\n           escaparse es inútil porque el mundo podría verlo y burlarse. Le fue\n                advetido de hacer sacrificio para que asuntos de vergüenza no\n             recayeran sobre él. Ebo: 1 caracol de babosa, 1 paloma y 32.000\n                 cowries. Él lo hizo como se le dijo. Después del sacrificio, el\n          babalawo se le escuchó cantar una canción de Ifá: Osa no roba, hen!\n           Osa no usa hechicerías del diablo, hen! Osa no divulga secretos de\n             sus amigos, hen! Osa no dice mentiras, hen! Mi asunto se vuelve\n\nhonorable, Yo ofreci un pájaro como sacrificio (3 veces). Mi asunto\n          se vuelve honorable, y así sucesivamente. Todo el que estaba allí se\n                                                                 unió al coro.\n\n\n157.2 · Atewogba (la aceptación) adivinó para Asole (perro guardián).\n     Asole fue advertido de hacer sacrificio para que su carácter pueda ser\n     aceptado por la gente del mundo. Ebo: miel, 1 gallina, 2.000 cowries.\n                                            Él escuchó y realizó el sacrificio.", "origen_id": "17b83114e95f5b947a163731"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀sá: un caracol, una paloma y 32,000 cauríes.", "El perro guardián: miel, una gallina y 2,000 cauríes.", "Por el hijo: ofrenda contra los enemigos de la tierra."], "pasajes": [{"titulo": "Ofrenda en el verso 157.1", "texto": "La hoja de Ọmo: adivinó Ifá para Ọ̀sá.\nEl adivino le advirtió: \"escaparse es inútil\nporque el mundo podría verlo y burlarse de él\".\nTambién le aconsejó: \"un sacrificio debe realizar\npara que asunto vergonzoso\nno vengan a el o no recaigan sobre él\"\nSacrificio: caracol de babosa, paloma y 32.000 cowries.\nÉl lo hizo como se le dijo.\nDespués del sacrificio,\nal Babaláwo se le escuchó cantar una canción de Ifá:\nỌ̀sá no roba,\n¡hẹn!\nỌ̀sá no usa hechicerias diabólicas,\nihẹn!\nỌ̀sá no divulga los secretos de sus amigos,\njhẹn!\nihẹn!\nỌ̀sá no dice mentiras,\nMis asuntos se vuelven honorables,\nYo ofrecí un pájaro como sacrificio (3 veces).\nYo ofrecí un pájaro como sacrificio\nYo ofrecí un pájaro como sacrificio\nMis asuntos son honorables,\ny así sucesivamente.\nTodo el que estaba allí se unió al coro.", "origen_id": "e6bcc3f48ddb4d8487ab9f4b"}, {"titulo": "Ofrenda en el verso 157.2", "texto": "Atẹwogba (la aceptación):\nadivinó Ifá para Aṣolé (perro guardián).\nAṣolé fue advertido de hacer sacrificio,\npara que su carácter pudiera ser aceptado\npor la gente del mundo.\nSacrificio: miel, gallina, 2.000 cowries.\nÉl escuchó y realizó el sacrificio.", "origen_id": "f4638843e0cb4ad6885474dc"}]}, {"titulo": "Relaciones espirituales", "texto": "Olókun (Ṣẹ̀níadé) acoge al hijo del escarabajo. Èṣù castiga a los que no ofrendaron."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de ọmọ, miel, caracol, paloma, pescado seco."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 157.1 (yorùbá): Ewé Ọmọ: li o difá f'Ọ̀sá. / Wọ̀n ni: \"sisa tiomaa sá yi Ayé a riimu, / wọ̀n a maa fi rerín\" / wọ̀n ni: \"ẹbọ niki o ṣe / ki òràn itiju ma baa de sii\". / İgbin, eyẹlé, egberindilógún owó. / Ó gbọ̀ ó rú. / Nigbati o rubo tan a ngbọ / Babaláwo nkorin Ifá: / Ọ̀sá mama jale o, / hẹn! / Ọ̀sá mama sá oògùn Ìká o, / hẹn! / Ọ̀sá mama tu aṣiri orẹ o, / hẹn! / Ọ̀sá mama ṣ'eke o, / hẹn! / Oràn mi d'eyeyẹ, mom'eyẹ rúbọ / Oràn mi d'ẹyẹyẹ, mom'ẹyẹ rúbọ / Oràn mi d'ẹyẹyẹ, mom'ẹyẹ rúbo / Ọràn mi d'eyeyẹ ati beebẹẹ. / Gbogbo èniyàn tiowa nibẹ si nba / wọn gbe orin naa.", "Verso 157.2 (yorùbá): Atẹwogba: / li o dífa fAṣolé (Aja). / A niki Aṣolé wa rubẹ, / ki iwà rẹ̀ baa le wọ aarin / àwọn pmọ aráyé. / Oyin, adiyẹ, igbio (owó) l'ebọ. / Ó gbọ̀ ó rú.", "REZO: OSA LONI OJUANI ONI EGGUN OSA NI OYE OMO BEBENIYO.IFA OMO ONI SHANGO AWO ONI OJUANI OGGUN AWANI IFA OMO ALARA.", "REZO: OLOFIN ADAWAUYE BOKUN BOGBO OMODE DANDAJUERO ADIFAFUN ORUNMILA INSHE-OZAIN. MAFEREFUN ORUNMILA.", "REZO: OSABE OJUANI ONI EGGUN NI OYO OMO ONI SHANGO AWO ONI JUANI AGON ASA NI IWA OMO ALARA.", "REZO: OBATALA OMO NI AWO OBAYI YELE UN AMALABA OSA JUANI OMO OBAYIYAWO MUYEFE OSA JUANI OSHISHE OTAMILEIKO OBAYERE AWO MALAMLA ABERI ORUNMILA MULANLA OBA IKO OBA NI INLE MOLANLA KASAIBE KUN ISHE MOLANLA ABERI ORUNMILA MOWA LADE IYALE ABE YERE MORO LODAFUN SHANGO MAFEREFUN ESHU IFA MOLAMLA.", "REZO: OSAGUERE KOMAGUAN AGUAYI OSA OMONI KOMALA NASHE LA NAKUAYO KOMA GUA GUA GUAYI KOMA KORODO KAFO WA KOMA OIYO LASHEDIN ISHOKO ELEBUTE OKUN LAYE NI OMA WOSHE OMO NI SHANGO ALADASHE UN OIYO OKUN OMO NI YEMAYA ODABI LAYE ASIA PUPUA ODASHE WA ASIA ARO ISOYE IFA NI KAFEREFUN YEMAYA NI SHANGO."]}]$q$::jsonb),
(158,'13abdb1b44131bbc033db0e2ec07d199','ee5ad0436b4ead69ca507506ecef45e2',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Ọ̀bàrà habla del peligro de perder seguidores o a una persona querida, y enseña cómo hacer regresar a quien se fue. La persona puede disfrutar de lo que le llega sin buscarlo. Si es babaláwo o hijo de babaláwo, debe seguir el oficio de su padre: la riqueza le llega quedándose en su lugar. Cuidado al ayudar a otros: que el bien no se le vuelva en contra."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme perder el apoyo de quienes lo acompañaron (relato de Akeregbe).", "Una amistad se enfría por orgullo o porque solo da una parte.", "Quiere revivir una relación o un proyecto que parecía terminado."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que regrese el que huyó.", "Regalos y ganancias sin tener que salir a buscarlos.", "Que el matrimonio se sostenga por respeto a quien lo hizo posible."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La abundancia lleva a la transformación. (Este Odu habla de la necesidad de soportar a esos que han sido sustentados en el pasado.)", "origen_id": "e5f045572a2debbe7dd6f8c9"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Ser abandonado por los suyos en su mejor momento.", "Perder el control de sí mismo por miedo.", "Dejar el oficio de la familia."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La inestabilidad mental lleva al egoismo. (Este Odu habla de la posibilidad de arrogancia causando una perdida de amistad)", "origen_id": "f97ce72e666313d211c48f15"}]}, {"titulo": "Enseñanza principal", "texto": "El cobarde es el que pierde el control de sí mismo. Y a veces la riqueza no se encuentra andando: Dúrówojú buscó trabajo por todas partes hasta que se sentó en el lugar de su padre."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀sá-Bàrà habla del peligro de perder partidarios, seguidores o un individuo.", "origen_id": "e892af0ff7cf23f3d4da328b"}]}, {"titulo": "Relatos reunidos", "puntos": ["El cántaro y sus seguidores. 'El cobarde es quien pierde el control de sí.' Al cántaro, que dependía de su mujer y sus hijos pequeños, le pidieron una paloma, una gallina y 6,600 cauríes para que sus seguidores no lo abandonaran de repente en su momento de gloria. No ofreció.", "Que regrese el que huyó. 'Ọ̀sá regresa pronto; si se va lejos, vuelve rápido a casa. Fulano regresa rápido.' Es un rezo para traer de vuelta a quien se fue.", "Dúrówojú y el oficio del padre. Los padres de Dúrówojú eran babaláwo, que se sientan en un lugar y la gente llega a consultar. Le dijeron que siguiera exactamente el oficio de su padre, pero no quiso y salió a buscar trabajo por todas partes sin éxito. Cuando por fin se sentó a consultar como su padre, le llegaron los clientes y los regalos.", "Oníyèyè y el que la casó. Ológoṣé Jùkú fue quien abrió el camino para que Oníyèyè se casara con su primer esposo. Con el tiempo el marido ya no se portaba bien, y ella habría dejado la casa, pero se quedaba por respeto a Ológoṣé Jùkú, que la había presentado. Así se sostuvo el matrimonio."], "pasajes": [{"titulo": "Verso 158.1", "texto": "\"El cobarde (miedoso)\nes quien pierde la capacidad\npara controlarse a sí mismo\":\nadivinó Ifá para Akeregbe\ncuando dependía de su mujer\ny sus hijos jóvenes.\nLe fue aconsejado a Akeregbe sacrificar,\npara que él no fuera abandonado de repente\npor sus seguidores (partidarios)\nmientras él estaba en su gloria.\nSacrificio: paloma, gallina\ny 6,600 cowries.\nEl escuchó y no sacrificó.", "comentario": "Akeregbe: calabaza grande que usan los nativos como cántaro para transportar", "origen_id": "00504f06c343f29ca2347265"}, {"titulo": "Verso 158.2", "texto": "Ọ̀sá regresa rápidamente,\nsi él huye lejos,\nel regresa a casa rápidamente.\n(¡Fulano!) regresa rápidamente.\nRápidamente un joven\nregresa a la granja de Èèsin.\n(¡Fulano!) también regresa rápidamente.", "comentario": "251 éèsin: URERA MANII (Wedd.) Benth. &Hook. f., Urticaceae y MUCUNA PRURIENS (L.) DC., Leguminosae Papilionoidea.\n252 éesin-funfun: planta no identificada.", "origen_id": "e0c6ccbaee6b147e3bfc5276"}, {"titulo": "Versos complementarios 1", "texto": "'         A\nIfá léleyìun wáá je' láyé. Tó bá jé' obìnrin ló dá Ifá yìí, isé                              ´´\n                                                             ' ' àjókòólè' se\n                                                                           ' nisée\n                                                                               ' ' ' rè.\n                                                                                      ' Bí bá n\nkirií ki, isée\n           ' ' ' rè' ó dànù. Tprí Ifá nìraan rèé\n                                              ' ' je.\n                                                   '\nÒ' sa bàrà mú tà\nA díá fún Dúrówojú\nOmo\n ' ' Ajèèrùsolà         '\nWón' ní bíi isée       ' ' baba è' ni kó móo     ' ' se\n                                                     '\nAwo ni baba Dúrówojú\nAwo sìí jókòó kalè' ni\nWón' ó móo      ' ' wáá wá\nWón'      ó  dàá    Ifá lówó' ' è'\nÒun náà ó ki Ifá fún won              '\nWón'      ó  wàá     rúbo   '\nWón'      ó  sì  fún    un    lówó\nSùgbón\n '       ' Dúrówojú ò fé' gbogbo èyuun\nNí bá ´´n kirií kiri\nWón          ´´\n   ' ``ní ngbà tó bá se bíi ti babaa rè\nNi nnkan rè' ó tòó gún\nNi Dúrówojú bá jókòó kalè'\nNi wón            ´´`\n         ' bá      n wá\nNi ón      bá ´´`\n                n  mú ajé wá\n     '\nWón' làwon      ' ò pèé jókòó tisée       ' ' ' babaà re'\nNi Dúrówojú bá´´`             n ji ní´´`\n                                       n yò'\nNí´´`\n    n yin àwon       ' Babaláwo\nÀwon   '    Babaláwo           náà´´`\n                                    n yin Ifá\nÓ ní béè   ' ' làwon  ' Babaláwo tòún wí\nÒ' sa    bàrà     mú     tà\nA díá fún Dúrówojú\nOmo\n ' ' Ajèèrùsolà         '\nKín làwá n seé là nlée wa?\nÈèrù\nÈèrù làwá´´`       n jeé là´´`  nlée wa\nÈèrù\n\nÒsá\n ' Òbàrà\n      '      A\nIfá dice que esta persona está en el mundo disfruta regalos libres. Si esta persona es una\nmujer, su trabajo es circunstancial en eso que ella tendría que quedarse en un lugar para\nganar su dinero del cielo. Si esta persona anda para buscar la riqueza, ella nunca lo\nconseguiría.\n\nÒ sa bàrà mú tà\nAdivinación lanzada para Dúrówojú\nEl niño de Ajèèrùsolà\nEllos le dijeron que practicara la profesión de su padre exactamente\nLos progenitores de Dúrówojú eran Babaláwos\nY Babaláwos se sentarían en un lugar particular\nLas personas vendrían de todo caminar de vida\nÉl lanzaría la adivinación para ellos\nÉl les pediría que realizaran los sacrificios\n\nY el dinero se daría al Babaláwo\nPero desde que Dúrówojú no quiso ninguno de éstos\nÉl empezó a pasar buscando un trabajo\n'No hasta cuando usted sigue los pasos de su padre\n'Entonces habría sus cosas ser buenas'\nDúrówojú se sentaba después\nEllos estaban consultándolo\nEra entonces que ellos lo recordaron su consejo más temprano\nDúrówojú empezó a bailar y regocijar entonces\nÉl estaba alabando su Babaláwo\nÉl dijo que era exactamente como su Babaláwo había predicho\nÒ sa bàrà mú tà\nAdivinación lanzada para Dúrówojú\nEl niño de Ajèèrùsolà\n¿Qué nosotros cosechamos en nuestra familia?\nLos regalos libres\nEs ganancia libre que nosotros disfrutamos en 'nuestra casa\nLos regalos libres.\n\nÒsá\n ' Òbàrà\n      '      B\nIfá pé eléyìun ó se\n                  ' rere fún èèyàn; kí wón ' ó mó' wàá so' oore òhún\n                                                                   '     dibi mó' o lówó\n                                                                                      ' ' ni kó\nse pèlépèlé\n' ' ' ' '   si. Ifá pé bó bá sì jé\n                                 ' pé eléyìun    ni wón\n                                                      ' soore fún,  oore òhún\n                                                                         '     ó fèé\n                                                                                  ' ' yègè,\n                                                                                       ' '\nsùgbón\n'    ' eni\n         ' ó se\n              ' atònà\n                    ' oore òhún\n                              '     ni ò níí jé' kí oore òhún\n                                                         '    ó yègè.\n                                                                 ' '\nOlógosé     ' ' jùkú\nLó día fún Oníyèyè mokò\nNíjó' tí ´´n lo' ilé oko    ' ' àárò'\nWón'      ní    ó  rúbo  '\nAlátònà '        ló  sì  se\n                         ' atònàa'    rè'\nTée dé ilé oko      ' '     àárò '\nWón      ´´n se ilé okoó lo\n´´ '          '          ' '' '\nNgbà ó dààrin kan\nÒró          ´´\n ' ' bá n mì\nOko\n ' ' è' ò se     ' dáadáa mó'\nBí ó bàá wí\nA pé ti Ológosé                           ´´\n                          ' ' jùkú lòún n wò\nTó se' atònà    ' òun\nOníyèyè Ì bá lo'\nWón' ní kó´´móo          ' '´´wo ti Ológosé  ' ' jùkú\nNí wá n jó n ní n yò'\nNí ´´n yin àwon       ' Babaláwo\nÀwon         Babaláwo          ´´\n                                n yin Ifá\n      '\nÓ ní béè    ' ' làwon   ' Babaláwo tòún wí\nOlógosé     ''    jùkú\nA díá fún Oníyèyè mokò\nNíjó' tí ´´n relé oko    ' ' àárò'\nOníyèyè Ì bá lo'\nBí ò bá sí Ológosé            ' ' jùkú\nOníyèyè Ì bá lo'\n\nÒsá\n ' Òbàrà\n      '      B\nIfá dice que esta persona ayudaría a alguien; él se advierte tal que este acto bueno no se\nvolvería contra él. Al contrario, si es esta persona que recibió la ayuda de otra persona,\nla ayuda puede intentar caerse en pedazos pero la persona que pavimentó el camino para\nla ayuda lo permitiría.\n\nOlógosé jùkú\nAdivinación lanzada para Onìyèyè mokò\nCuando ella estaba casándose al primer marido\nLe pidieron que realizara sacrificio\nEra un mediador que pavimentó el camino para ella casarse\nHaciéndolo fácil para ella conseguir a su marido\nEllos continuaron en el asunto matrimonial\nAproximadamente un tiempo particular\nHabía un problema\nEl marido no estaba haciendo bien de nuevo\nPero cuando la mujer informaría\nElla diría que ella estaba respetando sólo Ológosé jùkú\nQuién pavimentó aquí\nOníyèyè habría partido (abandonado, salir, dejar, partir, irse)\nElla fue mandada para ser considerada a Ológosé jùkú\nElla empezó a bailar y regocijar entonces\nElla estaba alabando su Babaláwo\nSu Babaláwo estaba alabando Ifá\nElla dijo que era como su Babaláwo había dicho\nOlógosé jùkú\nAdivinación lanzada para Oníyèyè mokò\nCuando ella estaba casándose al primer marido\nOníyèyè habría partido\nSi no debido al respeto para Ológosé jùkú\nOníyèyè habría partido", "origen_id": "6c4e18990f50e8f8c58cc566"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Osa-Bara habla del peligro de la pérdida de partidiarios o\n                                                            individualidades.\n           WO – Muestra al cliente como despertar aparentes llamas muertas.\n\n\n158.1 · Los cobardes dan lugar a las penas fue adivinado para\n               Akeregbe (la calabaza) quien dependía de su mujer y sus hijos\n     jóvenes. Le fue aconsejado sacrificar. Ebo: 1 paloma, 1 gallina, 6.600\n     cowries con el objeto de que él no pudiera ser abandonado de repente\n             por sus sostenes mientras él estaba en su gloria. Él escuchó y no\n                                                                    sacrificó.\n\n\n158.2 · Osa regresa rápidamente si él huye lejos, el regresa a casa\n\n   rápidamente, “fulano” regresa rápidamente. Un hijo pequeño debe\n    correr rápidamente fuera de la granja de Eesin. “fulano” también\n   regresa rápidamente. Hojas de Ifá: dividir en 6 pedazos la nuez de\n  kola, tomar 6 hojas blancas de eesin (esin- wara) marcar Odu Osa-\n  Bara sobre el tablero de Ifá con iye-irosu, recitar el sortilegio como\n    está establecido arriba usando el nombre de la persona que huyó.\nEntonces hechar un poco de iye-irosun sobre la hoja de eesin con una\n     válvula (baba) de la nuez de kola y llevar esto hacia fuera o a la\n   entrada del pueblo. Repetir este proceso 6 veces. Esto es utilizado\n         para atraer a alguien que a huído, de regresó a casa. La cosa\n sorprendente acerca de este Ifá, es que por larga que sea la distancia\n de la persona que huyó, es seguro que oirá como lo llaman. La hoja\nde eesin, una baba de nuez de kola (pedazo) y un poco de iye-irosun,\n    todo esto utilizado 6 veces es completamente suficiente para este\n propósito. Hechar aceite sobre Eşu tan pronto como sea completada\n                                                          la operación.", "origen_id": "c1e3279ee80f957e800c773c"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El cántaro: una paloma, una gallina y 6,600 cauríes.", "Para que vuelva quien huyó: una kola de seis gajos partida en seis, seis hojas blancas de ẹ̀ẹ̀sìn, iyẹ̀-ìrosùn marcado con el signo y el rezo diciendo el nombre de la persona; cada hoja con un gajo y un poco de polvo se lleva al Èṣù de la entrada del pueblo, seis veces, y al final se echa aceite sobre Èṣù."], "pasajes": [{"titulo": "Ofrenda en el verso 158.1", "texto": "\"El cobarde (miedoso)\nes quien pierde la capacidad\npara controlarse a sí mismo\":\nadivinó Ifá para Akeregbe\ncuando dependía de su mujer\ny sus hijos jóvenes.\nLe fue aconsejado a Akeregbe sacrificar,\npara que él no fuera abandonado de repente\npor sus seguidores (partidarios)\nmientras él estaba en su gloria.\nSacrificio: paloma, gallina\ny 6,600 cowries.\nEl escuchó y no sacrificó.", "origen_id": "6171e0a2dc916aa3ac9145d0"}]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù de la entrada del pueblo hace volver al que se fue."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Kola de seis gajos, hojas de ẹ̀ẹ̀sìn (Urera mannii o Mucuna pruriens), iyẹ̀-ìrosùn, aceite de palma."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 158.2", "texto": "Se necesita una nuez de kola de seis lóbulos, dividirla en seis secciones, tomar seis hojas blancas de éèsin?1 (èèsin- fúnfún?52), marcar el Odù Ọ̀sá-Bàrà sobre iyẹ̀-irosù en el tablero de Ifá, recitar el encantamiento anterior como está establecido usando el nombre de la persona que huyó (Lagbaja, significa fulano). Entonces echar un poco de iyè-irosu sobre una hoja de éésin con una sección de la nuez de kola , llevar esto hasta el Eṣú que está afuera de la ciudad o a un camino de entrada del pueblo. Repetir este proceso seis veces.\nEsto es utilizado para atraer a alguien que ha huido, para regresarlo a la casa. La cosa sorprendente acerca de este Ifá, es que por larga que sea la distancia de la persona que huyó, es seguro que oirá como lo llaman. La hoja de éèsin, una sección de nuez de kola (o pedazo) y un poco de iyè-irosù, todo esto utilizado seis veces es completamente suficiente para este propósito. Echar aceite sobre Eṣú tan pronto como sea completada la operación.", "origen_id": "b0428533a2b30804b0a78f2e"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 158.1 (yorùbá): Ojo nii barajẹ: / a difá fún Akeregbe, / nigbi Akeregbe gbẹkẹle obirin / ati awọn omodé. / A niki Akeregbe wa rúbo, / ki àwọn ti nṣe elegbe / lẹhin rẹ ma le yeẹsilẹ lojüji lojo / tiowa ninu ola rẹ. / Ebọ: Ẹyẹle, adiyẹ / ati egbẹ̀talélógbọ̀n owó. / Ó gbọ̀ ko rú.", "Verso 158.2 (yorùbá): Ewé Ifá: Ao pa Obi (iwarẹfa) alawẹ méfà, ewé èèsin (fúnfún) / wara mẹfà. Ao tẹ iyẹ̀-irosù ni Odù Ọ̀sá-Bàrà ninu Ọpọ̀n-Ifá. / Kiapee biatiwi loke ati oruko ẹninaa ti o salo, ao maa bu iyè-irosu / naa sinu ewé èèsin ati awẹ obi kan kiamaa gbee lọ sidi Èṣú / nigbamgba ita tabi li ona ni ẹnubode ilú. Bayi li aoṣe ti aofi rin / nigba mẹfà lo sidi Éṣú. / Eyi liafi npe aisa bowa'lé. Ohun iyanu tiowa nibẹ niipe biati / npee, oun yoo maagbą ohun wa ni eti rẹ. Ewé èèsin kan ati awẹ / obi kan, titi yoo fi tan. Ki a ta epo sori Eṣú biaba ti ṣetan. / Qsábowàrà, / biobasalo kiipẹde. / (Lagbaja)! Ṣekiobowàrà. / Wàràwàrà li omodé i bọ oko Éèsin. / (Lagbaja)! Ṣeki obowarà.", "REZO: OSA BARA OSA SHEPE OSA BANI YEREKUN OBA NI SHANGO OSA YIREAWO NILAYE INLE OSA SHEPE ONILEKUN.", "REZO: OSA BARA OBARABARA OGUALODE OBARA MALLE LODIFAFUN ONIBARA AMAIGUI TIGUI TILO DIALLE.", "REZO: OSA BARA BATRA ILE YEMAYA OSA BARA BARA LONA ADIFAFUN DIRE DERERE TINCHE DILLI ABANA LEGUN EYELE LEGO AUCO LEGO KAFEREFUN OYA.", "REZO: OSA BARA OSI BARA AQUE LEDE OBARA MELLI ADIFAFUN ONIBARA AGUN NAIQUIN LEGIN AYE.", "REZO: OSA BARA NI BARA ADIFAFUN OLOFIN ORUNMILA OSHOSI E IYA. OLOFIN USERE ORUNMILA, UMBO WA ILE AKURO ORUNMILA UNLONI LONA UNSE OSHOSI ODE MIAKUARE IYA OSHOSI ELE AKUARE UNYEN OSHOSI EFA TOKU IYA.", "REZO: ADIFAFUN OBADIMEYI OKAN SHONSHON ONA TIYA UMBOWA OWE INLE OMODE JORO JORO ADIFAFUN IRO LONA LORDAFUN OBINI KAFEREFUN OKUNI AGADA LORDAFUN ARUBO ADONI OSGA AGGAYU OROIÑA IYA NI AGGAYU SOKU SOKU ALADE OSHA MABINO LODASHO ALABASHE AGARI.", "REZO: OSA SHEPE OSA CIWERE BI BERUN OYOYI MEFA AGUALODE ONI ERUN OROBI OGGUN FOYURU MAGUN ABONI WAYE TINASIWE OGGUN OBA NAYIRE OMO OLOKUN OSA YANLALIN OSA AWANI BORA OGGUN OMO FUN EGGUN LAÑIRE INLE BOKU BAYAKUN ORON OMO DE AIRE ABEBEKUNLE OGGUN LERI KOFUN EGGUN AWANILIRUN", "OSAEWE ORABUYANO OSA OBARA MAFEREFUN OGGUN, ESHU, SHANGO,ORUNMILA, OLOKUN."]}]$q$::jsonb),
(159,'09b6af32176d019e25f90e68234d2711','87fac6eac5ca70437faba086610b0e29',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Ọ̀kànràn pide ofrendar para evitar la desgracia y tener tranquilidad. La persona es muy sensible e irritable. Quien le haga la guerra sin razón lo lamentará. No debe guardar malicia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Responde con enojo a las críticas o los pleitos.", "Se cree capaz de aguantar cualquier ataque y no escucha la advertencia (relato del antílope y sus cuernos).", "Busca un lugar propio donde vivir tranquilo (relato del caracol Igbín)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Paz y tranquilidad en la casa que construya.", "Que el que lo odia caiga solo.", "Hijos y un parto feliz."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La abundancia lleva a nuevas oportunidades. (Este Odu habla de la necesidad de ser honesto, servcioso y tener coraje para recibir una bendición de larga vida)", "origen_id": "06bac719b3deeae1ed4dd0a0"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Un ataque violento que lo paralice.", "Confiar solo en la propia fuerza.", "Ser odiado sin motivo."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La avaricia lleva al aislamiento. (Este Odu habla de las consecuencias negativas de creer que no puedes ser tocaado por muerte o perturbación).", "origen_id": "bd3dd8ee6b842e4782eac7c1"}]}, {"titulo": "Enseñanza principal", "texto": "El cuerpo que no aguanta el sufrimiento se construye una casa aparte. En la casa del caracol nadie corre y en la de la tortuga nadie llora."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀sá Kànràn habla de sacrificar para evitar la desgracia y asegurar la tranquilidad", "origen_id": "f6f2eb7d2b5648cd706c82ce"}]}, {"titulo": "Relatos reunidos", "puntos": ["El antílope y sus cuernos. Al antílope le pidieron una aljaba con flechas, un arco, 2,200 cauríes y un gallo antes de que le llegara un ataque violento. No moriría a manos de sus enemigos, pero el ataque podía frenarlo. No ofreció: dijo que sus cuernos bastaban. El adivino le dijo que los enemigos le mandarían los problemas desde lejos, y él insistió en sus cuernos.", "El caracol y su casa. Al caracol le pidieron una tortuga y 1,800 cauríes. Ofreció y le aseguraron paz y tranquilidad en la casa que iba a construir.", "El lodo resbaloso. Tẹ̀ẹ̀rẹ̀, el lodo resbaloso, no le guardaba rencor a nadie, y aun así todos lo despreciaban. Ofreció. Desde entonces, cuando la gente pasa por el lodo se sube la ropa y camina con cuidado, pero Tẹ̀ẹ̀rẹ̀ la hace resbalar y cae de golpe.", "Òrìṣà Oko y el ñame nuevo. Òrìṣà Oko preguntó si su esposa embarazada daría a luz bien. Le dijeron que sí, y que el parto sería cerca de la fiesta. Ofreció. El día que iban a comer el ñame nuevo del año, su esposa dio a luz. 'Hoy que comemos el ñame nuevo, mi esposa parió un niño.'"], "pasajes": [{"titulo": "Verso 159.1", "texto": "Osákànràn: adivinó Ifá para el Antilope,\nLe fue aconsejado hacer sacrificio\nantes que un problema violento\ncon peligro para su vida le sucediera\n(insulto para su vida, agravio, asalto repentino).\nÉl no moriria en manos de sus enemigos,\nsin embargo,\nese incidente podria paralizarie su avance\ny tendría que salvarse a sí mismo.\nLe aconsejaron sacrificar:\nun aljaba (bolso de madera porta flechas)\ny flechas, un arco (arma para tirar flechas),\n2.200 cowries y un gallo.\nbrăn iwósí: gran problema de insulto para la vida, ser atacado,\nultrajado, sufrir violencia.\nEl oyó y no sacrificó.\nÉl dijo: \"mis cuernos son suficiente para garantizar\nmi inmunidad ante los insultos (ataques).\nEl adivino dijo: \"Los enemigos te enviaran los problemas\ndesde lugares lejanos\"\nEl dijo que: \"dependería de sus cuernos\".", "origen_id": "99f7f24d7d161d64b600da2c"}, {"titulo": "Verso 159.2", "texto": "\"El cuerpo que no tolera el sufrimiento,\nconstruye una vivienda separada para él\":\nadivinó Ifá para igbin (caracol babosa).\nle fue aconsejado sacrificar:\ntortuga (jicotea) y 1.800 cowries.\nIgbin sacrificó.\nEl adivino asegura:\n\"El disfrutará de paz y tranquilidad en la casa que va a construir\".\nEsto quiere decir que nadie anda rápido en la casa del caracol\ny nadie se lamenta (llora) en casa de la tortuga.", "origen_id": "70fde1fd070969da14e0634e"}, {"titulo": "Versos complementarios 1 · A", "texto": "Ifá pé' eni ti bá n gbé' òtá ko eléyìun ó kàn kú jun ni;' ebo\n                                                             ' ni kó rú, kò sì gbodò\n                                                                                ' ' kórira. Ifá\n  pé' eni ó bá kórira eléyìun ó kàn subú dànù ni.\n\n Igi´ nlá lo ya dínà\n La e bùgbé   '\n A díá fún 'tèèrètè' ' '\n Tí ò lódì' enìkan´ nnu\n Gbogbo aráyé ló ní tie                ' nínú pítipìti\n Tèèrè                              ´\n ' ' ' ò lódì' eníkan     ´ n bínúu rè\n                                       nnú\n Gogbo wón  '         bá                    '\n Wón\n   '     ní kó      rúbo'\n À á' séé mo  ' Tèèrè?'' '\n N làá pe' Eré   '\n Tèèrè\n '' ' ´   bá    rúbo'\n Wón\n   '     ní ngbà tó o bá yò              ' wón '\n Ó ó rií n tójúu wón         '        ó   kàn\n Bí' ón bá ti´ n' lo lójú' Erè           '\n Wón\n   '     ó bàá      ká      aso\n                           '' ´     sóké\n Wón     ó mo                                    ´\n   '        ' 'telè   ' gínngín ginngin\n Tèèrè\n ' ' ' ó bàá yò       ' wón    '\n Won\n   '     a subú lulè      '\n Ní wá´ n jó ní´ n yò\n Ní´ n yin àwon   '         Babaláwo\n Àwon      Babaláwo            ´ n yin Ifá\n     '\n Ó ní béè\n        ' ' làwon   '          Babaláwo tòún wí\n Igi´ nlá ló ya dínà\n La e bùgbé   '\n A díá fún Tèèrè '' '\n Ti ò lódi' enìkan´ nnú\n Gbogbo áráyé ló ní tie                ' ´nínú pitipiti\n Kín ní´ n pa won     '          tí wón\n                                     '        n kú 'beere?\n                                                      ' '\n Tèèrè\n '' '\n N ní´ n pa wón  '          làwon '\n                                        ´ n kú beere\n                                                   '' '\n Tèèrè\n '' '\n\n' Òsá' Òkànràn A\n  Ifá dice a cualquiera que se atreve (desafía) guerra contra esta persona simplemente se\n  moriría prematuramente. Él debe realizar sacrificio pero debe mandar para no ser\n  malsano. Pero quien lo odia lo sentiría\n\n Este es porque un árbol grande se cayó por la senda\n Que nos hizo desviar a través del arbusto\n Adivinación lanzada para Tèèrè\n Que tenía ninguna malicia\n Todavía todos lo despreciamos\n Tèèrè guarda no malicia de uno\n Todos empezamos belicoso sin embargo contra él\n Le pidieron que realizara sacrificio\n Cómo hacemos para conocer a Tèèrè\n\n Es el nombre alternativo para el ' Barro Resbaladizo’\n Tèèrè realizó el sacrificio\n ‘Cuando usted los resbala fuera '\n ‘Usted vería cuánto ellos sufrirían por odiarlo ', ellos aseguraron a Tèèrè\n Siempre que ellos caminaran en el barro resbaladizo\n Ellos sostendrían su ropa\n Ellos estarían caminando prudentemente\n Tèèrè los resbalaría entonces fuera\n Ellos se caerían con un porrazo\n Él empezó a bailar y regocijarse entonces\n Él estaba alabando su Babaláwos\n Sus Babaláwos estaban alabando Ifá\n Él dijo que era exactamente lo que su Babaláwos había dicho\n Es porque un árbol grande se cayó por la senda\n Eso nos hizo desviar a través del arbusto\n Adivinación lanzada para Tèèrè\n Que tenía ninguna malicia\n Todavía todos lo despreciamos\n ¿Qué estaba matándolos y ellos estaban agonizando en su multitud?\n Tèèrè\n Era lo que estaba matándolos, haciéndoles morirse en multitud,\n Tèèrè", "origen_id": "10b9c0d1e6c99216c1e48512"}, {"titulo": "Versos complementarios 2", "texto": "Ó rìn kánran\n  Ìrin kánran kánran nirin' Ekùn\n  Ó kú okè\n  Okè okun\n  A díá fún Òòsà oko Agbaa Ìràwo           '\n  Tí ó fi inúúdùn' jesu    '     àmódún\n                                    '\n  Wón\n    '     ní kó rúbo '\n  Wón\n    ' níre' omo     ' fún un\n  Aboyún ilé òún bí báyìí?\n  Wón\n    '     ní wéré\n              ' ' ní ó bìí\n  Ojú' ònà ní ó bìímo        ' si\n  Òòsà Okó bá rúbo         '\n´\n  Ngbà ó tó gégé ' ' '     odún\n  Tí wón'    ó móo\n                 ' ' 'je 'isu àmodún'\n  Wón\n    '     bá  ní  kí won\n                       '       ó móo\n                                  ' ' 'lòó\n                                        ' ru 'Isu Òòsà Oko wa\n             ´\n 'Isu ni' ón n rùú bò    '\n  Ìyàwò bá dójú' ònà\n  Ló bá bímo   '\n  Hàín!\n  Wón\n    '     dé ilé lÒòsà okó bá´ n yò      '\n  ‘Lónìí tóun ó' je Isu náà ni Obìin òún tún bí' omo      ' báyìí’?\n  Ifá loun pé ire' omo       ' fún eléyiun\n  N ní wá´ n jo n ní´ n 'yò\n      ´\n\n  Ní n yin àwon'     babalawo\n  Àwon     Babaláwo    ´ n yin Ifá\n     '\n  Ó ní bee' làwon'    Babaláwo òun wí\n  Ó sá kánran\n  O rìn kánran\n  Irìn kánran kànran nìrìn' Ekùn\n  Ó kú okè\n  Okè okun\n  A díá fún Òòsà oko Agbaa Ìràwò        '\n  Tí ó fi inúúdùn' jesu' àmódún\n                              '\n' Ebo\n    ' n wón'     ni kó rú\n  Ebo\n' '     n  wón\n           '     ni kó' se\n  Òòsà oko Àgbà Ìràwò      ' gbébo\n                                 ' ' nbè'\n  Ó rúbo'\n' E mòmò\n       ' ' kú oké\n  Okè okun\n  Òòsà oko Àgbà Ìràwò      ' ló wáá finú dídùn 'jesu\n                                                  ' àmódún\n                                                     '\n  Layé bá ye '   gbogbo    wa   tán pátá  porongodo", "origen_id": "f6d603263d9c84c567e48694"}, {"titulo": "Versos complementarios 3 · B", "texto": "Ifá dice que esta persona estaría contenta en la vida.\n\n Él corre al azar\n Él camina al azar\n El leopardo pasea siempre es de una manera casual\n Ó kú okè\n Okè okun\n Adivinación del lanzamiento para Òòsà Oko, la estrella más grande,\n Eso comería el nuevo ñame con felicidad\n Le pidieron que realizara sacrificio\n Ellos le desearon la fortuna de niños\n ¿' Habría a la mujer embarazada en mi casa entregar seguramente '?\n Ellos lo tranquilizaron que ella entregaría seguramente\n Ellos le dijeron que ella estaría en una jornada aproximadamente el tiempo de su entrega\n Òòsà-Oko ofrecieron el sacrificio entonces\n Cuando estaba sobre la fiesta anual\n Ellos estaban preparando comer el nuevo ñame\n Las mujeres fueron pedidas ir y traer Òòsà se puso muy jubiloso\n ¿' Hoy que nosotros comeríamos nuestro Nuevo ñame del Año, mi esposa entregó de un\n bebé '?\n Ifá dice que él le desea la fortuna buena de niños a esta persona\n Él empezó a bailar y regocijarse entonces\n Él estaba alabando su Babaláwos\n Sus Babaláwos estaban alabando Ifá\n Él dijo que era exactamente como su Babaláwos que dijo que él corre al azar\n Él camina al azar\n El leopardo caminar siempre es de una manera casual\n Ó kú okè\n Okè okun\n Adivinación lanzada para Òòsà Oko, la estrella más grande,\n\nQue comería el nuevo ñame con felicidad\nLe pidieron que ofreciera sacrificio\nEl sacrificio era el antídoto prescrito\nÒòsà Oko que la estrella más grande oyó hablar del sacrificio\nY lo realizó\nE mòmò kú okè\nOkè okun\nEs Òòsà Oko la estrella más grande con la que tenía felicidad comió el Nuevo ñame del\nAño\nY la vida nos agradó en integridad.", "origen_id": "f489b65de20b4b02d7502272"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Osakanran habla de sacrificar para evitar la desgracia y asegurar\n                                                                 la tranquilidad.\n                                      WO - El cliente está demasiado delgado.\n\n\n159.1 · Osakanran adivinó Ifá para el antílope, a quien le fue pedido\n             hacer un sacrificio antes de que ocurra incidentes ofensivos por lo\n                que él no moriría como resultado de ellos, pero debía salvarse.\n           Ebo: un bulto de carcaj, flechas y arcos, 2.200 cowries y 1 gallo. Él\n               oyó y no sacrificó. Él dijo que sus cuernos eran suficientes para\n                                  garantizarle su inmunidad sobre los insultos.\n           Ellos dijeron que los enemigos le enviarían los problemas a él desde\n                        lugares lejanos. Él dijo que dependería de sus cuernos.\n\n\n159.2 · Aquel que no tolere los insultos debe construir su casa en un\n      área separada. Fue profetizado Ifá para Igbin (la babosa de caracol), a\n                                                       quien se pidió sacrificar.\n                Ebo: 1 tortuga (jicotea), 1.800 cowries. Igbin sacrificó y le fue\n            asegurado que él disfrutaria de paz y tranquilidad en la casa que él\n           iba a construir. Se dice que las personas nunca deben ir rápido en la\n               casa del caracol y nadie debe llorar en casa de ahun (la tortuga).", "origen_id": "f94ef0bd60d33d0029c78caa"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El antílope: una aljaba con flechas, un arco, 2,200 cauríes y un gallo.", "El caracol: una tortuga y 1,800 cauríes.", "Ofrenda a Òrìṣà Oko por el parto."], "pasajes": [{"titulo": "Ofrenda en el verso 159.1", "texto": "Osákànràn: adivinó Ifá para el Antilope,\nLe fue aconsejado hacer sacrificio\nantes que un problema violento\ncon peligro para su vida le sucediera\n(insulto para su vida, agravio, asalto repentino).\nÉl no moriria en manos de sus enemigos,\nsin embargo,\nese incidente podria paralizarie su avance\ny tendría que salvarse a sí mismo.\nLe aconsejaron sacrificar:\nun aljaba (bolso de madera porta flechas)\ny flechas, un arco (arma para tirar flechas),\n2.200 cowries y un gallo.\nbrăn iwósí: gran problema de insulto para la vida, ser atacado,\nultrajado, sufrir violencia.\nEl oyó y no sacrificó.\nÉl dijo: \"mis cuernos son suficiente para garantizar\nmi inmunidad ante los insultos (ataques).\nEl adivino dijo: \"Los enemigos te enviaran los problemas\ndesde lugares lejanos\"\nEl dijo que: \"dependería de sus cuernos\".", "origen_id": "a14ea389ead593975fa76d21"}, {"titulo": "Ofrenda en el verso 159.2", "texto": "\"El cuerpo que no tolera el sufrimiento,\nconstruye una vivienda separada para él\":\nadivinó Ifá para igbin (caracol babosa).\nle fue aconsejado sacrificar:\ntortuga (jicotea) y 1.800 cowries.\nIgbin sacrificó.\nEl adivino asegura:\n\"El disfrutará de paz y tranquilidad en la casa que va a construir\".\nEsto quiere decir que nadie anda rápido en la casa del caracol\ny nadie se lamenta (llora) en casa de la tortuga.", "origen_id": "dcc32b952ef634b2112f7681"}]}, {"titulo": "Relaciones espirituales", "texto": "Òrìṣà Oko, la estrella más grande, recibe el ñame nuevo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tortuga, arco y flechas, gallo, ñame nuevo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 159.1 (yorùbá): Osákànràn: a difá fún Agbonrin. / Wọ̀n niki o rúbọ / ki òràn iwọ̀si too de. / Ki o ma baakúsi owọ̀ òtá / kiobaa legba ara rè silẹ. / Wọ̀n niki ó ru: / Iti-apo ati ofa, iti orun, / ogbọ̀kànlá owó / ati akuko-adiyẹ. / Ó gbọ̀ ko rú. / O ni: \"owo oun too kợ'ya\". / Wọ̀n ni: \"Lati okere ni òtá timaama-ranṣẹ wa / tiyoo maa kan an l'ara\" / Ó ni: \"Owo oun ti to\".", "Verso 159.2 (yorùbá): \"Ara mi ko gba iya, / a ko ilé rè lọtọ\": / a difá fún Igbín, / wọ̀n niki İgbin wa rúbọ, / llé ti İgbín maa kọ, a tuu lara. / Ẹbọ: Ọbahun ati egbaásàn owó. / igbin rúbọ. / Wọ̀n ni: / \"A ko niigbaawẹ nile igbin laelae\" / A kiigbọ ekún ni ilé Ahun (Awun/ljapá).", "REZO: OSA KANA OBARA ORI EGUN ADIFAFUN DAD BAÑANI, OWO, EYELE, OUNKO LEBO. MAFEREFUN SHANGO ATI YEMAYA.", "REZO: OSA KANA IFA LODAFUN OLOKUN, MAFEREFUN ORUNMILA, SHANGO, YEMAYA, OBATALA, ELED ATI ALA.", "REZO: REZO ARARA: SAKA NUMA DIAVA . SA SIYE SIYE AKI SIYE SIYE. NOMU SOAYO YI KPE ZADOYU.", "REZO: OSARA AWO OMO IKU ENI LORUN INLE OLOLUKOYE INTORI IRE SHANGO AFUSE ABEBE ORUN OSA KANA TI OYA ISITILE OSA KANA AFOYU TIESIN OSA KANA OFOYU AKUA IKU AFEFE.", "REZO: OSA KANA KANA AWO ABERI EWE BARAYIBAWO MARIBOYA MARIBI IKU OMO OBA ABI ISHE KANA BI ASHE AWALAYE IYERE INLE AYERIN NILEKUN IBA AGO OBA ISHE OMONI LADE OYA OMO YEKU LODE AWO ABERI EWE IRE ASHEGUN OTA OYA ISHE GBOGBO OSHA KO OBA ISHE ODARA OYA ASHEGUN ETA IFA KAFEREFUN ODUDUWA IFA KAFEREFUN OYA IFA KAFEREFUN OGO.", "REZO: ADIFAFUN BOMIBATA EWE OZAIN AKARABA KAMBELE OYA NILE ADELEYE ORUN WARABI INAYO OKO BOMIBATA ORISHA FIGBO EGBERE MOLE IGBO BIRI OKURU BIRI EWE AYE KOBALE EWE ARUN NI MUYE EWE ALUKUAYIDA EWE EWIN IJA EWE AZUN FURUN EWE AKUAKUE ASHEGUN OTA LODAFUN OMO OZAIN MESAN KAMBELA RI OMO YEKU KAFEREFUN IYANZA OSA KANA SHEWELE AWO INLE.", "SUYERE: OYA FUFU LELE ADE OYA FUFU LELE OYA ONIRAN NIBE LOKO ONISHE ORUN", "REZO: OSA KANA KENESIDE IYA EWE ELENKU EGGUN ODARA EKULE ILE ONIREO ABO ILE LAIWO SHONSHON ILE OLOFIN INLE MEREBILE KUDUN BIGBE NILU ILE NIKUWA ERAN AKAMEN, AMOMEKUIN ERAN OLUWE ILE OBA AUNLO LEBO SILLE TELLES NILE WA LEBUSI ADIFAFUN OSA KANA KENILE KOLO ONO OBA ONIRE ORUN LALA KUE KUE AYE ORUNMILA ILE AWA IMA OBA YOLEILEDI AWO OBO ASARE PAWO KAFEREFUN ELEGBA LODAFUN IYA MONKUO ORISHA OBORILEDA LODAFUN OBATALA ORUYULE ORISHA."]}]$q$::jsonb),
(160,'12b33d4744c7174910417cb827592c97','c3254740a1ddcb1d7ef04f17a03ab2d7',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Ògúndá dice que la buena fortuna no se logra ni se mantiene sola: hay que ofrendar para conseguirla y también para conservarla en paz. Hay alguien en quien la persona no debe confiar. Todo lo bueno que se le había ido regresará. Unos se confabulan para dañarlo y no lo lograrán."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Disfruta un logro y descuida un peligro que no ha resuelto.", "Recibió varios consejos y está siguiendo solo los que le gustan (relato de Olibara y los tres adivinos).", "Un cambio de humor puede llevarlo a un pleito evitable.", "Una fortuna perdida puede regresar."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Dinero e hijos.", "Que regrese lo que se fue: dinero, pareja, hijos.", "Ser honrado y vivir mucho.", "Que el daño que le hacen no lo mate y llegue a rey.", "Una pareja que llega de forma inesperada."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La abundancia lleva a despejar obstaculos. (Este Odu habla de la necesidad de prepararse para un conflicto extremo para proteger la buena fortuna que ya se manifesto).", "origen_id": "f2131432835fa14df7bf4744"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Atender solo una parte de lo que Ifá marca.", "Una guerra por no ofrendar.", "Confiar en quien no debe.", "Contar secretos a la pareja."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La inestabilidad mental lleva al conflicto. (Este Odu habla de la posibilidad que el enojo y la depresion lleve a la violencia.)", "origen_id": "9590a6de02f459005479baf5"}]}, {"titulo": "Enseñanza principal", "texto": "Olibara hizo dos ofrendas y dejó la tercera, y la guerra llegó a los once días. El agua que se escurre del pez vuelve a encontrarlo en el río: así regresan las cosas buenas."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀sá'Gúndá habla de que la buena fortuna no se logra, ni mantiene por si misma sin realizar sacrificios. Además de sacrificar para obtener buena fortuna, hay que hacerlo para mantener los logros alcanzado, con paz y tranquilidad.", "origen_id": "b28fd9b9fb51f296f790f551"}]}, {"titulo": "Relatos reunidos", "puntos": ["Olibara y los tres adivinos. Tres adivinos consultaron para Olibara. El primero le anunció dinero y le pidió una paloma, una carnera y 44,000 cauríes; ofreció. El segundo le anunció hijos y le pidió una chiva, una gallina y 32,000 cauríes; ofreció. El adivino de su propia casa le anunció una guerra y le pidió un carnero y 66,000 cauríes, advirtiendo que si no ofrecía la guerra llegaría en once días. No ofreció. A los once días llegó la guerra y Olibara tuvo que huir del pueblo.", "La hierba Aikújegúnrè y el campesino. A la hierba Aikújegúnrè le dijeron que no moriría y que se sentaría en un lugar alto, y ofreció un caracol, una gallina y un carnero. Al campesino le pidieron un carnero, un machete y 66,000 cauríes para no desaparecer. Cuando el campesino desyerba, junta la hierba con su machete y la pone sobre un tocón. La hierba dice: 'Díganle a mi padre en el cielo que me honran: me sientan en un trono'. Por eso dice que ni el campesino ni ella deben morir, para seguir juntos siempre.", "Ọ̀rúnmìlà y Bòmbò. Ọ̀rúnmìlà iba a tomar por esposa a Bòmbò, hija del Òrìṣà. Ofreció, y todas las cosas buenas que se habían ido de su casa empezaron a regresar. 'El agua que se escurre del pez vuelve a encontrarlo en el río.'", "Alágbàniràwé. Alágbàniràwé preguntó si la vida le sería grata. Le dijeron que algunos le estaban haciendo daño y que nunca lograrían nada: le hicieron mal a Olúmẹpín y no murió; a Olúmẹ̀ta y no murió; al ñame de agua le cortaron la cabeza y lo enterraron en el surco, y volvió a brotar. Ofreció, y le dijeron que el daño no lo mataría; más bien llegaría a rey.", "El cazador y la mujer búfalo. A un cazador le pidieron dos gallos, dos gallinas, cerveza de maíz y ñame de semilla machacado para su Orí, porque ese año encontraría esposa. Un día, desde su plataforma en el árbol, vio a un animal grande como búfalo que se quitó la piel y se convirtió en una hermosa mujer rojiza; escondió la piel detrás de un árbol y se fue al mercado. El cazador tomó la piel, la siguió y en el mercado le pidió matrimonio; ella dijo que no, hasta que él le enseñó la piel. Entonces aceptó, con la condición de que nunca se lo contara a nadie. Le dio hijos. La primera esposa, celosa, buscó al hermano mayor del cazador, que lo emborrachó con vino de palma hasta que le contó todo, y se lo dijo a ella. Un día que el cazador estaba en el campo, la primera esposa golpeó leña contra el suelo, cosa prohibida en casa de un cazador, y cuando la otra le reclamó, le dijo con desprecio: 'Eres gente y animal; tu piel está en el granero'. La mujer buscó su piel, la remojó, se la puso, le salieron cuernos y mató a la primera esposa. Se quitó uno de sus cuernos, lo dejó en casa y corrió al campo. El cazador la vio venir, supo lo que había pasado y rezó con lo que había ofrecido. Ella le preguntó cómo lo supo la otra, y él le contó lo del vino. Lo perdonó, pero le pidió que cada año, cuando sus hijos hicieran su fiesta, ofrecieran a su Orí ante el cuerno que dejó. Por eso a los que ofrecen ante cuernos se les llama 'hijos del búfalo'."], "pasajes": [{"titulo": "Verso 160.1", "texto": "\"Ọ̀sá'Gúndá puede luchar\"\n\"Oiderẹ, el adivino de la casa de Igbado\",\n\"Àlùkò, el adivino de la casa de lgbado\",\n\"Aija-gogorogo,\nel adivino de la casa de Olibara\":\nfueron los que adivinaron Ifá para Olibara.\nOiderẹ, el adivino de Igbado\n(Oiderẹ es un adivino de fuera de Olibara\nque fue llamado, invitado a adivinar)\npredijo buena fortuna de dinero para Olibara,\npor eso Olibara, debía sacrificar:\npaloma, carnera y 44.000 cowries.\nEl sacrificó.\nAlukò, el adivino de Igbado\n(Alùkò es también un adivino de otro lugar\nque fue invitado adivinar en casa de Olibara),\npredijo una buena fortuna de hijos,\npor eso Olibara debía sacrificar:\nchiva, gallina y 32.000 cowries.\nOlibara escuchó y sacrificó.\nAija-gogorogo, el adivino de la casa de Olibara,\npredijo una guerra que venía,\nél también le pidió a Olibara un sacrificio:\ncarnero, 66.000 cowries.\nEl le repitió a Olibara que si no sacrificaba\nallí habría una guerra dentro de once días.\nOlibara no ofreció el sacrificio.\nPasados los once días, la guerra vino,\nOlibara tuvo que huir de la guerra y del pueblo.", "origen_id": "5c2d3ea305c21217677d48a7"}, {"titulo": "Verso 160.2", "texto": "Sun-mis'ebe\nSun-mis'aporo\nadivinó Ifá para Aikújegúnrè\ny para Oloko (el agricultor).\nÉl le aconsejó a Aikújegúnrè sacrificar:\ncaracol babosa, gallina, carnero.\nEl adivino aseguró:\n\"Aikújegúnrè no morirá, será ascendido,\nso sentará en un puesto alto\nsobre la tierra (aga)\"\nÉl escuchó y sacrificó.\nEl adivino aconsejo\ntambién al agricultor ofrecer sacrificio:\ncarnero, machete y 66.000 cowries,\nde modo que él no muriera\n(no dejara de existir),\nél oyó y sacrificó.\nCuando el campesino esta sachando\nkukute: tocón, parte del tronco de un árbol que queda unida a su raíz en el suelo\ncuando lo cortan por su base. ori kukute es la cima del tocón.\n257 Sun-mis'ebe: Mover y empujar para hacer un montón de tierra.\n25° Sun-mis'aporo: Mover y empujar para hacer un surco en la tierra.\n(guataqueando la tierra con el azadón\npara quitar las malas hierbas),\nél reúne a Aikújegúnrè\ncon su machete en un lugar.\nAikújegúnrè dice:\n\"me están confiriendo dignidad\npor reunirme en un lugar,\nasí que ayúdame a decirle\na mi padre en el cielo\"\nCuando el campesino termina\nde deshierbar la tierra\ncoge con su machete a Aikújegúnrè\ny la coloca sobre un tocón (kukute)\nAikújegúnrè dice:\n\"cuéntale a mi padre en el cielo\nque me están honrando (dignificando)\nme están sentando sobre una aga\"\npor eso, las últimas palabras usualmente\ndichas por Aikújegúnrè (tipo de hierba) son:\n\"el campesino no debe morir (desaparecer),\nyo no debo morir tampoco,\nasí permaneceremos juntos por siempre\".", "origen_id": "de8f850b24875f0dcd1aeee4"}, {"titulo": "Versos complementarios 1 · A", "texto": "Ifá pé gbogbo ire eléyiun tó ti dànù pátá ní ´´n padàá bò.\n                                                        ' Kó rú eja\n                                                                          ´´\n                                                                ' abori nlá ka àti eyelé;\n                                                                                     '\nkí wón\n     ' ó fi eja\n             ' náà lé orí Ifá kí wón\n                                  ' ó la enu\n                                          ' è' kí wón ' ó sì gbón\n                                                               ' ìyè' Ifá òhún\n                                                                          '    sí i. Kí wón\n                                                                                         '\nó wáá fi eja\n         '    òhún\n              '    bo\n                    ' Ifá. Gbogbo  ire òhún\n                                       '    ní   ó padà wá.\n\nÀkò' ò Lerán '       lèsè\n                       ' ' tée dé gbonrangandan\n                                       '          ojúgun\nA díá fún Òrúnmìlà\n                 '\nNíjó' ti ´´n lo' rèé fi Bombo'    ' omo\n                                    ' ' Òrìsà\n                                           ' sayà\nÒrúnmìlà\n'               ló fé' Bombo\n                          '    ' Omo\n                                  ' ' Òòsà\nGbogbo ire tó ti sí lo' ´´nlé è'\nGbogbo è' bá ´´n padàá dé\nAyé ye' Òrúnmìlà\n            '\nNí wá ´´  n jó ní ´´n yò\nNí ´´n yin àwon    ' Babaláwo\nÀwon      Babaláwo       ´´\n                          n yin Ifá\n      '\nÓ ní béè ' ' làwon  ' Babaláwo tòún wí\nÀkò ni ò lèran  '      lésè\n                        ' ' tée dé gbonrangandan\n                                         '         ojúgun\nA díá fún Òrúnmìlà\n                 '\nNíjó' ti ´´n lo' rèé fi Bòmbò'    ' omo\n                                    ' ' Òrìsà\n                                           ' sayà\nWón' ní ó sá káalè' ebo     ' ' ní ó se\n                                      '\nÒrúnmìlà\n'               gbébo\n                    ' '  nbè   ó rúbo\nAjé tó ti sí  ' lo'\n      ´´\nAjé n padàá bò' wá\nOmi tó sun lo' lára eja     '\nKò sàì sàn wáá béja      ' lodo\nAya tó ti sí lo'\nOmo\n' ' tó ti sí    ' lo'\nGbogbo ire tó ti sí lo\nWón     ´´\n   ' n padàá bò' wá\nOmi tó sun lo' lára eja     '\nKò sàì sàn wáá bèja      ' lódo\nÒsá\n ' Ògúndá A\nTodo las fortunas buenas que habían eludido a esta persona regresarían. Ifá le pide que\nsacrifique un pez que se arrastra en el suelo (lodo, fango, pescado oscuro o pardo.\n[mudfish]) Grande y palomas. Ifá le pide que ponga el pez en el sacrificio, ellos deben\nabrir la boca del pez y verter polvo de Ifá en él y entonces lo usan para sacrificar a Ifá.\nTodas las cosas buenas regresarían.\n\nEs pájaro de Àkò que no tiene la carne a la espinilla\nAdivinación lanzada para Òrúnmìlà\nEn el día él iba a tomar Bòmbò el niño de Òrìsà como esposa\nEs Òrúnmìlà que se caso Bòmbò\nTodas las cosas buenas que habían partido de su casa previamente\nTodos ellos empezaron regresando\nLa vida de Òrúnmìlà tan contento\nÉl empezó entonces también a bailar y regocije\nÉl estaba alabando su Babaláwo\nSu Babaláwo estaba alabando Ifá\nÉl dijo que era exactamente como su Babaláwo había dicho\n\nEs pájaro de Àkò que no tiene la carne a ¡la espinilla desnuda\nAdivinación lanzada para Òrúnmìlà en el día que él iba a tomar Bòmbò el niño de Òrìsà\ncomo esposa\nLe pidieron cuidar de la tierra y realizar el sacrificio\nÒrúnmìlà oyó hablar del sacrificio y lo realizó\nLa riqueza que había partido\nLa riqueza está regresando\nEl agua que escurrió (vació, agoto, apurar) lejos de un pez\nFluiría atrás para encontrarse el pez en el río\nLa esposa que había partido\nEl niño que había partido\nTodas las cosas buenas que habían partido\nTodo ellos están viniendo de regreso\nEl agua que escurrió fuera de un pez\nFluiría atrás para encontrarse el pez en el río", "origen_id": "74b327ad225232e77d6d660f"}, {"titulo": "Versos complementarios 2 · B", "texto": "Wón\n  ' ó móo\n       ' ' pé àwón\n                ' ó dàá eléyìun lóró. Ifá pé ìró' ni, won\n                                                       ' ò níí le mú u.\nOró ti wón  ' dÓlúmepín       '\nOró ò leè pOlúmepín       '       mó'\nOró tée''   dÓlúmetà   '\nOró ò leè pOlúmetà        '\nOró ti wón  ' dá Ògbògbò\n                      ' ' ' ewùrà\nWón' korí è' bolè ' ' ní poro oko\nOró òhún\n     '        ò  níí   pÒgbògbò\n                          ' ' ' ewùrà\nÒgbògbò\n ' ' ' ewùrà tée            ' ' korí è' bolè\n                                         ' ' ní poro oko\n A díá fún Alágbàniràwé\nOmo\n ' ' akéré wogbó   '           iwin lo'\nAlágbàniràwé ní ´´n bèèrè lówó         ' ' Ifá\nAyé ye' òun báyìí?\nWón' ní ayé ó´´ye' é'\nWón' ní wón   ' n dá a loro ni\nWón' ní gbogbo ení       ' ó dá a lóró\nWón    ní   gbogboo        won                   `p´\n   '                            ' ò níí rójútùú nnkaan won\n                                                         '\nÓ ní wón  '   dá  Olúmepín    '    lóró\nOlúmepín\n       ' ´´´ ò kú\nAyé ní n je'\nWón      p´\n   ' dá Olúmetà      ' lóró\nOlúmetà' ò kú\nWón'   dá   ògbògbò\n             ' ' ' ewùrà lórí\nWón'   korí   è' bòlè\n                  ' ' ní poro oko\nÒgbògbò\n ' ' ' ewùrà tún hù\nÒgbògbò\n ' ' ' ewùrà ò kú\nIfá pé kí ekéyìun ó rúbo' dáadáa\nWón' níwo' Alágbàniràwé ò níí kú\nGbogbo níwo Alágbàniráwè ó níí kú\nGbogbo oró ti ón      ' dá o' ní ó lo'\nÓ ní Oró ti wón   ' dÒlúmepín      '\nOró ó leè pOlúmepín       '       mó'\n\nOró tée\n      ' ' dÓlúmetà '\nOré ò leè pOlúmetà   '\nOró ti wón' dá Ògbògbò\n                  ' ' ' ewùrà\nWón\n  ' korí è' bolè' ' ní poro oko\nOró òhún\n    '       ò níí pÒgbògbò\n                     ' ' ' ewùrà\nÒgbògbò\n' ' '       ewùrà    tée\n                       ' ' korí è' bolè\n                                    ' ' ní poro oko\nA díá fún Alágbàniràwé Omo       ' ' akéré wogbó\n                                               '    iwin lo'\nOró tée\n      ''  dá Alágbàniráwè\nKó níí pa Alágbàniráwè\nOba\n'   ní ó fi je'\n\nÒsá\n ' Ògúndá B\nIfá dice que algunas personas se confabularían para causar daño a esta persona. Ellos no\ntendrían éxito.\n\nEl daño (mal, perjudicar) ellos causaron a Olúmepín\nEl daño no podría matar a Olúmepín\nEl estrago usted causó a Olúmetà\nNunca podría matar Olúmetà\nEl daño ellos causaron a la semilla de ñame de agua fresca\nEllos entierran su cabeza en los surcos de la granja\nEl daño no mataría la semilla de ñame de agua fresca\nCuya cabeza ellos entierran en los surcos de la granja\nAdivinación lanzada para Alágbàniràwé\nEl niño de akéré wogbó iwin lo\nEs Alágbàniràwé que estaba preguntándole a Ifá eso\n'¿La vida me agradaría en absoluto?'\nEllos dijeron que la vida lo agradaría\nEllos dijeron que algunas personas están causándole daño\nTodos que se confabularon para causarle los dolores\nEllos nunca encontrarían el avance para sus cosas, ellos dijeron\nEllos causaron a Olúmepín un gran daño\nTodavía Olúmepín no se murió, ellos dijeron\nÉl estaba disfrutando la vida\nEllos dijeron 'Ellos causaron a Olúmetà un gran estrago'\nOlúmetà no se murió\nEllos cortaron el retoño del ñame de agua\nY entierra la cabeza en los surcos de la granja\nEl ñame de agua creció y germinó\nNo se murió\nIfá le pide a esta persona que realice sacrificio bien\nUsted, Alágbàniràwé, usted no se moriría\nTodos los horrores que ellos causaron que usted iría\nÉl dijo el daño que ellos causaron a Olúmepín\nEl daño no podría matar a Olúmepín\nEl estrago usted causó a Olúmetà\nNunca matará a Olúmetà\nEl daño que ellos causaron a la semilla de ñame de agua fresca\nEllos entierran su cabeza en los surcos de la granja\nEl daño no mataría la semilla de ñame de agua fresca\n\nCuya cabeza usted entierra en surcos de la granja\nAdivinación lanzada para Alágbàniràwé el niño de Akéré wogbó iwin lo\nEl daño que usted causó Alágbàniràwé\nNunca mataría a Alágbàniràwé\nÉl se volvería un rey más bien.", "origen_id": "0820458106c5f7501675b05d"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Osa´Gunda habla de que la buena fortuna no se mantendría sin\n                                                               sacrificios.\n                  WO - Hay alguien en el cual el cliente no debe confiar.\n\n\n160.1 · Osa´Gunda puede luchar. Oidere, el awo de Igbado, Aluko el\n     awo de Igbado, Aijagogorogo, el awo de Olibara, todos adivinaron\n   Ifá para Olibara. Oidere, el awo de Igbado dijo que él descubrió una\n   buena fortuna para Olibara, por eso Olibara, debía sacrificar. Ebo: 1\n     paloma, 1 carnero y 44.000 cowries. Él sacrifico. Aluko, el awo de\n   Igbado, dijo que él descubrió la fortuna de dar el nacimiento a niños\n              (ambos Oidere y Aluko son extraños) por eso Olibara debía\n   sacrificar. Ebo: 1 chiva, 1 gallina, 32.000 cowries. Olibara escuchó y\n         sacrificó. Aijagogorogo, el awo de la casa de Olibara, dijo que él\n   previó una guerra, él también le pidió a Olibara un sacrificio. Ebo: 1\n   carnero, 66.000 cowries. Él le dijo y Olibara no sacrificó. Allí habría\n  una guerra en 11 días, Olibara no ofreció un sacrificio, la guerra vino\n                                               y Olibara huyó del pueblo.\n\n\n160.2 · Sun-mis´ebe, Sun-mis´aporo (movimientos a los montones y\n    surcos) adivinó Ifá para Aikojegunre (tipo de mala hierba) y Oloko\n  (agricultor). Aikojegonre fue advertido a sacrificar. Ebo: 1 caracol de\n\nbabosa, 1 gallina, 1 carnero. Ellos dijeron que Aikojegunre no\n             moriría pero sería elevado o puesto sobre un objeto alto sobre la\n          tierra. Oyó y sacrificó. El agricultor le fue pedido ofrecer sacrificio.\n              Ebo: 1 carnero, 1 machete y 66.000 cowries de modo que él no\n      muriera, él oyó y sacrificó. Cuando el campesino estaba utilizando el\n             azadón él recogió a Aikujegunre con su machete hacia un lugar.\n     Aikujegunre dijo, “yo estoy notable por estar siendo reunido , así que\n              ayúdame a decirle a mi padre en el cielo”. Cuando el agricultor\n                   terminó de usar su azadón y de desherbar la hierba llamada\n           Aikujegunre coon su machete y colocado sobre un tocón, la hierba\n          mala dijo: “dile a mi padre en el cielo que yo estoy siendo notable”.\n            Por eso, las últimas palabras usualmente dichas por la hierbamala\n             son: “el campesino no debe morir, no debo morir yo tampoco así\n                                         permaneceremos juntos por siempre”.", "origen_id": "e5c009e23454a050483e91d6"}, {"titulo": "Relato en inglés 1", "texto": "“To fight and stir up dust like Buffalo” was the one who cast Ifa for Hunter.\nThey said he should make a sacrifice so that he would find a wife to marry during\nthat year, Hunter sacrificed two cocks, two hens, maize beer, and one shilling.\n\nWe will find some yam cuttings;! we will pound yam loaf with them and sacri-\nfice them to our head. Hunter made the sacrifice.\n\nOne day this hunter went to the farm. When he climbed to his lookout plat-\nform,” he saw 4 Gidigidi,® but when he tried to aim his gun at it, this Gidigidi\nturned into a beautiful reddish maiden. When she had finished taking off her hide,\nthe hunter watched as the Gidigidi hid her hide, and he knew the place where she\nhid it behind a tree. But she herself did not know that this hunter was watching\nher.\n\nWhen the Gidigidi had left, this hunter came down from his lookout and put\nthe hide that she had taken off into his bag; and he followed her until he saw that\nshe was going to market, When they reached the market, this hunter approached\nher; he greeted her, and told her that he had come to market seeking her, This\nGidigidi who had turned into a woman replied, “Is something wrong?” The hunter\nanswered that he wanted to marry her, Gidigidi answered that she was not going\nto marry anyone. The third time that the hunter approached her in this way, she\nasked if he had seen anything behind her.\"\n\nThe hunter replied that he had seen something behind her. The Gidigidi\nwoman answered, “What did you see behind me?” Then the hunter told her that\nshe should come with him, so that he could tell her what he had seen behind her.\nWhen they got outside the market, the hunter put his hand into his bag and brought\nout her hide and showed it to her. When she saw the hide that she had taken off\nin the forest in the hand of the hunter, she said the hunter should take pity on her,\nthat she would marry him. The woman went back to the market and gathered up\nher goods and set out with the hunter. But while they were on the way, she told\nthe hunter that he must not speak a word about this to anyone; and the hunter told\nher that he would not tell anyone. Thus she became his wife, and they lived to-\ngether in his house.\n\nThis woman began to bear children for the hunter, but the wife whom the\nhunter had first married began to tease the hunter by asking him where he had\nmet his second wife, that he had not told her about it. The hunter told her that\nshe was the child of the women who came to the farm to buy meat from him, but\nthis kind of answer did not satisfy his first wife, and she began to inquire whether\nshe had perhaps come from this town or from that town. The hunter told her that\nshe was from a different town, but still this did not satisfy the woman, and she\nbegan to\n\ninquire about. While she was doing this, the Gidigidi woman bore her first child,\nand her second child.\n\nThe first wife went to the hunter’s elder brother and discussed the matter\nwith him, The elder brother took the hunter out and gave him lots of palm wine\nto drink. When the hunter had drunk his fill, his brother asked him, “Where did\nyou meet your second wife?” The hunter replied. that she was a Gidigidi, that. he\nhad seen her taking off her hide where he was watching from a tree in the farm,\nand that he had taken her hide and gone to the market with her, that he had shown\nher the hide, and that from that time on she had been his wife. When the hunter’s\nelder brother came home, he reported this to the hunter's first wife.®\n\nAfter a while, the hunter got ready and went to the farm; but on the second\nday after he had left, his senior wife took wood and struck it against the ground\nin order to break it. (It is a tabu that wood must not be struck against the ground\nin this way in the house of a hunter.) This Gidigidi woman asked whether their\nhusband had not warned them that they must not break wood in this way in his\nhouse? Then the senior wife replied with contempt “Take yourself and go away,\nWayil!l® You are both a human being and an animal. Eat and drink; your hide is\ninside the storehouse.”\n\nWhen the Gidigidi woman heard this, she said, “Ha!” and she kept quiet. She\ngot ready and went to the storehouse, When she got there, she found her hide\nwhere the hunter had hidden it, and she brought it out. When she looked at it, it\nhad dried out. She drew some water and put the hide into it, When it was ready,\nshe got into it, and she had horns on her head. Then she ran at the senior wife,\nbutted her, and killed her, When she had butted and killed the senior wife, she\npulled off one of her two horns, and then started toward the farm. When the\nhunter saw her coming, he knew that wood had been broken in his house. When\nshe wanted to butt her husband, her husband said that she must not butt him. He\nsaid:\n\n“Loaf of yam cuttings and pot of maize beer,”\n“You cut weeds and cover me,\n“You heap honor upon me.”\n\nThen she asked the hunter, how it was that his senior wife had known about\nher. The hunter told her how his elder brother had taken him out and had given\nhim so much palm wine to drink that he no longer knew what he was saying. Then\nshe said, “It is all right.” She said that she would not kill him, but that he should\ngo home and that whenever her children should want to perform their annual fes-\ntival, he should\n\nsacrifice with them to the horn that she had pulled off and left at home as a re-\nmembrance of her when they might want to sacrifice to their heads. From that\ntime on, her children have continued to sacrifice to the horn when they perform\ntheir annual festival. Those who sacrifice to horns in this way are the ones that\nwe call and greet as “Children of Buffalo”® until this very day.\n\nIfa says he sees the blessing of a woman for this person, but that we should\nsacrifice, lest the woman die when her children reach two in number; lest she\ndie and lest her senior wife die with her; lest her husband bring illness home\nfrom the farm; and lest he die and it be said that his wife has taken him away to\nheaven. We should be careful not to reveal secrets to a woman® regarding some-\nthing we want to do, lest, through this our secrets be made public.", "comentario": "1. There are two yam harvests. At the early harvest, the lower part of some\nyams is cut off and the rest is replanted. When these mature, they are called egun\nyams and are used primarily as seed-yams (ebu) for planting in the following year.\nThey are never pounded into yam loaf for eating, but they are commonly used in\nthis form in medicines and for other ritual purposes. Here they are used as a\nsacrifice to the head, which is for the soul which controls the individual’s luck.\n\n2. A platform in a tree reached by a ladder where a hunter watches for game.\nNote the pun here on “mount the lookout” (gun egun) and “pound yam cuttings” (gun\negun).\n\n3. A Gidigidi is a wild animal described the informant as large and power-\nful, and similar to a buffalo; it runs from the rain, which it dislikes, and is some-\ntimes seen with its head under a shelter but its body out in the rain. Other infor-\nmants described it as like a wild goat or like a horse, but stronger. It is identi-\nfied in the CMS Dictionary as “a large and strong animal,” and by Abraham as the\nYellowbacked Duiker (Cephalophus Sylvicultrix Sylvicultrix Afzelius). Later in\nthe verse the children of the Gidigidi woman are spoken of as “children of Buffalo,”\nand Buffalo is mentioned in the introductory phrase. Cf, n. 7.\n\n4. That is, whether he had found out anything about her past.\n5. The Yoruba text says he told the hunter’s second wife, but from the con-\ntext this is clearly an error.\n6. An exclamation expressing great contempt.\n7. Both the maize beer and the loaf of yam cuttings mentioned here, in an\nincantation recited by the hunter to prevent the Gidigidi from killing him, were\nincluded in the sacrifice he had offered.\n8. According to the informants, this is a sib or lineage name (orilẹ) in Ifẹ\nwhose origin is thus explained. However, a variant of this myth recorded at\nMẹkọ, in which a Buffalo (ẹfọn) appears in place of the Gidigidi, identifies the\n“Child of Buffalo” as Qya, the Goddess of the Niger River and the principal wife\nof the God of Thunder. This variant explains why the worshipers or “children”\nof Qya sacrifice to buffalo horns, and why Qya has the praise name Iyansan or\nYansan. Probably this verse also refers to the worshipers of Qya, and Gidigidi\nis a praise name for Buffalo. Cf. n. 1. Cf. also the versions recorded by Idewu\n(1956: 22-25); Danford and Fuja (1960: 7-10); the Walkers (1961: 11-16); and\nFuja (1962: 77-82) in which the animal is identified as a hind or a deer.\n\n9. Cf. verse 18-7. ,", "origen_id": "bcbb050b28271115f7eaa334"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Dinero: una paloma, una carnera y 44,000 cauríes. Hijos: una chiva, una gallina y 32,000 cauríes. Contra la guerra: un carnero y 66,000 cauríes.", "La hierba: un caracol, una gallina y un carnero. El campesino: un carnero, un machete y 66,000 cauríes.", "Para que regrese lo perdido: un pez de lodo grande con la boca llena de iyẹ̀ de Ifá, y palomas.", "El cazador: dos gallos, dos gallinas, cerveza de maíz y ñame de semilla machacado para Orí."], "pasajes": [{"titulo": "Ofrenda en el verso 160.1", "texto": "\"Ọ̀sá'Gúndá puede luchar\"\n\"Oiderẹ, el adivino de la casa de Igbado\",\n\"Àlùkò, el adivino de la casa de lgbado\",\n\"Aija-gogorogo,\nel adivino de la casa de Olibara\":\nfueron los que adivinaron Ifá para Olibara.\nOiderẹ, el adivino de Igbado\n(Oiderẹ es un adivino de fuera de Olibara\nque fue llamado, invitado a adivinar)\npredijo buena fortuna de dinero para Olibara,\npor eso Olibara, debía sacrificar:\npaloma, carnera y 44.000 cowries.\nEl sacrificó.\nAlukò, el adivino de Igbado\n(Alùkò es también un adivino de otro lugar\nque fue invitado adivinar en casa de Olibara),\npredijo una buena fortuna de hijos,\npor eso Olibara debía sacrificar:\nchiva, gallina y 32.000 cowries.\nOlibara escuchó y sacrificó.\nAija-gogorogo, el adivino de la casa de Olibara,\npredijo una guerra que venía,\nél también le pidió a Olibara un sacrificio:\ncarnero, 66.000 cowries.\nEl le repitió a Olibara que si no sacrificaba\nallí habría una guerra dentro de once días.\nOlibara no ofreció el sacrificio.\nPasados los once días, la guerra vino,\nOlibara tuvo que huir de la guerra y del pueblo.", "origen_id": "80f25cae5d239c1db0175437"}, {"titulo": "Ofrenda en el verso 160.2", "texto": "Sun-mis'ebe\nSun-mis'aporo\nadivinó Ifá para Aikújegúnrè\ny para Oloko (el agricultor).\nÉl le aconsejó a Aikújegúnrè sacrificar:\ncaracol babosa, gallina, carnero.\nEl adivino aseguró:\n\"Aikújegúnrè no morirá, será ascendido,\nso sentará en un puesto alto\nsobre la tierra (aga)\"\nÉl escuchó y sacrificó.\nEl adivino aconsejo\ntambién al agricultor ofrecer sacrificio:\ncarnero, machete y 66.000 cowries,\nde modo que él no muriera\n(no dejara de existir),\nél oyó y sacrificó.\nCuando el campesino esta sachando\nkukute: tocón, parte del tronco de un árbol que queda unida a su raíz en el suelo\ncuando lo cortan por su base. ori kukute es la cima del tocón.\n257 Sun-mis'ebe: Mover y empujar para hacer un montón de tierra.\n25° Sun-mis'aporo: Mover y empujar para hacer un surco en la tierra.\n(guataqueando la tierra con el azadón\npara quitar las malas hierbas),\nél reúne a Aikújegúnrè\ncon su machete en un lugar.\nAikújegúnrè dice:\n\"me están confiriendo dignidad\npor reunirme en un lugar,\nasí que ayúdame a decirle\na mi padre en el cielo\"\nCuando el campesino termina\nde deshierbar la tierra\ncoge con su machete a Aikújegúnrè\ny la coloca sobre un tocón (kukute)\nAikújegúnrè dice:\n\"cuéntale a mi padre en el cielo\nque me están honrando (dignificando)\nme están sentando sobre una aga\"\npor eso, las últimas palabras usualmente\ndichas por Aikújegúnrè (tipo de hierba) son:\n\"el campesino no debe morir (desaparecer),\nyo no debo morir tampoco,\nasí permaneceremos juntos por siempre\".", "origen_id": "ec9460282330180d3f4c07c0"}]}, {"titulo": "Relaciones espirituales", "texto": "Orí recibe el ñame machacado. Los 'hijos del búfalo' ofrecen ante el cuerno; algunos lo relacionan con Ọya. El Òrìṣà da a su hija Bòmbò a Ọ̀rúnmìlà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pez de lodo grande, iyẹ̀-ìrosùn, ñame de semilla, cerveza de maíz, machete. Tabú en casa de cazador: golpear leña contra el suelo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 160.1 (yorùbá): Ọ̀sá'Gúndá le jà, / Oiderẹ awo Igbado, / Alùkò awo lgbado, / Aija-gogorogo Awo Olibara: / li o difá fún Olibara. / Oiderẹ awo Igbado (àlejò), / o ni oun ri ire Ajé fún Olibara / nitorinaa kiorú: / Eyẹlé, àgùtàn / ati egbàá méjilélógún owó. / O rúbọ. / Alùkò awo Igbado (òun naa àlejo), / Ó ni òun ri ire ọmọ, / O niki Olibara rú: / Ewúré, agbebo-adiyẹ / ati egbàá merindilógún owó. / Ô gbọ̀ ó rú. / Aija-gogorogo awo ilé Olibara, / o ni ogun li oun ri, / O niki Olibara rúbo: / Agbo, egbàá mẹ̀talélọ̀gbọ̀n owó. / O ni bi Olibara ko ba rúbo, / O ni ogun yoo de ni ojẹ mókănlá. / Olibara ko rúbọ. / Qjo mokănlá pe, Ogún de. / Olibara sa'gun kuro ni ilú.", "Verso 160.2 (yorùbá): Sun-mis'ebe, / Sun-mis'aporo ẹsẹ: / li o difá f'àikújegúnrè / ati Oloko (Agbẹ̀). / Wọ̀n niki àikújegúnrè wa rúbo: / İgbin, abo-adiyẹ ati agbo. / Wọ̀n ni: / \"ko maa kú, a joyè, agún aga\". / Ó gbọ̀ ó rú. / Wọ̀n niki Oloko wa rúbọ, / Aikújegúnrè: Tipo de hierba, CoMMELINA sp., Commelinaceae. / aga: silla o taburete. En este caso el muñón de un árbol cortado en el campo, / donde el agricultor coloca la hierba constituye para la hierba una silla de honor. / Oloko ko maa kú. / Ẹbọ: Eran agbo, àdá / ati egbaa mẹtalélógbọ̀n owó. / Ó gbọ̀ ó rú. / Nigbati Oloko ba r'oko / a fi àdá ko aikújegúnrè jẹ sibikan. / Aikújegúnrè a maa wipe: / \"Emi joyè Lakojo, / ẹ bami wi fún baba mi li òrun\". / Nigbati Oloko ba r'oko tán / tiofi àdá rẹ̀ ko Aikújegúnrè / si orí kukute / Aikújegúnrè a maa wipe: / \"Ẹ bami wi fún Baba mi lode òrun pe\". / \"Emi joyè orí aga o\", / nitorinaa, / orọ ikẹhin ti Aikújegúnrè nsọ niipe: / \"Ki Oloko ma kú o, / ki emi ma kü, / ki a njọ fi àikú j'egbo s'ara\"", "REZO: OSA KULEYA YIBIO YIBIO OMO OLOGU IYA MI ODESE BABA MI LEBO.", "REZO: OSA OGUNDA WARA WARA AYE WARA WARA OU ADIFAFUN ASHUMARE AKUKO LEBO. OUN AYAPA TIROKO AFEYU AFELEPE ADIFAFUN UMBO OUN BATINLO LOKO. ODE BOGBO TENUYEN BOBAYE OLUWO LAKI OYUGBONA LABERO ADIFAFUN APOTIN SHOMO BINI ORUNMILA OMA URE LEBO. ELEBO AKARAN NIRA ESHU EYE EURU ONI SHANGO OLO NINSHAWO ARA AWO ERI ARABAYE ISHU AGARA ADIE LEBO. AKUKO, EYELE LEBO.", "REZO: TINITINI TINI SOROIKIMBO TANIBORO OLUWO OPA ILERE OI FENAN SILE ONINKO ASHE AGBADO KINIRINNI FEFE KUFE. AYAPA FINUSO.", "REZO: OSA KULEYA, OMO ONI BABALAWO OBARA BAIFE MOYUGE, UMBATI FOBATE OMO ONI BABALAWO OSA BARA IFE TIBAISHE OMO AWO ODILA OYA OKUN ARAMORI OBAISHE OSHANLA OLO SABI OMO OBAISHE ONI SHANGO IGUAIRE ILE OBA ILIRE ONI BABALAWO, OSA BARA IFE IFA, KAFEREFUN OLOKUN OMO WAIRE OLOFIN.", "REZO: LATEJOJO LERI GUACUNI AKOMO HYAPA AJA OBINI DACULA EBA ASHERE ARUBA LODAFUN OLOKUN YENI DEREGBA ACAÑA ERI.", "SUYERE: ALOMIDA, FIRE, AWADO LERI AYAPA OSA KULEYA.", "REZO: OSA KULEYA EJA OSA KULEYA AWA AWO OMO ADISHE ABASHE OMO YARO IYA ELE IBU AÑAUN ÑOÑA IBA AWO EBA AWA OUN TIRCO A ARIBO KOWA TESHE IBASHE AÑOÑU EYE FISHE IBASHE ELENU AUN."]}]$q$::jsonb),
(161,'f1fee6bd1c728b75398dfbe70277358d','1b732d36fc65b4cf876142ed123333af',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Ìká anuncia un hijo y pide ofrendar para que padres e hijo tengan asiento y estabilidad; también habla de proteger los secretos. Un antiguo empleado, una persona cercana o los chismes pueden revelar sus secretos y causarle problemas. Ifá escucha sus ruegos, y lo que pida debe darse el mismo día. Llegará a viejo aunque lo molesten."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le preocupa el futuro de un hijo o dónde va a vivir (relato de Ọmotitun).", "Viaja mucho y busca un lugar estable.", "Alguien de confianza puede contar sus secretos (relato de Ayékogbejẹ)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un hijo que tenga un lugar estable en el mundo.", "Que los secretos no salgan a la luz.", "Que Ifá escuche sus súplicas.", "Llegar a viejo sin que lo venzan."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La abundancia lleva a un incremento en el poder personal. (Este Odu habla de la necesidad de ser honorable en asuntos relacionados con el espirítu)", "origen_id": "33ceb09dc344289599eadbb9"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Andar errante sin asentarse.", "Un confidente que revela los secretos.", "Vergüenza por lo que se divulga."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La inestabilidad mental lleva al comportamiento impropio. (Este Odu habla de la posible vergüenza que viene del comportamiento impropio no honorable en asuntos relacionados con el espirítu)", "origen_id": "8f04de89ba8e3bb6e9fe161f"}]}, {"titulo": "Enseñanza principal", "texto": "Por mucho que pisen a la sandalia, sigue hablando y dura hasta vieja. El que ofrenda no se desgasta antes de tiempo."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odu Ọ̀sá-Ká pronostica un nuevo hijo y aconseja hacer sacrificios para ntizar el asiento y estabilidad de los padres e hijo. Además habla de la ldad de proteger los secretos personales.", "origen_id": "e38f2c61bea77cd7fba81a29"}]}, {"titulo": "Relatos reunidos", "puntos": ["El recién nacido viajero. Le dijeron a la familia de un recién nacido que de grande le gustaría andar por todo el mundo sin asentarse, y que ofrendaran para que tuviera residencia estable: un caracol, un pangolín, 3,200 cauríes y medicina de Ifá.", "Los secretos revelados. Un confidente estaba revelando los secretos de Ayekogbejẹ. Le pidieron un caracol, aceite de palma, manteca de cacao, una paloma, 6,600 cauríes y medicina de Ifá para no pasar la vergüenza. Ofreció.", "Onílé Orókè y la campana. Onílé Orókè ofreció. '¿Oyen la campana? Sí, la oímos en casa de Onílé Orókè. Ifá escucha nuestra súplica.'", "La sandalia en Lìkì. La sandalia iba a ejercer en la tierra de Lìkì y preguntó si le iría bien. Le dijeron que sí, si ofrendaba. Por más que la pisaban y la arrastraban, seguía sonando 'pèé, pèé'; no la vencieron, y solo la dejaron cuando ya estaba vieja."], "pasajes": [{"titulo": "Verso 161.1", "texto": "\"Oná viaja alrededor\":\nadivinó IIfá para un recién nacido,\nEl adivino dijo:\nil bebé le gustará viajar por todo el mundo cuando sea mayor\nvagabundear, vivir la vida por el mundo,\nn tener un lugar estable donde asentarse).\ne fue aconsejado hacer sacrificio\nmatn que el bebé pueda tener\nI rosidencia estable (asentamiento)\neque a estar acomodado en el mundo.\nmcrificio: caracol babosa, Aiká,\nnegro, 3.200 cowries y medicina de Ifá.", "comentario": "viaje errante, divagación, andar de un lugar a otro sin estabilidad: irin: aminata, kiri: v. vagar; andar errante; alárinkiri: s. vagabundo, errante i un viaje definido a un lugar distante se emplea en yoruba irin-àjò.\na distante.", "origen_id": "921f4d41df968c7bbb69ff27"}, {"titulo": "Verso 161.2", "texto": "\"Los secretos se hicieron públicos\":\nadivino lta para Ayekogbejẹ,\ncuando un confidente?3\nestaba revelando sus secretos.\nLe fue aconsejado hacer sacrificio\npara que no viviera un problema vergonzoso\nporque sus secretos fueran divulgados.\nSacrificio: caracol babosa, aceite de palma,\nmanteca de cacao, paloma,\n6.600 cowries y medicina de Ifá.\nEl oyó e hizo el sacrificio.\n2° Jókó-jé: CISSAMPELOS OWARIENSIS P. Beauv., Menispermaceae.\nAiká: pangolín.\n252 bràn itiju: problema vergonzoso, vivir el problema de sufrir vergüenza por\npalabras o acciones deshonrosas o humillantes, por causa propias o ajenas.\n283 Nota: Confidente: persona a la que se cree fiel, de confianza,\ncomo para confiarle secretos o encargarle la ejecución de cosas reservadas.", "origen_id": "29a731efcd0e0e70595880f7"}, {"titulo": "Versos complementarios 1 · A", "texto": "Ifá pé ire fún eléyìun; ayée rè' ó dáa. Ifá pé àwon\n                                                 ' Irúnmolè ' ' ó gbóhùn rè,\n                                                                           ' sùgbón\n                                                                             '     '\nohunkóhun ti Ifá bá gbá lójó\n                           ' ' náà ni kó fún un. Ifá pé òún ó gbó' ohùn eléyìun, òun ó sì\ngbó' ti eni\n        ' ó dá Ifá yìí náà. Ifá pé kí eléyìun ó móo\n                                                  ' ' sòótó' o. Kó sì móo\n                                                                       ' ' sòrò\n                                                                            ' ' Ifá lénu\n                                                                                     ' è' ní\nrere.\n\nÓ sá kádi\nÓ rìn kádi\nÓ fò fèrè' ' fèrè\n               ' '\nÓ módi Ìká gùn\nA díá fún Onílé Orókè\nÈyí tíí somo' ' Abèwolégi\n                     ' '\nWón '   ní  kó sá káalè' ebo\n                         ' ' ní ó se\n                                  '\nÓ sì gbébo     ´´\n                nbè\n          ' '      '\nÓ rúbo'\nE' wá ´´n gbágogo\nA bé ò gbágogo?\nÀwá mòmò        ´´\n           ' ' n gbágogo\nNílé onílé Orókè\nIbè' la gbé ´´n gbágogo\nIfá wá ´´ n gbó' tiwa\nÀbí ò gbó' tiwa?\nOnílè Orókè\nIfá ´´n gbó' tiwa\n\nÒsá\n ' Ìká A\nIfá desea bien a esta persona. Ifá dice que los Irúnmolè oirían Su lamento, pero\ncualquier cosa Ifá exige de él debe darse el mismo día. Ifá escucharía el lamento de esta\npersona y la voz del Babaláwo que lanzó la adivinación. Este Babaláwo debe ser\nverídico y alabar Ifá siempre.\n\nÉl corre hacia dentro a esconder\nÉl camina hacia dentro a esconder\nÉl salta alto\nY subir a los límites de Ìká\nAdivinación lanzada para Onílé Orókè\nEl niño de Abèwolégi\nLe pidieron cuidar de la tierra y realizar el sacrificio\nÉl oyó hablar del sacrificio\nY lo realizó\n'Pueda usted oír el gong resonante\n'¿O usted no puede oírlo?'\nNosotros realmente estamos oyendo el gong resonante\nEn la casa de Onúilé Orókè\nAllí, nosotros oímos el sonido del gong\nIfá escuchan ahora nuestra súplica\n¿No hace él?\nOnílé Orókè\nIfá escucha nuestra súplica.", "origen_id": "ec25155ed4ceb99150dad387"}, {"titulo": "Versos complementarios 2 · B", "texto": "Ifá pé ó ye' eléyìun. Bí ón\n                         ' ti wulè' kí wón\n                                        ' ó se\n                                            ' tó, eléyìun ó móo\n                                                             ' ' jayé ni. Ifá pé ka si móo\n                                                                                        ''\nse\n' bíi tòun.\nÓ dá sáká sáká\nÓ rìn sáká sáká\nA díá fún Sálúbàtà\nNíjó' ti ´´n sawoó relèe      ' ' Lìkì\nWón  ' ní kó rúbo´´    '\nIlèe\n   ' ' Lìkì tí òúj ´´n lo' yìí\nÓ dáa fún òun nbè?         '\nWón  ' ní yóó dá fún un\nWón  ' ní ebo\n            ' ' ni kó se    '\nKò sí bí won    ' ò ti ra á mólè     ' ' tó\nWón  '  ní  o  ó móo'' '  fohùn      ni\nNí ó móo  ' ' ' ' ' pèé\n               se  pèé       ' ' pèé''\nWón  '  ra  á,  ra á\nIpá ò ka\n´´\nNgbà ó bá sú won         ' tó gbó\nWón  ' ó bàá fi Sálúbàtà sílè'\nSálúbàtá gbó; ó tó'\nIfá pé emí\n         ' eléyìun ó gùn\nÓ ní ódá sáká sáká\nÓ rìn sáká sáká\nA díá fún Sálúbàtà\nTì ´´n sawoó relèe    ' ' Lìkì\nWón  ' ní ó sá´´káalè' ebo    ' ' ní ó se'\nÓ sì gbèbo ' '   nbè '   ó rúbo   '\nÀbòdé  ' ilèe' ' Lìkì\nMo wáá dá sáká o\nMo rìn sáká o\nSálúbàtà wáá ségun   ''\nÒsá\n ' Ìká B\nIfá dice que la vida agradaría a esta persona. No importa cuánto ellos lo preocupan, él\nestaría disfrutando la vida y envejecería. Él se manda para comportarse en la semejanza\nde Ifá.\n\nÓ dá sáká sáká\nÓ rìn sáká sáká\nAdivinación lanzada para las Zapatillas\nEl día que él estaba aventurando el sacerdocio en la tierra de Lìkì\nLe pidieron que realizara el sacrificio\n'¿Esa la tierra de Lìkì que yo voy?'\n'Sería bueno apartado para mí allí'? las Zapatillas habían preguntado\n'La vida estaría allí buena para usted'\n'Pero usted debe realizar sacrificio'\nNo importa cuánto ellos lo friegan (maleza, matorral, reserva) cuando lleva puesto\nTodavía estaría hablando\nSonando 'pèé', 'pèé'\n\nEllos lo llevaron continuamente\nEllos no podrían superarlo\nCuando ellos se alimentaron a y las Zapatillas se envejecieron\nEllos lo dejarían solo\nLas Zapatillas envejecieron y viejas\nIfá dice que esta persona envejecería en la vida\nÓ dá sáká sáká\nÓ rìn sáká sáká\nAdivinación lanzada para las Zapatillas\nEl día que él estaba aventurando el sacerdocio en la tierra de Lìkì\nLe pidieron cuidar de la tierra y realizar el sacrificio\nLas Zapatillas oyeron hablar del sacrificio y lo ofrecieron\nEn el viaje del retorno de la tierra de Lìkì\nYo me lavo limpiamente\nYo caminé limpiamente y galantemente\nLas Zapatillas ganaron.", "origen_id": "f0a2b9d8a5009b1d69e1af79"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Osa-Ka habla de pronosticar un nuevo hijo y de la protección de\n                                                      secretos personales.\n    WO - Un comentario acerca de un antiguo empleado puede causar\n                                                 problemas para el cliente.\n\n\n161.1 · Osa camina alrededor, fue adivinado por Ifá para un nuevo\n             bebé. Esto fue profetizado que el nuevo bebé sería también\n     aficionado de caminar o viajar por el mundo cuando fuera mayor.\n   Ellos dijeron que el sacrificio debía hacerse así el bebé pueda tener\n         un lugar de residencia en la tierra y quizás muy adinerado. Ebo:\n         caracol de babosa, 1 aika (especie de animal de matorral), jabón\n negro, 3.200 cowries, hojas de Ifá. Las hojas de Ifá deben ser molidos\n     y preparados como sopa con el aika y el caracol también para ser\n   tomados por el cliente y las hojas de Ifá deben ser molidos también\n                                        para mezclar con jabón para baños.\n\n\n161.2 · Los secretos se hicieron públicos, esto fue adivinado por Ifá\n  para Ayekogbeje. Un confidente está revelando secretos. Se le pidió\n          que sacrificaca así no haría cosas vergonzosas en secreto y ese\n  secreto fuera divulgado. Ebo: 1 babosa o caracol, manteca de corojo,\n   manteca de cacao, 1 paloma, 6.600 cowries y hojas de Ifá. Él oyó y\n                                                         hizo el sacrificio.", "origen_id": "a8a6172543672e5489288b9f"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El recién nacido: un caracol, un pangolín, 3,200 cauríes y medicina de Ifá.", "Contra la vergüenza: un caracol, aceite de palma, manteca de cacao, una paloma, 6,600 cauríes y medicina de Ifá.", "Lo que Ifá pida, el mismo día."], "pasajes": [{"titulo": "Ofrenda en el verso 161.1", "texto": "\"Oná viaja alrededor\":\nadivinó IIfá para un recién nacido,\nEl adivino dijo:\nil bebé le gustará viajar por todo el mundo cuando sea mayor\nvagabundear, vivir la vida por el mundo,\nn tener un lugar estable donde asentarse).\ne fue aconsejado hacer sacrificio\nmatn que el bebé pueda tener\nI rosidencia estable (asentamiento)\neque a estar acomodado en el mundo.\nmcrificio: caracol babosa, Aiká,\nnegro, 3.200 cowries y medicina de Ifá.", "origen_id": "23a71d2ac3bfab26c0c18630"}, {"titulo": "Ofrenda en el verso 161.2", "texto": "\"Los secretos se hicieron públicos\":\nadivino lta para Ayekogbejẹ,\ncuando un confidente?3\nestaba revelando sus secretos.\nLe fue aconsejado hacer sacrificio\npara que no viviera un problema vergonzoso\nporque sus secretos fueran divulgados.\nSacrificio: caracol babosa, aceite de palma,\nmanteca de cacao, paloma,\n6.600 cowries y medicina de Ifá.\nEl oyó e hizo el sacrificio.\n2° Jókó-jé: CISSAMPELOS OWARIENSIS P. Beauv., Menispermaceae.\nAiká: pangolín.\n252 bràn itiju: problema vergonzoso, vivir el problema de sufrir vergüenza por\npalabras o acciones deshonrosas o humillantes, por causa propias o ajenas.\n283 Nota: Confidente: persona a la que se cree fiel, de confianza,\ncomo para confiarle secretos o encargarle la ejecución de cosas reservadas.", "origen_id": "dd468d5e8068f1cc79c76111"}]}, {"titulo": "Relaciones espirituales", "texto": "Las Irúnmọlẹ̀ escuchan la súplica. Ifá oye la voz del babaláwo verdadero."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de jókó-jẹ (Cissampelos owariensis) cocinadas en sopa con carne de pangolín y caracol, y molidas con jabón para baño. Caracol, manteca de cacao."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 161.1", "texto": "Las hojas de Jókó-jẹ° deben ser molidas y preparadas en sopa con la carne del Aiká y del caracol babosa, para ser tomados por el cliente. Las hojas de Ifá, también, deben ser molidos también para mezclarlas con jabón y usarlo para baños.", "origen_id": "9fbc86113cf7b20d75332e19"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 161.1 (yorùbá): Ọ̀sá-rin-ka: / a difá fün Ọmotitun, / wọn ni: / Dmotitun yi a feran irinkiri ninu ayé / nigbati o ba dagba. / Wọ̀n ni ki a rúbọ / kloleni ibujoko li ayé; / kiara le rọọ. / Ebọ: Igbin, Aiká, Ọ̀ṣẹ́, / egberindilógún owó / ati ewé Ifá (Jókó-jé)", "Verso 161.2 (yorùbá): Ọrọ-ikoko-gbamgba-ni-mbq: / a daa fún Ayékogbejẹ. / Ẹni ti a ba mulẹni kọkọ / ntumọ ohun tiajoṣe, / wọ̀n niki o wa rúbọ / ki o ma baa ṣe ğràn itiju si ikoko, / ki orẹ ma le tu aṣiri rẹ. / Ẹbọ: İgbin, epo, òrí, eyẹlé, / egbẹ̀talélógbọ̀n owó ati ewé Ifá. / Ó gbọ̀ ó rú.", "REZO: OSA KANI IWANI AUTELE KOLE ADIFAFUN ARITINLO EYUA YOLE ELANYO EYUA AKUKO LEBO, OUNKO LEBO, ORI EBBO, ADIE, EWE TINLO YOKULA UNLO ASHO FUN FUN IKAN LOWA. OSA KA IFA OINA LORDAFUN OMO."]}]$q$::jsonb),
(162,'d2df7f961b6ccd24d378dbaaaea98bcc','9bd662c3ff4e2fc236518bd14a3e8f9e',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Òtúrúpọ̀n habla de la infertilidad y de la ofrenda para una vida larga. Es buen momento para ofrendar a Ògún buscando concebir. Pide ofrendar por hijos agradecidos y que la mujer no deje a su esposo para no lamentarlo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Desea tener hijos o le preocupa su fertilidad (relato de Ọ̀sá Atinuṣojo).", "Quiere asegurar su bienestar a largo plazo.", "En la familia hay tensión entre juntar bienes y cuidar a los hijos (relato de Yèyé Owójùwà y Yèyé Omójùwà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Salud y vida larga, como la piel del animal.", "Hijos que honran a la madre.", "Riqueza, pareja e hijos en la casa de la mujer que se calma."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La abundancia lleva a la protección de las enfermedades. (Este Odu habla de la necesidad de ignorar los efectos del chisme y envidia.)", "origen_id": "d8f24f3e69c19dd1951ac781"}]}, {"titulo": "Ibi y advertencias", "puntos": ["No poder cargar un hijo en la espalda.", "Tener solo dinero y nadie que herede.", "Andar de un lado a otro sin asentarse en la casa."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La inestabilidad mental lleva a la enfermedad. (Este Odu habla de la posibilidad de una enfermedad e infertilidad para esos quienes hacen interno el chisme y envidia)", "origen_id": "7f2fb81ea9bff238155353a2"}]}, {"titulo": "Enseñanza principal", "texto": "Los hijos valen más que la riqueza. Owójùwà ofrendó solo por dinero y, al morir, otros heredaron; Omọ́jùwà ofrendó por hijos, y sus hijos la enriquecieron y la despidieron con honores."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀sá-Òtúrúpọ̀n habla de infertilidad y del sacrificio para alcanzar una larga vida.", "origen_id": "199b187ded51b3defbc783c1"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀sá Atinuṣojo. 'Ella no carga un bebé en la espalda.' A Ọ̀sá Atinuṣojo le pidieron una chiva, una gallina, 16,000 cauríes y medicina de Ifá para tener un hijo. Se negó.", "La piel del animal. A la piel le dijeron que sería salud y vida larga para el cuerpo de cualquier animal, y ofreció una paloma, una carnera, kola y 42,000 cauríes.", "Owójùwà y Omọ́jùwà. Dos mujeres venían del cielo a la tierra. Owójùwà ofrendó solo por la riqueza y llegó a tener dinero sin medida, pero no tuvo hijos; cuando murió le hicieron su ceremonia y todos se fueron, y otros se quedaron con su dinero. Omọ́jùwà ofrendó por los hijos y tuvo muchos; lo que ganaba, los hijos se lo comían, pero con el tiempo ellos la enriquecieron. Cuando murió, sus hijos la enterraron con honores, ensillaron un caballo, bailaron por el pueblo y dispararon al aire, cosa que entonces no se hacía. El rey los llamó, y ellos le dijeron: 'La madre no muere dos veces'. Le cantaron: 'Los hijos valen más que el carácter, hoy y mañana'. El rey reconoció que tenían razón y los dejó seguir bailando.", "La gallina que andaba de un lado a otro. A Olórùbùrekè, la gallina, le dijeron que fuera tranquila y reservada en casa de su esposo. No hizo caso y andaba de un lado a otro. Después ofreció, se calmó, y en su casa no faltó riqueza, pareja ni hijos."], "pasajes": [{"titulo": "Verso 162.1", "texto": "\"Ella no lleva un bebé en su espalda\":\nadivinó Ifá para Ọ̀sá Atinuṣojo,\nLe fue aconsejado hacer sacrificio\npara que ella fuera capaz de parir un niño.\nSacrificio: chiva, gallina, 16.000 cowries y medicina de Ifá.\nElla escuchó y rehusó sacrificar.", "origen_id": "4c11e9a27e3ce8f31084d348"}, {"titulo": "Verso 162.2", "texto": "Ọ̀sá-Òtúrúpọ̀n,\nỌ̀sá-Òtúrúpọ̀n:\nadivino Ifa para la piel del animal.\nI djo: \"La piel será para el cuerpo salud y larga vida\nen cualquier animal en el mundo\".\nSacrificio: paloma, carnera, nueces de kola y 42.000 cowries.\nLa piel oyó y sacrificó.", "origen_id": "4c94cd80d78ca9a805bec8d8"}, {"titulo": "Versos complementarios 1 · A", "texto": "Ifá pé ayé ó ye' eléyìun,       '            nnkaan 'rè ò sì níí bàje.\n                                                                      ' Ifá pé' okàan 'rè ó balè,\n                                                                                              ' ' sugbón\n                                                                                                     '   kó rúbo\n                                                                                                              '\n   dáadáa kí' omo          ' rere ó gbèyìn        `` òun.\n   Ìgbòho, Ìgbòho\n   A díá fún Yèyé Owójùwà\n   Níjó tí n 'tòrun bò wálé ayé\n'´´Ebo ' n wón '          ní ó' se\n   Ngbà tí ó rúbo' è\n ' Ebo ' ajé ló rú\n   Ó bá bèrè ' ' síí lájé\n   Ó lówo láyé, owó ò ní mòmó                  ' ' mó  '\n   Ìgbòho, Ìgbòho\n   A díá fún yèyé' Omójùwà          '\n   Níjó      ´´\n        ' tí n 'tòrun bò       ' wálé ayé\n ' Ebo ' n wón '          ní ó' se\n   Òun bá rúbo         ' ' omo '\n   Omó\n ' ' '       pò\n   Ilè        ´´\n   ' kún ngbà ó dójúde ìsálayé\n   Yèyé Owólójùwà´´n lájé\n   Bí yèyé' Omolójùwà   ' ´´             tí´´n' se é´´ntiè\n                                                       '\n   Béè\n    ''     làwon\n               ' ' '     omo     n ' je' é\n´´Ngbà        ó 'pé sàà\n   Yèyé Owójùwà bá kú\n   Wón                 ´´\n     ' ' se Ìta nlé' è\n   Bí' ón ti' se Ìta tán\n   Oníkálukú bá 'korí sílée won                  '\n   Kò kúkú ' lómo         ' láyé\n   Owó bá dowó' elòmíìn\n ' Ojó\n     ' wáá yí lu' ojó          '\n   Osù\n    ''      yí  lu   osù\n                     '\n   Àwon  ' ' omoo ' ' yèyé' Omójùwà      '            bá la Ìyáa won\n                                                                 '\n   Òun náà lówó\n´´Ngabà ó pé sàà\n                   '\n   Yèyé Omòjùwà  '               náà kú\n   Àwon  ' ' omo  ' ' è bá gbé ìyáa won            '\n   Wón\n     '       sin   ín\n   Wón\n     '       bá ta 'amó' esin\n   Wón     ´´n jó kiri' ìlú\n     ' ´´\n   Wón\n     '       n tànkúú 'lo\n   Wón         ´´\n     ' ´´bá n dárin\n   Wón\n     '       n pómó\n                ' ' jùwà o\n ' ' ' jùwà\n   Omó       mò\n   Ìgbòho\n ' Omó   ' mò ' jùwà\n ' Omó       jùwà        lónìí' omó  ' jùwà lóla\n   Ìgbòho\n ' Omó   ' jùwà ò' omó         ' mò   ' jùwà\n   Ìgbòho\n ' Omó   ' mò ' jùwà\n   Àwon  '     onílù fìlù si\n                ´´\n\n  Wón\n    '       bá n yinbon   '      pé ìyá àwón\n                                           '     kú\n  Wón\n    '       è é  sì  í yìnbon'      láàrin ìlú  nígbà  ìwásè\n                                                          '\n' Obá bá gbúròó won           '\n' Obá ní kí wón    ' ´´ ó wá\n  È é ti rí 'tée ' fí n yínbon?   '\n  Wón\n    '       ní  À!\n  Ìyá tó bí àwon          ´´\n                    ' ´´ nnú\n  N ló 'lo làwón n 'yò\n  Táwon      ´´n yìnbon sí\n         '              '\n' Obá ní 'sée   ' gbó  ' pé' enìkan a móo    ' ' yìnbon'\n  Wón ní baba mó bìínú\n    '\n  Ìyà ò níí kú 'léèmejì '\n' Obá ní ó dáa kí wón          '     ó tún orii won\n                                                  '   'ko\n  Wón\n    ' tún ní Ìgbòho\n' ' mò\n  Omó        ' jùwà\n' Omó  ' jùwà lónìí o' omó          ' jùwà 'lóla\n  Ìgbòho\n' Omó  ' mò  ' jùwà\n  Omó\n' '         jùwà     o' omó ' mò  ' jùwà\n  Ìgbòho\n' Omó  ' mò  ' jùwà\n  Obá      ní  lóòótó                           ´´\n'                    ' ni àwon    ' ' omo' yìí n 'so\n  Níjóo\n      ' ' Yèyé Owójùwà kú\n  Tó ra' erú\n  Tó ra' erú\n  Tó kólé\n  Wón\n    '       túká´´nlé' è ni\n' Èyin' omo    ' ' le wáá' se èyí?\n  Ó dáa\n' E móo ' ' jó\n  Kée\n   ' ' móo ' ' yò.\n\n' Òsá Òtúrúpòn A\n  Ifá desea bien a esta persona. Estaría bien. Pero él debe realizar el sacrificio para los\n  niños compasivos.\n\n Ìgbòho, Ìgbòho\n Adivinación lanzada para la Madre Owójùwá\n En el día ella estaba viniendo del cielo a la tierra\n Le pidieron que realizara el sacrificio\n Cuando ella estaba realizando su sacrificio\n Ella sacrificó exclusivamente para la riqueza\n Ella llego a la tierra y empezó teniendo la riqueza\n Ella tenía tanto dinero a la magnitud de no poder estimarlo\n Ìgbòho, Ìgbòho\n Adivinación lanzada para la Madre Omolójùwà\n En el día ella estaba viniendo del cielo a la tierra\n Le pidieron que realizara el sacrificio\n Ella solo realizó el sacrificio para los niños\n Ella tenía tantos niños\n\nSu casa estaba llena de niños cuando ella llegó sobre la tierra\nLa madre Omojùwà estaba teniendo toda la riqueza\nPero en cuanto la Madre Omojùwà trabajo para el dinero,\nLos niños lo consumirían\nDespués de un tiempo prolongado\nLa Madre Owójùwà se murió\nLas personas observaron 'Ìta' en su casa\nDespués de la observancia de ritos de Ìta en su casa\nTodos volvimos a su o su morada respectiva\nElla no tiene ningún niño\nAlguien más heredó su dinero\nDías pasaron después de días\nMeses después de meses\nLos niños de Madre Omójùwà enriquecieron a su madre\nElla tenía el dinero también\nY después de un período de tiempo\nTambién la Masdre Omojùwà se murió\nLos niños llevaron a su madre\nEllos dieron su entierro adecuado\nEnsillado un caballo\nY empezó a bailar alrededor del pueblo\nEllos estaban realizando la ronda de ritos de entierro\nEllos cantaron las canciones\nEllos estaban cantando 'realmente, los niños son mayores que el carácter'\nRealmente, los niños son mayores que el carácter\nÌgbòho\nRealmente, los niños son mayores que el carácter\nLos niños son mayores que el carácter hoy e incluso en días a venir\nÌgbòho\nLos niños son mayores que el carácter\nLos tambores dieron el golpeteo fuerte\nEllos empezaron explotando los tiros en el aire,\nPero en los días antiguos, nadie dispara en el aire en el medio de las ciudades\nEl rey oyó hablar como resultado del acto prohibido\nÉl los convocó en el palacio\n'Por qué usted debe disparar armas? El rey preguntó\n¡Ha! Ellos exclamaron\n'La mujer que dio el nacimiento a nosotros es la razón'\n'Ella está muerta y nosotros estamos regocijando'\n'Y ésa es la razón para los tiros\n'Tiene su oído a cualquiera haciendo en la vida que antes'? El rey preguntó, visiblemente\nenfadado\n'No se ofenda, Kabiesi\nLa madre de uno no se morirá dos veces' ellos contestaron\nEl rey pidió entonces que ellos cantaran la canción que él oyó que ellos cantaban de\nnuevo\nEllos Realmente cantaron, Ìgbòho\nLos niños son mayores que el carácter\nLos niños son mayores que el carácter hoy e incluso en días a venir\nÌgbòho\n\n El niño es mayor que el carácter\n Los niños son mayores que el carácter hoy e incluso en días a venir\n Ìgbòho\n El niño es mayor que el carácter\n 'Realmente, lo que estos niños están diciendo es verdad', el rey razonó\n 'En el dia que la Madre Owójùwà se murió'\n 'El que compró a tantos esclavos\n 'Y tenía toneladas de cargas para ponerse la cabeza del esclavo'\n 'Y construyó tantas casas\n 'Todos dispersamos fuera de su casa'\n En su caso, ustedes niños han realizado un hecho'\n 'Eso esta bien'\n 'Usted puede seguir bailando'\n 'Y estar regocijando'", "origen_id": "e8018a618e5d89c17e8e7c9e"}, {"titulo": "Versos complementarios 2 · B", "texto": "Ifá pé kí eléyìun ó rúbo;\n                         ' Kó sò móo' ' ' se bíi tifá.' Sùgbón\n                                                            '  ngbà ó bá yá Obìnrin' è ó pèé òun\n´ n lo. Ifá pé kò gbodò lo; torí bó bá lo yóó kábàámò è.\n     '              ' '                                  ' '\n  Àgbé réke réke                                             ´\n  A díá fún Olórùbùrekè            ' '\n  Tí´´n fomi ojú sògbérè' omo                ' ´´\n  Wón\n   '      ní  bó       bá   ti  dé    ilé  ibi  tí n lo\n  Wón     ní  kó       fara    balè   ´´nbè o '\n   '                              '       '\n  Olórùbùrekè ' '          ò  ti kókó\n                                 ' ' 'fé\n  À á' séé mo   '       Olórùbùrekè?   ' '\n  Làá pe Agbébo           '    Adìe '\n  Kò ' jé 'pé´´nlé' oko     '    àárò ' kéé dalé   '\n            ´´\n  Kíkó ní n kóó kiri\n  Ló bá rúbo    '\n  Ló fara balè     '\n  Ní wá n jó ní´´n 'yò\n  Ní´´n yin àwon     '        Babaláwo\n  Àwon\n     '      Babaláwo´´n yin Ifá\n  Ó ní béè\n         ' ' làwon     '       Babaláwo tòún wí\n  Àgbé réke réke\n  A díá fún Olórùbùrekè            ' '\n  Tí´´n fomi ojú sògbérè' omo                '\n  Àgbé réke réke\n  Ajé e é wón          ´´nlé Olórùbùrekè\n               '                             ' '\n  Àgbé réke réke\n  Aya è é wón           ´´nlé Olórùbùrekè\n                 '                             ' '\n  Àgbé réke réke\n                         ´´nlé Olórùbùrekè\n' Omo' è é wón     '                            ' '\n  Àgbé réke réke\n\n' Òsá Òtúrúpòn B\n  Ifá le pide a esta persona\n                     '       que ofrezca sacrificio. Él se manda para comportarse según las\n  instrucciones de Ifá. Su ``\n                           mujer puede intentar divorciarse de el; Ifá dice que que ella\n  debe advertirse para desistir por otra parte del acto que ella lamentaria.\n\nÀgbé réke réke\nAdivinación lanzada para Olórùbùrekè\nQue estaba llorando debido a los niños\nEllos le dijeron que en llegar a la casa de su marido\nElla debe ser dócil y reservada\nElla se había negado a considerar la advertencia al principio\n¿Cómo se conoce Olórùbùrekè?\nEs uno que alternativamente llamada la Gallina\nElla nunca sería sumisa en la casa de su marido mañana hasta noche\nElla estaba empacando alrededor (por todas partes)\nElla realizó el sacrificio después\nElla se hizo dócil y sumisa\nElla empezó a bailar y regocijar entonces\nElla estaba alabando su Babaláwo\nSu Babaláwo estaba alabando Ifá\nElla dijo que era exactamente como su Babaláwo había dicho\nÀgbé réke réke\nAdivinación lanzada para Olórùbùrekè\nQue estaba llorando debido a los niños\nÀgbé réke réke\nNo habrá nunca una carestía de riqueza en la casa de Olórùbùrekè\nÀgbé rèke rèke\nNo habrá nunca una carestía de esposas en la casa de Olórùbùrekè\nÀgbé rèke rèke\nNo habrá nunca una carestía de niños en la casa Olórùbùrekè\nÀgbé réke réke", "origen_id": "ea9b55d88a45ebf3edd7fb58"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Osa-Oturupon habla de infertilidad y del sacrificio para una vida\n                                                                            larga.\n                 WO - Este es el tiempo para sacrificcar a Ogun para concebir.\n\n\n162.1 · Ella no tenía el bebé en su espalda, fue adivinado por Ifá para\n            Osa Atinusojo, se le dijo que se sacrificara y así ella sería capaz de\n            parir un niño. Ebo: 1 chiva, 1 gallina, 16.000 cowries hojas de Ifá.\n                                                    Ella oyó y rehusó sacrificar.\n\n\n162.2 · Osa-Oturupon, Osa-Oturupon fue adivinado por Ifá para la piel\n               del animal. Ellos dijeron que la piel será salud y larga vida para\n            cualquier animal en el mundo. Ebo: 1 paloma, 1 carnero, nueces de\n                                  kola, 42.000 cowries. La piel oyó y sacrificó.", "origen_id": "a2fede7da84097d876ce3fa5"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para un hijo: una chiva, una gallina, 16,000 cauríes y medicina de Ifá.", "La piel: una paloma, una carnera, kola y 42,000 cauríes.", "Ofrenda a Ògún para concebir."], "pasajes": [{"titulo": "Ofrenda en el verso 162.1", "texto": "\"Ella no lleva un bebé en su espalda\":\nadivinó Ifá para Ọ̀sá Atinuṣojo,\nLe fue aconsejado hacer sacrificio\npara que ella fuera capaz de parir un niño.\nSacrificio: chiva, gallina, 16.000 cowries y medicina de Ifá.\nElla escuchó y rehusó sacrificar.", "origen_id": "1fddc52b08589457059768f5"}, {"titulo": "Ofrenda en el verso 162.2", "texto": "Ọ̀sá-Òtúrúpọ̀n,\nỌ̀sá-Òtúrúpọ̀n:\nadivino Ifa para la piel del animal.\nI djo: \"La piel será para el cuerpo salud y larga vida\nen cualquier animal en el mundo\".\nSacrificio: paloma, carnera, nueces de kola y 42.000 cowries.\nLa piel oyó y sacrificó.", "origen_id": "eccd91b7890caf6d5e1807f3"}]}, {"titulo": "Relaciones espirituales", "texto": "Ògún ayuda a concebir. El rey reconoce el valor de los hijos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Chiva, gallina, carnera, kola. Ante dificultades para concebir, conviene también la consulta médica."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 162.1 (yorùbá): Koromogbepon: / a difá fún Ọ̀sá Atinuṣojo, / Wọn niki o wa rúbọ / nitoripe kiobaa le r'omo bi. / Ebọ: Ewúré, agbebo, egbàájo owó ati ewé Ifá. / Ô gbọ̀ ẹbọ ko rúbọ.", "Verso 162.2 (yorùbá): Ọ̀sá-Òtúrúpọ̀n, / Ọ̀sá-Òtúrúpọ̀n: / a difa fún Awo (eran), / Wọ̀n ni: Ara Awọ a le, / a pe l'ayé ju erankẹran. / Ebọ: eyẹlé, àgùtàn, obi ati ẹgbàá mọ̀kànlélógún owó. / Ô gbọ̀ ó rú.", "REZO: OSA TRUPON ARIBURU TRUPON OSA RULU OTRUPON OM EYELE ELODI ODEFA AB TINSHOMO OLU OD OSA KUNA OTRUPON OM YEL LODI ADAFUN PAKERE, TINSHOMO OLUBO OSA TRUPON OSA LANU.", "REZO: OSA TRUPON ORITUROPON OSA OTRUPA AMEYLE ELADI ODIFA ABA TINCHOMA OLU ODA TRU AN ORI TUROPAN OSA LUNU OTUROPAN OMA EYELE LADI ADAFUN PAQUERE TINCHOMA OLUBO OSA TURUPAN ORI TURUPAN OSA LANU OTURUPAN OMA YEYE GUA OWO EYELE AKUKO LEBO.", "REZO: OSA TRUPON OSA TRUPASA OFORI BERE BERE RILE ENLLANLA OSHUN QUELE QUELE HUO ADIFAFUN ORUNMILA OLUPON TINLO NUMUCODABA NUNU OMI GUADA LLESASI OGUE Y SHANGO.", "REZO: KAFEREFUN SHANGO, YALORDE, OBATALA ALA OGGUN E ILLA.", "REZO: OSA TRUPO BEBEWA OKUN, ADIFAFUN OMO OLOKUN OMI LOSA ARUKO LASHE OKUN ORUN FOSHE, AYEBEWE OKUASUN AGANA ERI OMO OLOKUN OMILONA ORUKO LASHE BOKUN ORUN DOSA FOLOKUN OLONA, ALAYENIFA OMO LA MESAN ADIFAFUN OLOKUN AWONIFA OMO LOSAIN SAIN ORUN, OKANA YEKUABARI OZAIN OMOTOKUN AFEFE LAYRO BROMO, BRONSIA, AFEFE LEKUN ORUN EYA IKU OMO EYA NABEYA OLOKUN AGBA DOA OKUN LAYE IRENIFA OZAIN LODAFUN ORUNMILA."]}]$q$::jsonb),
(163,'f7377a2d09d32c1408403f4d8ecfcbe4','dc6e8e20db28355354e16b9a896c2c18',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Òtúrá dice que los dioses favorecen a quienes dicen la verdad y están en armonía con el buen carácter de Olódùmarè. La persona debe enfrentar un problema que ha estado evitando. Ifá le desea buena fortuna de pareja y le permite llegar a la raíz de lo que investiga."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está evitando un problema que ya conoce.", "Quiere investigar un asunto para saber qué lo causó.", "La decepción o el enojo le impiden hablar con franqueza (relato de Ọ̀sá Òtúrá preguntando qué es la verdad)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ser bendecido por decir la verdad.", "Conseguir pareja con astucia y paciencia.", "Llegar a la raíz de un asunto.", "No ver el mal si ofrenda."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La abundancia lleva a la visión mistica. (Este Odu habla de la necesidad absoluta de ser honesto en todas las cosas. La honestidad trae entendimiento honor y buena fortuna.)", "origen_id": "9255b6dd7f8cb80bb95d2854"}]}, {"titulo": "Ibi y advertencias", "puntos": ["La mentira.", "Evitar un problema que hay que enfrentar."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La inestabilidad mental lleva a la decepción. (Este Odu  habla de las consecuencias negativas de enojo excesivo y decepción.)", "origen_id": "4872b50a959125df82a88d7e"}]}, {"titulo": "Enseñanza principal", "texto": "La verdad es el buen carácter de Olódùmarè, su palabra que no falla y no se corrompe. 'Habla la verdad, sé justo: al que dice la verdad, Dios lo ayuda.'"}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀sá-Òtúrá dice que los dioses favorecen a aquellos que hablan la verdad (están en armonía con el buen carácter de Olódùmarè).", "origen_id": "ee813266043a45ce55906dfd"}]}, {"titulo": "Relatos reunidos", "puntos": ["¿Qué es la verdad? Ọ̀sá Òtúrá pregunta qué es la verdad, y Ọ̀rúnmìlà responde: es Olúwa, el Señor de la tierra; es la sabiduría que viene de Olódùmarè; es el buen carácter de Olódùmarè y su palabra infalible, la palabra que no se corrompe. Ifá dijo que las personas del mundo debían ser sinceras.", "Ọ̀rúnmìlà y las tres hijas. Tres muchachas, Somúrógé, hija de Alárá; Sòkùndìgbà, hija de Ajerò; y Somúlùké, hija de Ọwáràngún Àga, decidieron casarse solo con quien supiera sus nombres verdaderos. Ọ̀rúnmìlà preguntó cómo saberlos. Le dijeron que pusiera tres platos de ẹ̀kuru blanco en el camino por donde ellas iban al arroyo y se escondiera. Al ver los platos, se llamaron una a otra por su nombre, y Ọ̀rúnmìlà los memorizó. Comieron y rompieron los platos. Él salió y les reclamó sus platos por nombre. Los padres le ofrecieron veinte, treinta y cincuenta mil, y él dijo que solo una persona entera pagaba sus platos. Cada padre le dijo a su hija: 'Síguelo'. Así se casó con las tres.", "Ọ̀rúnmìlà y el secreto de Olódùmarè. Ọ̀rúnmìlà quería conocer los secretos de todo y le pidieron poner su ofrenda en la playa. Cuando llegó, Olódùmarè se había quitado la ropa: el mar es su parte más grande, y cuando respira, la marea sube y baja. Olódùmarè sospechó y le preguntó si había visto su secreto. Ọ̀rúnmìlà respondió que solo había visto la orilla. Olódùmarè le dijo: 'De ahora en adelante no habrá nada que no sepas'."], "pasajes": [{"titulo": "Verso 163.1", "texto": "Oes:Ctorà pregunta: ¿Qué es la verdad?\nyunto ¿Qué es la verdad?\nOrimmilà dice\nad es Olúwa\ntierra desde el firmamento.\nỌ̀sá-Òtúrá pregunta: ¿Qué es la verdad?\npregunto: ¿Qué es la verdad?\nDranmilà dice:\n¡ad en el \"Único no visto\"\no la tierra,\nuría emana de Olódumare,\nit sabiduría, mucha sabiduría.\nỌ̀sá-Òtúrá pregunta: ¿Qué es la verdad?\nYo pregunto: ¿Qué es la verdad?\nOranmila dice:\na verdad es el buen carácter de Olódùmarè\niu palabra infalible.\nla verdad.\na verdad es la palabra que no se corrompe.\n1 Dran Poder siempre bendecido.\nlo fue adivinado por Ifa\ntra todos en la tierra.\nHon dijeron que las personas en el mundo\ndebian ser sinceros.", "comentario": "(atowar mgnifica gobernante poseedor del buen carácter. Este verso se refiere a arê", "origen_id": "04461a1a06df8de6058bfe67"}, {"titulo": "Versos complementarios 1 · A", "texto": "Ifá loun pé ire obìnrin fún eléyìn.\n\nOhun eni     ' ò níí nu ni\nKóhun ó un ni\nA díá fún Somúrógé      '                   tíí somo\n                                                   ' ' Alárá\nOhun eni     ' ò níí nu ni\nKóhùn ó nu ni\nA díá fún Sòkùndìgbà    '                       tíí somo\n                                                      ' ' Ajerò\nOhun eni     '       ò  níí     nu     ni\nKóhùn ó nu ni\nA díá fún Somúlùké      '                '\nOmo\n ' ' '      Owáràngún                  àga\nEbo\n' ' n wón        ' ní wón         ' ó se    '\nÀwon          mètèèta            ni    ón   pá    oko                             ´\n        '        ' '' '                '          ' ' ìmònràn'      làwón\n                                                                       ' ó nìi ntàwon '\nEní\n' ó bá le moóko' àwon                         '\nN làwón      ' ó fèé     ''\nAlárá so' tiè' ní Somúrógé         '\nAjerò so' tiè' ní Sòkùndìgbà         '\nOwáràngún\n '                        àgá   '  so    tiè' ní Somúlùké\n                                                      '         '\nWón  '      bá   dàgbà           dàgbà\nWón  ' tó ilé okóó     ' ' ' lo'\nÒrúnmìlà\n '                   ní òun wáá le moóko             ' ' ' won ' báyìí?\nWón  '      ní  kó     rúbo     '\nWón  ' ní kó tójú         ' Awo èkuru funfun méta                  '\nKó lòo    ' ' gbé métèèta    ' ' ' kalè'\nLójú ònà                                         ´\n            ' odò tí ón           ' gbé n lòó        ' ' ponmi\n                                                           '\nKó 